/* ÇEVİRİ ar · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ar","olay",{
"OLAYLAR_EK5:1532-08-05:0":{"b": ["الحملة الألمانية وحصار غونس (كوشيغ)", "8aec937a"], "d": ["سار القانوني بجيشه على النمسا بغرض إجبار شارل الخامس على معركة ميدان؛ وأخّرت قلعة غونس الصغيرة تقدم الجيش بمقاومتها خمسة وعشرين يومًا. ولما لم يخرج الإمبراطور إلى القتال ضرب الأكنجية محيط فيينا وعاد الجيش بسبب تقدم الموسم. ولم تجلب الحملة مكسبًا في الأرض، لكنها أجلست الهابسبورغ إلى المائدة وهيأت أرضية صلح العام التالي.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["معاهدة إسطنبول — أول صلح مع الهابسبورغ", "b085767a"], "d": ["قبل السلطان، وقد استقبل رسول فرديناند كورنيليوس، وقف إطلاق النار، فظهر أول نص صلح رسمي بين العثمانيين والنمسا. وبموجب المعاهدة قبل فرديناند أن يدفع ضريبة سنوية مقابل الأراضي المجرية التي في يده، وعُدّ أرشيدوق النمسا في البروتوكول مساويًا للصدر الأعظم. وكانت هذه المكانة غير المتكافئة تعبيرًا صريحًا عن دعوى التفوق التي حملتها الدبلوماسية العثمانية في القرن السادس عشر.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["الاستيلاء على قارص وانفتاح الحدود الشمالية الشرقية", "742e3101"], "d": ["بينما كان الرتل الطليعي لحملة العراقين يتجه شرقًا من أرضروم، سُلّمت قلعة قارص، التي كانت في يد الأتابكية الجورجية وبقيت خربة منذ تيمورلنك، دون مقاومة. وكانت المدينة تُعدّ مفتاح الباب الشمالي المفتوح على إيران لأنها تمسك الممر بين قوس آراس وجلدير. وكان هذا المكسب الحلقة الأولى في ولاية قارص التي ستؤسس بعد ثلاثين سنة وفي خط القوقاز.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["الدخول الأول إلى تبريز — افتتاح حملة العراقين", "cf7ed4e3"], "d": ["دخل إبراهيم باشا، الذي تحرك أولًا بصفة سر عسكر، العاصمة الصفوية تبريز دون مقاومة بعد أن تجنب الشاه طهماسب معركة ميدانية وانسحب إلى الداخل. ووصل القانوني أيضًا إلى المدينة في أيلول/سبتمبر؛ غير أن الجيش اتجه نحو بغداد بسبب هجوم الشتاء وطول خط التموين الشديد، ولم تُحفظ تبريز طويلًا. وكانت المدينة التي استُولي عليها للمرة الثانية بعد جالديران المكان الذي تعلمت فيه الدولة العثمانية أن الاستيلاء في الشرق سهل وأن الاحتفاظ به صعب.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["فتح بربروس لتونس", "d8754216"], "d": ["اتجه قبطان باشا بربروس خير الدين باشا إلى تونس بعد أن ضرب سواحل إيطاليا بأسطوله، فأجبر حاكم الحفصيين مولاي حسن على الفرار ودخل المدينة. وقلب أخذ تونس، بموقعها المسيطر على مضيق صقلية، ميزان القوى في غرب المتوسط لصالح العثمانيين في لحظة. غير أن هذه السيطرة لن تدوم طويلًا، إذ سيرد شارل الخامس في العام التالي بأسطول كبير.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["خسارة تونس لصالح شارل الخامس", "a691f0f8"], "d": ["أخذ شارل الخامس تونس بعد أن أسقط حلق الوادي بحملة كبيرة دعمتها أساطيل جنوة والبابوية، وأعاد مولاي حسن إلى العرش تحت الحماية الإسبانية. ووُضعت في المدينة حامية إسبانية، فأُوقف تقدم العثمانيين في وسط المتوسط مؤقتًا. ولن يتيسر الفتح القطعي لتونس إلا بعد أربعين سنة، في 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["عمليات غازي خسرو بك على طول السافا: بوسنة برود وياسينوفاتس", "3740ec83"], "d": ["بعد الاستيلاء على يايتسه وبانيالوكا عام 1528، ظلت القلاع على طول نهر السافا مدة أخرى على الحد الكرواتي السلافوني التابع للتاج الهابسبورغي. وفي عام 1536 صار غازي خسرو بك سنجق بك البوسنة للمرة الثالثة، فاستولى في العام نفسه على بوجيغا وما حولها، وضم قلعتي برود وياسينوفاتس على ضفة السافا إلى الإدارة العثمانية. وهكذا بلغ الحد الشمالي للبوسنة السافا؛ واكتملت المنطقة بعد سنتين بالاستيلاء على دوبيتسا.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["إعدام إبراهيم باشا المقبول", "348aa7b8"], "d": ["أُعدم إبراهيم باشا، الذي شغل الصدارة العظمى ثلاث عشرة سنة وكان أقرب أصدقاء القانوني والرجل الثاني الفعلي في الدولة، خنقًا في القصر الذي دُعي إليه للإفطار دون ذكر أي مبرر. ويُعدّ موقفه في حملة العراقين واستعماله لقب 'السردار السلطان' وتوازنات القصر مؤثرة في موته. والإعدام منعطف يبين أن الصدور العظام في الإدارة المركزية العثمانية لا أمان مطلقًا لهم.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["فتح قلعة كليس وتأسيس سنجق دلماسيا", "6ffd4ebf"], "d": ["أخذ مراد بك، كتخدا غازي خسرو بك المهتدي الكرواتي الأصل، قلعة كليس الاستراتيجية الواقعة شمال سبليت مباشرة من البندقية. وبعد الفتح مباشرة جُعلت كليس مركز سنجق وقضاء جديد يشمل ما حولها؛ ورسمت حدود هذا السنجق في معظمها إطار كرواتيا العثمانية. وأكمل هذا الفتح، الذي جاء بعد خمس عشرة سنة من كنين، الهيكل الإداري لداخل دلماسيا.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["حصار كورفو والحرب مع البندقية", "11af95bd"], "d": ["أنزل الجيش العثماني بعد حملة أبوليا (Apulia) جنودًا في كورفو وحاصر قلعة الجزيرة البندقية القوية. وبسبب وعورة القلعة والخسائر الفادحة وظروف الموسم رُفع الحصار وانسحب في 6 أيلول/سبتمبر. ومع أن الحصار لم يسفر عن شيء، فإن الحرب التي بدأت مع البندقية انتهت بانضمام عدد كبير من الجزر في إيجه والأدرياتيك إلى العثمانيين وبانتصار بريفيزه في العام التالي.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["حملة بربروس على إيجه: الاستيلاء على الجزر التابعة مباشرة للبندقية", "1b32ed96"], "d": ["تسلّم الأسطول العائد من حصار كورفو، مستفيدًا من إعلان الحرب على البندقية، الجزر في إيجه التابعة مباشرة للبندقية لا للدوقية، واحدة بعد أخرى. وضُبطت إجينا بعد مقاومة شديدة، واستسلمت أستيباليا التي كانت في يد أسرة كويريني وكاربثوس وكاسوس، وقبلت باتموس الخاضعة لإدارة الدير الحماية العثمانية أيضًا. أما دوقية ناكسوس فرُبطت بالجزية وتُركت في مكانها؛ وكان ضمها سيتأخر إلى عام 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["حملة بربروس على شمال إيجه: الاستيلاء على سكيروس وسبوراديس الشمالية", "20ab688e"], "d": ["في الطريق إلى بريفزة، تسلّم الأسطول الواحدة بعد الأخرى جزر شمال إيجه التي لجأت إلى البندقية بعد فتح القسطنطينية. وبذلك دخلت سكيروس شمال إغريبوز وسكياثوس وسكوبيلوس وألونيسوس، التي تمسك مدخل خليج سالونيك، في الإدارة العثمانية. وسدّت هذه الجزر آخر فراغ في شمال إيجه ظل في يد البندقية ثماني وستين سنة أخرى رغم أن إغريبوز استُولي عليها عام 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["الاستيلاء على عدن وضم ساحل اليمن", "e7d46d8f"], "d": ["اتجه الأسطول الذي أبحر من السويس لحملة الهند أولًا إلى ساحل اليمن، لأنه لا يمكن الخروج إلى المحيط دون تأمين البحر الأحمر. ودخل خادم سليمان باشا ميناء عدن في 3 آب/أغسطس 1538؛ وأُحضر حاكم الطاهريين عامر بن داود، الذي مال إلى البرتغاليين، إلى باب القبطان وأُعدم، وتُرك في المدينة حرس من 500 شخص. وفي أثناء الحملة نفسها سُلّمت المخا وجزيرتا كمران وفرسان المسيطرتان على المضيق، ووُضع أساس ولاية اليمن. وهكذا امتلكت الدولة العثمانية لأول مرة الساحل الشمالي لباب المندب بأكمله؛ أما صنعاء والمناطق الداخلية فكان عليها الانتظار تسع سنوات أخرى.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["حملة البغدان وضم منطقة بوجاق (بندر)", "90a88a56"], "d": ["في الحملة التي خرجت على فوييفود البغدان بيترو رارش لعدم وفائه بالتزاماته العثمانية أُخذت سوتشافا، ونهب خان القرم صاحب كراي مدينة ياش. وأقام السلطان تشكيرغه ستيفان على الفويفودية، وضمّ منطقة بوجاق (جنوب بسارابيا) مع بندر إلى الأراضي العثمانية مباشرة. وكان هذا الضم إحدى الحلقات التي جعلت سواحل شمال غرب البحر الأسود بحرًا داخليًّا عثمانيًّا. وكانت البغدان أصلًا فويفودية تابعة للعثمانيين؛ فلم تأخذ هذه الحملة أرضًا من دولة أجنبية، بل أخذت الإدارة الداخلية لبندر وبوجاق من الفويفود وربطتها بالسلطان مباشرة؛ وبقيت بقية الفويفودية على وضعها التابع. وسيتكرر البناء نفسه في 1484 في كيلية وأق كرمان وفي 1713 في خوتين: قلاع الحدود مباشرة والأراضي الداخلية تابعة.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["تسلّم أنابولي (نافبليو) بموجب المعاهدة", "104d0937"], "d": ["انتهت الحرب مع البندقية التي دامت ثلاث سنوات بعد بريفزة بقبول الجمهورية التخلي عن آخر قلعتيها في المورة. وسُلّمت أنابولي وبنفشه، اللتان لم يمكن الاستيلاء عليهما بالحصار، إلى الدولة العثمانية على المائدة، إضافة إلى تعويض حرب قدره ثلاثمائة ألف دوقية. وبذلك اتحدت شبه جزيرة المورة دون أن يبقى فيها أثر قدم بندقية واحدة.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["دخول سغدين في الإدارة العثمانية وتشكيل لواء سغدين", "019aa000"], "d": ["بعد أن أُقيمت الإدارة العثمانية في بودين إقامة تامة عام 1541، اعتنق وجهاء سغدين سيادة فرديناند الأول واستعدوا للدفاع المسلح. واستدعى بكلربك بودين كوجك بالي باشا حكام المدينة في مطلع 1543 وأعدمهم بحجة الخيانة، ثم أرسل قوة للاستيلاء على المدينة. وفي هذه الأثناء شُكّل لواء سغدين وعُيّن ابن بالي باشا درويش بك أول سنجق بك فيه؛ وكان اللواء يمتد في البداية بين الدانوب والتيسا.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["فتح فالبو وشيكلوش وبيتش", "2ca030a3"], "d": ["كان الهدف الأول لحملة المجر التي انطلقت بعد سنتين من ضم بودين تأمين الجناح الجنوبي للإيالة الجديدة بين الدراف والدانوب. وبعد الاستيلاء على قلعتي فالبو وشيكلوش، استسلمت بيتش مركز بارانيا. وستصبح المدينة أكثر مراكز المجر العثمانية ازدحامًا بالسكان وعمرانًا، وسيأخذ المؤرخ إبراهيم البيتشوي اسمه منها.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["فتح إسترغون وإستولني بلغراد", "efca9e05"], "d": ["في حملة المجر التي خرج إليها القانوني بنفسه دخلت إسترغون، المركز الديني لمملكة المجر ومدينة رئاسة الأساقفة، في الإدارة العثمانية بعد حصار دام أسبوعين ونصفًا. ثم أُخذت إستولني بلغراد، مدينة تتويج الملوك المجريين، واكتمل نطاق الدفاع لولاية بودين. وبقيت إسترغون قلعة مفتاحية لخط الدانوب في يد العثمانيين حتى 1595.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["حزام الدفاع الشمالي والغربي لبودين: فاتس وهتفان وشيمونتورنيا", "733ee5ce"], "d": ["بعد الاستيلاء على إستركون وإشتولني بلغراد، تحرك بكلربك بودين دون حملة سلطانية لإكمال حلقة القلاع المحيطة بالعاصمة. وسُلّمت فاتس عند منعطف الدانوب، وهتفان بوابة السهل المجري، وشيمونتورنيا على خط شيو، واحدة بعد أخرى. وحوّلت مكاسب هذه السنة الهادئة بودين من مدينة ثغر إلى مركز إيالة سيصمد مائة وأربعين سنة.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["ضم البصرة والوصول إلى الخليج العربي", "02f87c11"], "d": ["عند فتح بغداد (1534) كان حاكم البصرة راشد بن مغامس قد أعلن طاعته للقانوني، وأرسل مفاتيح المدينة عام 1538. وحين وقف خلفه الشيخ يحيى في وجه العثمانيين، سار بكلربك بغداد أياس باشا براً، وسار سنجق بك الموصل بـ120 سفينة عبر الفرات؛ ودخل أياس باشا البصرة في 26 كانون الأول/ديسمبر 1545 وصارت المدينة مركز بكلربكية. وكان هذا الميناء عند مصب شط العرب البوابة التي انفتحت منها الدولة العثمانية على الخليج الذي كانت البرتغال تسيطر عليه من هرمز؛ واعترفت إيران أيضًا بهذا الوضع بمعاهدة أماسيا عام 1555.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["فتح صنعاء وداخل اليمن", "d31ded85"], "d": ["بعد تعز استُولي على صنعاء أيضًا، وارتبطت البلاد بأسرها بالبكلربكية. غير أن هذه السيادة لم تكن مريحة قط بسبب وعورة الجغرافيا والاختلاف المذهبي؛ وصارت اليمن جبهة تلتهم الجنود باستمرار بالنسبة إلى الدولة العثمانية.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["فتح تعز", "d4509df9"], "d": ["في اليمن، التي اكتُفي فيها قبل تسع سنوات بالشريط الساحلي، ومع ازدياد قوة الأئمة الزيديين في المناطق الجبلية الداخلية، صعدت قوات أوزدمير باشا إلى الهضبة وضبطت تعز.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-18:0":{"b": ["معاهدة إسطنبول — صلح لخمس سنوات مع الهابسبورغ", "41f81773"], "d": ["وُقّع بين العثمانيين والهابسبورغ صلح لمدة خمس سنوات؛ وقبل فرديناند أن يدفع 30.000 دوقية في السنة مقابل الأراضي المجرية التي في يده. وسجلت المعاهدة قانونيًّا الوضع الفعلي لتقسيم المجر إلى ثلاثة أقسام. وأتاح تأمين الجبهة الغربية بذلك للقانوني تنظيم حملات جديدة على إيران.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["حملة إيران الثانية وإعادة الاستيلاء على تبريز", "e82365df"], "d": ["في الحملة التي انطلقت بتشجيع القاص ميرزا، أخي الشاه طهماسب الذي تمرد عليه ولجأ إلى إسطنبول، دخل الجيش تبريز للمرة الثانية. ولأن الصفويين لم يخوضوا معركة ميدانية مرة أخرى وانسحبوا محرقين الأرض، لم يمكن البقاء في المدينة إلا بضعة أسابيع. وحسمت الحملة أن تبريز لا يمكن الاحتفاظ بها، ووجّهت الاستراتيجية العثمانية إلى إقامة خط حدودي دائم، أي إلى تحصين وان.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["فتح وان وتثبيت الحد الشرقي", "fc8f930b"], "d": ["كانت قلعة وان، التي حوصرت في أثناء العودة من تبريز، بموقعها المرتفع على صخرة عند الشاطئ الشرقي للبحيرة القفل الذي لا جدال فيه للمنطقة، وسلّمت بعد حصار قصير. وجُعلت المدينة على الفور مركز بكلربكية، وربطت بها سناجق أرجيش وعادلجواز وحكاري. وعلى خلاف تبريز احتُفظ بوان، وبقيت أربعة قرون أبعد موقع دائم للعثمانيين في الشرق.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["ضم الأحساء والقطيف — ساحل الجزيرة العربية في الخليج", "f6701e60"], "d": ["بعد الاستيلاء على البصرة، استُولي على القطيف التي صارت موقعًا أماميًا للبرتغاليين على الساحل الغربي للخليج، وأُسست مع واحات الأحساء الداخلية بكلربكية جديدة. وكانت هذه نقطة انطلاق العمليات الموجهة إلى البحرين وهرمز. وهكذا صار للدولة العثمانية كلمة في وقت واحد على ساحلي شبه الجزيرة العربية، البحر الأحمر والخليج العربي.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["فقدان شهرزور — ميل أمير أردلان سهراب إلى الصفويين", "5600efc9"], "d": ["كانت منطقة شهرزور، التي اعترفت بالإدارة العثمانية في أثناء حملة العراقين (1535)، تحت حكم أمير أردلان بيجه بك المقيم في قلعة زلم. وبعد وفاة بيجه بك عام 1550، استولى أخوه سهراب على قلعة زلم وسيطر على الإمارة، ومال إلى الصفويين وانفصل عن الطاعة للدولة العثمانية؛ فخرجت منطقة شهرزور بذلك من النفوذ العثماني. ولم تُسترد المنطقة إلا في أثناء حملة نخجوان عام 1554، بحصار قلعة زلم والاستيلاء عليها.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["الاستيلاء على أردهان وحوض جلدير", "14c9eb76"], "d": ["اتجه بكلربك أرضروم، في أثناء الحرب المستمرة مع الصفويين، إلى أراضي الأتابكة الجورجيين في منحنى الكر، فضم أردهان ومحيط جلدير إلى الإدارة العثمانية. وهكذا اكتمل خط قارص — أردهان، وخضعت للرقابة الهضاب المفتوحة على جورجيا في الشمال الشرقي. وسيكتمل النظام الإداري النهائي للمنطقة بإيالة جلدير التي ستؤسس بعد سبع وعشرين سنة.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["عبور صوقوللو محمد باشا الدانوب — بدء حرب ترانسلفانيا", "38fde931"], "d": ["إثر الفوضى التي تسبب بها الراهب مارتينوتزي، وصي ملك ترانسلفانيا الصغير يانوش زيغمونت، وتخلي ترانسلفانيا عن قلاع البنات لفرديناند، رُئي أن حملة جديدة ضرورية؛ وأُسندت القيادة إلى بكلربك الروميللي صوقوللو محمد باشا. وعبر الجيش الدانوب رغم مساعي مارتينوتزي للمماطلة، واستولى على بيتشه وبيتشكرك وتشاناد وليبا؛ غير أن حصار تيميشوارا رُفع في 16 تشرين الثاني/نوفمبر بسبب البرد. وهكذا افتُتحت حرب عثمانية هابسبورغية جديدة في المجر.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["استيلاء جيش كاستالدو النمساوي على مدينة ليبوفا (ليبا) — سلّمت القلعة في 5 كانون الأول/ديسمبر", "a0e1ff0d"], "d": ["حاصر جيش الجنرال كاستالدو في 4 تشرين الثاني/نوفمبر ليبوفا التي استولى عليها صوقوللو محمد باشا في تشرين الأول/أكتوبر 1551؛ وبعد يومين وقعت المدينة في يد النمساويين. ودافع أولاما باشا بحامية من 5.000 رجل عن القلعة تسعة أيام أخرى وخرج منها باتفاق في 5 كانون الأول/ديسمبر 1551. وظلت ليبوفا في يد الهابسبورغ حتى سقوط تيميشوارا عام 1552.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["القوات المرسلة من تيمشوارة تمسك بلانكات البانات الجنوبية — فيرشيتس وهارام وكيفه", "edca0921"], "d": ["اتجهت الفرق التي انفصلت عن جيش الحصار بعد استسلام تيمشوارة للجيش العثماني إلى بلانكات البانات الصغيرة؛ وبحسب رواية بانلاكي أمسكت هذه القوات بلانكات فيرشيتس وفاتشت ومهاديا وتشاكوفار وهارامفار وكيفه. وبذلك وقعت هارام الواقعة على ضفة الدانوب في يد العثمانيين أيضًا.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["فتح سولنوك وفشل حصار إغري", "a7156e8f"], "d": ["بعد الاستيلاء على تيميشوارا، استولى الجيشان العثمانيان المتحدان على سولنوك على نهر تيسا شبه دون قتال، إذ ترك الحراس المرتزقة القلعة. أما قلعة إغري التي حوصرت بعد ذلك فلم يمكن الاستيلاء عليها أمام صمود حامية من ألفي رجل بقيادة إشتفان دوبو ثمانيًا وثلاثين يومًا، وانسحب الجيش مع حلول الشتاء. وكان سقوط قلعة وصمود أخرى في الحملة نفسها أول علامة واضحة على أن الحد في المجر لم يعد يتقدم من تلقاء نفسه لمصلحة العثمانيين.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["التحالف العثماني - الفرنسي — وضع الأسطول الفرنسي تحت أمر العثمانيين", "a8e01b22"], "d": ["وُضع الأسطول الفرنسي بموجب معاهدة 1 شباط/فبراير 1553 تحت أمر الأسطول العثماني؛ وتُصوّر عمل مشترك في غرب المتوسط ضد إسبانيا. وبعد المعاهدة خرج طرغد رئيس في 15 حزيران/يونيو 1553 بخمس وأربعين قادسًا لدعم فرنسا. وكانت هذه أول معاهدة تحالف رسمية نقلت الأرضية التجارية لامتيازات 1536 إلى تعاون عسكري.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["إعدام الأمير مصطفى في أرغلي قونية", "dec36858"], "d": ["دخل الأمير مصطفى سرادق أبيه ليلتحق بالجيش المجتمع لحملة نخجوان، فواجه الجلادين وهو آتٍ للمثول بين يديه، وخُنق وقُتل. وأثار قتل ولي العهد المحتمل، الذي كان محبوبًا جدًّا في الجيش، غضبًا عميقًا بين الإنكشارية، وعُزل رستم باشا من الصدارة. وانتقلت الواقعة إلى الأدب والذاكرة الشعبية بوصفها من أكثر منعطفات سياسة الأمراء العثمانية إثارة للجدل.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["نقل حد إبريم والنوبة جنوبًا", "c57d5d77"], "d": ["نُقل الحد الجنوبي لبكلربكية مصر إلى ما وراء الشلال الثاني بتحصين قلعة إبريم، التي ترتفع على رأس صخري على النيل، على يد أوزدمير بك وضم النوبة السفلى ضمًّا تامًا إلى مصر العثمانية. (كان التنظيم الإداري العثماني في إبريم قد أُسس بعد فتح مصر؛ وتُظهر الخريطة إبريم عثمانية منذ 1517. وهذه السنة تقريبية، والمصدر لا يذكر سنة.) وكانت القلعة سدًّا ضد الغارات القادمة من النوبة، وكذلك نقطة مراقبة لطريق الذهب والرقيق المتجه إلى سنار. وكانت الحامية البوسنية التي وُضعت هنا دائمة إلى حد أن أحفادها كانوا لا يزالون في القلعة بعد ثلاثمائة سنة. وتقدم المصادر روايتين مختلفتين عن وقت دخول إبريم في الإدارة العثمانية: فمادة «السودان» في TDV تربط انضمام النوبة السفلى إلى مصر العثمانية بحملة أوزدمير باشا في منتصف القرن السادس عشر، بينما تذكر مادة «النوبة» أن المنطقة حتى وادي حلفا والتنظيم الإداري في إبريم أُسسا فور فتح 1517. وربط سنجق إبريم بإيالة الحبشة في 26 تموز/يوليو 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["الاستيلاء على بجاية (بوجي) من الإسبان", "49691cda"], "d": ["استسلمت بجاية، التي كانت في يد إسبانيا منذ ثلاث وأربعين سنة والتي تقسم الساحل بين الجزائر وقسنطينة إلى قسمين، بعد حصارها برًا وبحرًا. وبسقوط القلعة صار ساحل أوجاق الجزائر متصلًا بلا انقطاع حتى وهران. وأثار هذا الفقدان في إسبانيا سخطًا شديدًا إلى حد أن القائد ألونسو دي بيرالتا الذي سلّم القلعة أُعدم في وطنه.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["ضم زيلع إلى إيالة الحبشة", "7bbf369a"], "d": ["ضُمّ ميناء زيلع، على الساحل الإفريقي لخليج عدن في الطرف الجنوبي لإيالة الحبشة، إلى الإدارة العثمانية. وكانت هذه المدينة، باب سلطنة عدل المفتوح على البحر، آخر نقطة تموين للسفن الخارجة من باب المندب. وبانضمام زيلع بلغ حد الدولة العثمانية في إفريقيا أقصى نقطة له في الجنوب.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["معركة الأمراء في قونية", "1c8de387"], "d": ["جاء الأمير بايزيد، الذي دخل في الصراع على العرش، إلى قونية بقوة تبلغ نحو 30.000 رجل، وهُزم أمام أخيه الأمير سليم في اشتباك دام يومين. وفرّ بايزيد المهزوم عبر أماسيا إلى إيران ولجأ إلى الشاه طهماسب. وحوّلت المعركة أزمة وراثة العرش في السنوات الأخيرة للقانوني إلى مسألة سياسة خارجية.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["الانتصار البحري في جربة", "c7b905c1"], "d": ["شتت الأسطول العثماني بقيادة بيالة باشا أسطول الحلفاء الإسباني - الجنوي - المالطي الذي تجمع لاسترداد طرابلس، بمناورة الانقسام إلى قسمين أمام جربة. وفقد الحلفاء معظم أساطيلهم، وسقطت القلعة في الجزيرة في وقت قصير. وتُعدّ جربة ثاني انتصار بحري كبير بعد بريفيزه رسّخ تفوق العثمانيين في المتوسط.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["إعدام الأمير بايزيد في قزوين", "a759de14"], "d": ["سلّم الشاه طهماسب الأمير بايزيد، الذي لجأ إلى إيران، إلى الوفد العثماني بعد مساومات طويلة، وخُنق وقُتل مع أبنائه الأربعة. وحصل الصفويون مقابل التسليم على تنازلات مادية مهمة وضمان للحدود. وبهذا الإعدام زالت آخر عقبة أمام جلوس سليم الثاني على العرش، وحُفظ نظام الصلح في معاهدة أماسيا.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["الاستيلاء على خيوس من الجنويين", "a4559b96"], "d": ["تسلّم بيالة باشا خيوس، التي كانت تُدار منذ مائتي سنة مستعمرة تجارية تابعة لأسرة جوستنياني الجنوية وتدفع الجزية للدولة العثمانية، دون إطلاق رصاصة واحدة، بحجة تأخرها في دفع الجزية وإيوائها سفن العدو. وصُفي مع خيوس وبسارا آخر وجود جنوي على الساحل الشرقي لإيجه. وبقيت لأهل خيوس صناعة المصطكى وامتيازاتهم، وربطت الجزيرة بإيالة جزائر بحر سفيد.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["ضم دوقية ناكسوس — جزر كيكلاديس بأسرها", "68f0ec0b"], "d": ["أُلغيت دوقية ناكسوس اللاتينية، القائمة منذ عام 1207 والتي تدفع الجزية للدولة العثمانية منذ عام 1537، محتجين بالشكاوى التي وردت بعد أن ظلم آخر دوقاتها جياكومو كريسبو شعبه. وأُخضعت ناكسوس وباروس وطينوس وأندروس وسيروس وميكونوس وإيوس وأنافي وجميع جزر كيكلاديس المحيطة بها، بقرار واحد، للإدارة العثمانية المباشرة. وأسند القانوني إدارة الجزر مدة إلى يوسف ناسي؛ وهكذا انتهى في وسط إيجه الحكم اللاتيني الذي دام ثلاثة قرون ونصف.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["تمرد اليمن وحملة قوجه سنان باشا على اليمن", "c8218d8e"], "d": ["ثار الإمام الزيدي المطهر بحجة جمع الضرائب بالقوة، فاقتلع الإدارة العثمانية من معظم اليمن. وأعاد قوجه سنان باشا، الذي أُرسل من إسطنبول، السيادة العثمانية في المنطقة بعملية قادها بين 1568 و1570 أخذ فيها كوكبان بعد حصار طويل. وكانت الحملة ذات أهمية حيوية للحفاظ على الرقابة على البوابة الجنوبية للبحر الأحمر وطريق تجارة المحيط الهندي.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["تحالف دفاعي مع سلطنة آتشيه ومساعدة المحيط الهندي", "8e835f24"], "d": ["قدّم وفد آتشيه، الذي طلب العون من القانوني أمام الهجمات البرتغالية، ولاءه لسليم الثاني عند وفاة السلطان في زيغتوار، ووُقّعت معه معاهدة دفاعية. وأمر السلطان بإرسال المدافع والبنادق والذخيرة والصناع من الإسكندرية؛ وجُهزت سبع عشرة سفينة حربية لتُرسل إلى مياه الهند. وحال اتساع تمرد اليمن دون خروج الأسطول، لكن المدفعيين والصناع العثمانيين الذين بلغوا آتشيه تركوا أثرًا دائمًا في المنطقة.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["إنزال قبرص: الاستيلاء على ليماسول", "9074ccc9"], "d": ["استولى الجيش العثماني، النازل على الجزيرة، على ليماسول دون مقاومة تُذكر، وتوجه في اليوم التالي إلى لارنكا. وبفضل عدم رضا الأهالي عن الإدارة البندقية ومساعدتهم القوات العثمانية، لم تُواجَه مقاومة جدية في لارنكا أيضًا؛ وجُعلت إسكلة توزلا قاعدة إنزال للجنود والعتاد. وكانت البندقية قد حشدت دفاعها في لفكوشة وماغوسا؛ ولم يعلن والي بافوس طاعته للسردار إلا بعد سقوط لفكوشة.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["فتح نيقوسيا", "413d866b"], "d": ["سلمت نيقوسيا، عاصمة قبرص التي كانت تحت الإدارة البندقية، للجيش العثماني بعد حصار بدأ في 25 تموز/يوليو 1570 ودام خمسة وأربعين يومًا. وحصر سقوط مركز الجزيرة المقاومة البندقية في قلعة فاماغوستا. وأثار الفتح صدى كبيرًا في الغرب وعجّل العملية المؤدية إلى تشكيل أسطول العصبة المقدسة بقيادة البابا.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["استسلام كيرينيا — الساحل الشمالي لقبرص", "39fdeea5"], "d": ["كسر سقوط لفكوشة في 9 أيلول/سبتمبر بإعمال السيف المقاومة في شمال قبرص. واستسلمت قلعة كيرينيا الواقعة وراء جبال بيشبارماق استسلامًا مشروطًا بعد ثمانية أيام لما علمت بمصير العاصمة، وأُذن لحاميتها بمغادرة الجزيرة. ولم يبقَ العلم البندقي في الجزيرة إلا في ماغوسا؛ وستصمد هي أيضًا أحد عشر شهرًا أخرى.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["إعادة بناء الأسطول بعد ليبانتو", "db51fe44"], "d": ["كان أول عمل قلج علي باشا، الذي عُيّن قبطان باشا بعد هزيمة إينه بختي، إعادة بناء الأسطول الذي تكبد خسائر فادحة؛ وعملت الترسانات دون انقطاع طوال شتاء 1571-1572. وخرج في حزيران/يونيو 1572 إلى المتوسط أسطول جديد مؤلف من نحو 250 قادسًا و300 قادس لرؤساء متطوعين. وأظهر هذا التعافي السريع أن إينه بختي لم تكسر القوة البحرية العثمانية كسرًا دائمًا.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["معاهدة إسطنبول مع البندقية — الاعتراف بقبرص", "4d08ef50"], "d": ["عقدت البندقية، التي بقيت وحدها بعد تفكك العصبة المقدسة، صلحًا منفصلًا مع العثمانيين، فاعترفت رسميًّا بأن قبرص عثمانية وقبلت دفع تعويض حرب. وبيّنت المعاهدة بوضوح أن انتصار إينه بختي لم يحقق للعالم المسيحي مكسبًا سياسيًّا. وستتجنب البندقية بعد ذلك الدخول في حرب مباشرة مع العثمانيين سبعين سنة.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["وفاة سليم الثاني", "c289f5ee"], "d": ["لم يستطع سليم الثاني أن يحضر الديوان نحو شهرين بعد سقوطه، وتوفي. وأُخفي موته اثني عشر يومًا في القصر إلى أن جاء ابنه الأكبر مراد من مانيسا إلى إسطنبول. وتختلف المصادر في يوم الوفاة: يقول سلانيكي 15 كانون الأول/ديسمبر؛ ويقول غيرلاخ ومحمد بن محمد وجنابي 13 كانون الأول/ديسمبر.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["إعلان وفاة سليم الثاني وجلوس مراد الثالث", "84334d70"], "d": ["أُعلن رسميًّا في 22 كانون الأول/ديسمبر 1574 موت سليم الثاني وجلوس مراد الثالث الذي جيء به من مانيسا. وسيبقى السلطان الجديد على العرش واحدًا وعشرين عامًا، وستُذكر سلطنته بحروب إيران الطويلة في الشرق وعشية الحرب الطويلة في الغرب وبتخفيض عيار الأقجة في الداخل. واستمر النظام القديم في إدارة الدولة حتى وفاة صوقوللو محمد باشا عام 1579.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["معركة وادي المخازن (القصر الكبير) — عبد الملك المدعوم عثمانيًّا يبيد الجيش البرتغالي", "21280dac"], "d": ["أباد عبد الملك، الذي جلس على عرش المغرب بدعم عثماني، الجيش الكبير لملك البرتغال سباستيان في وادي المخازن؛ ولأن ثلاثة ملوك ماتوا معًا في المعركة تُسمى في المصادر الغربية 'معركة الملوك الثلاثة'. وانهارت القوة العسكرية للبرتغال وسقطت البلاد بعد قليل في يد إسبانيا. وتوفي عبد الملك أيضًا في المعركة؛ وأبلغ أخوه أحمد المنصور الذي خلفه إسطنبول بالانتصار بوفد. وبقيت العلاقة بين الدولتين على مستوى تبادل السفراء والهدايا، لا الجزية أو التبعية، وتوترت بعد قليل بسبب مسألة الهدايا.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["إعلان أهل دربند الولاء للالا مصطفى باشا — دمير قابي في الإدارة العثمانية", "9c55aeff"], "d": ["في أثناء حملة شروان، ذهب وفد من سبعة أشخاص من أهل دربند إلى السردار للالا مصطفى باشا المقيم في إريش وأعلن الولاء. وأدى دربند (دمير قابي)، الذي يسد الممر الضيق بين سور القوقاز وبحر قزوين، بوصفه ممر الطرق البرية القادمة من الشمال الإجباري، دورًا محوريًا في الاحتفاظ بشروان. واستمرت السيادة العثمانية هنا حتى عام 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["فتح شروان: الاستيلاء على شماخي", "9afae4c1"], "d": ["دخل الجيش، الذي انفتح على القوقاز بعد انتصار جلدير، شروان، أغنى إيالات الصفويين على ساحل بحر قزوين، واستولى على مدينة المركز شماخي. وعُيّن أوزدمير أوغلو عثمان باشا بكلربكًا هنا، وأُدخل الفرع الشمالي لطريق الحرير تحت الرقابة العثمانية. وستصبح شروان أكثر جبهات حرب الشرق، التي ستدوم اثنتي عشرة سنة، تداولًا بين الأيدي وأغلاها كلفة.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["الاستيلاء على باكو — الوصول إلى ساحل قزوين", "eb5adab8"], "d": ["استُولي على ميناء باكو على الساحل الغربي لبحر قزوين بوصفه آخر حلقة في عملية شروان. وكانت آبار النفط حول المدينة مصدر دخل معروفًا حتى في ذلك العهد، وكان الميناء نقطة تصدير الحرير الإيراني القادم عبر بحر قزوين. وهكذا صارت الدولة العثمانية، للمرة الأولى والوحيدة في تاريخها، صاحبة ساحل على بحر قزوين.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["فتح ريفان (إريفان) وبناء القلعة", "7f623b7b"], "d": ["سار فرهاد باشا، الذي تلقى الأمر في قارص بالذهاب إلى ريفان وبناء قلعة فيها، على ريفان، وأُخضعت المدينة للسيطرة العثمانية في مطلع رمضان 991 (منتصف أيلول/سبتمبر 1583). وبُنيت في ريفان، التي تمسك الباب الشمالي لوادي آراس، قلعة جديدة كبيرة، وجُعلت المدينة مركز بكلربكية. وكانت ريفان، القائمة في منتصف طريق الجيش بين قارص وتبريز، العمود الفقري اللوجستي للجبهة الشرقية. وبُنيت القلعة متينة إلى درجة أنها صارت الهدف الثابت للحروب العثمانية الإيرانية في القرنين التاليين.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["ضم قره باغ وكنجة", "29abaead"], "d": ["كآخر مكسب في حرب الشرق التي دامت عشر سنوات، سار فرهاد باشا عام 1588 على كنجة ودخل المدينة في 1 أيلول/سبتمبر؛ وأُخضعت منطقة قره باغ بين الكر وآراس ومركزها كنجة للإدارة العثمانية. وهكذا اتحدت شروان وريفان وقره باغ فتشكل في القوقاز خط عثماني متصل. وستسجل معاهدة فرهاد باشا الموقعة عام 1590 هذا الحد، غير أن المكسب لن يُحفظ إلا عشرين سنة.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["فتح بيهاتش", "651a7275"], "d": ["بعد أن أخذ بكلربك البوسنة تللي حسن باشا ريباتش، القلعة الأمامية لبيهاتش، في تشرين الثاني/نوفمبر 1591، استولى في 1592 على المدينة والقلعة نفسها؛ وسلّم القائد لامبرغ بعد حصار دام عشرة أيام. وأدى هذا الفتح إلى دفع حدود البوسنة إلى الأمام على امتداد نهر أونا، وكان آخر مكسب عثماني كبير عشية الحرب الطويلة التي ستندلع بعد سنة باستشهاد تللي حسن باشا أمام كولبا.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["بدء 'الحرب الطويلة' العثمانية - النمساوية", "bd22c392"], "d": ["أعلنت الدولة العثمانية الحرب على النمسا بعد هزيمة بكلربك البوسنة تللي حسن باشا واستشهاده أمام كولبا (سيساك)، وبدأت الحرب الطويلة التي ستدوم ثلاث عشرة سنة. وعجّلت هذه الحرب، التي كان المشاة المسلحون بالأسلحة النارية حاسمين فيها، في استخدام السكبان والجنود حاملي البنادق في نظام الجيش العثماني، وعمّقت تراجع السباهية أصحاب التيمار. وستنتهي الحرب بمعاهدة زيتفاتوروك عام 1606.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["خروج قوجه سنان باشا في حملة النمسا — الحملة الأولى للحرب الطويلة", "d4a2f46d"], "d": ["أقنع الصدر الأعظم قوجه سنان باشا، بعد هزيمة بكلربك البوسنة حسن باشا أمام سيسكا (Sisak) واستشهاده، السلطان بالحرب بكلام لامع ووعود، وخرج مع 12.000 إنكشاري وفرق أخرى. وهكذا فُتحت الحملة الأولى للحرب العثمانية - النمساوية التي ستدوم ثلاث عشرة سنة.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["فتح يانق قلعة (غيور)", "14b75207"], "d": ["تسلّم الصدر الأعظم قوجه سنان باشا، بعد حصار دام أكثر من شهر، يانق قلعة التي تُعدّ قفل طريق فيينا. وأثار سقوط القلعة ذعرًا كبيرًا في أوروبا، وكان أبهى مكاسب العثمانيين في الحرب الطويلة. غير أن القلعة لن يمكن إبقاؤها إلا أربع سنوات.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["وفاة مراد الثالث", "1b62e886"], "d": ["توفي مراد الثالث بعد سلطنة دامت واحدًا وعشرين عامًا، في الأيام التي أحرق فيها جيش الأفلاق برايلا وامتد إلى سيليستره، ودُفن في حظيرة آيا صوفيا. ووصل ابنه محمد الثالث المستدعى من مانيسا إلى إسطنبول بعد عشرة أيام وجلس على العرش (27 كانون الثاني/يناير 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["خسارة إسترغون لصالح النمسا", "f420d333"], "d": ["سلّم حراس إسترغون القلعة إلى الأرشيدوق ماتياس، لأنهم لم ينالوا عونًا كافيًا في الحصار الذي قاده كارل فون مانسفلد. وبانتهاء سيادة عثمانية دامت اثنتين وخمسين سنة انكسرت سلسلة الدفاع على خط الدانوب، ودخلت بودين تحت تهديد مباشر. ولن تُسترد القلعة إلا بعد عشر سنوات، في 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["فتح قلعة إغري", "3e511629"], "d": ["سقطت قلعة إغري القوية، التي لم يستطع العثمانيون أخذها من قبل بأي شكل، بتسليم الحراس بعد قتال دام ثلاثة أسابيع. وأصلح هذا الفتح، الذي حضره السلطان بنفسه، معنويات تضررت بخسارة إسترغون إلى حد ما، وأُسست ولاية إغري. وصارت سنة 1596، بانتصار خاتشوفا الذي تحقق بعد أسبوعين، أنجح سنوات الحرب الطويلة للعثمانيين.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["خسارة يانق قلعة (غيور)", "b4ccc679"], "d": ["استعادت القوات بقيادة ميكلوش بالفي وأدولف فون شفارتسنبرغ يانق قلعة بتفجير بوابات القلعة بغارة مباغتة. وأدى فقدان القلعة، التي نالها قوجه سنان باشا قبل أربع سنوات بجهود كبيرة، إلى انهيار الخط الأمامي العثماني في المجر. ومع أن القوات المعادية التي حاصرت بودين في العام نفسه رُدّت، فقد تحول ميزان الحرب شيئًا فشيئًا إلى حرب استنزاف.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["انتفاضة قره يازيجي عبد الحليم", "30493b0d"], "d": ["جمع قره يازيجي عبد الحليم السكبان والليفندات الفارين من الجيش في الحرب الطويلة، وأخضع منطقة واسعة في وسط الأناضول، وأخذ قلعة أورفة (تشرين الثاني/نوفمبر 1599)، وأعلن سلطنته بلقب 'حليم شاه' وأرسل فرمانات تحمل طغراءه. ويُعدّ قره يازيجي أول قادة الموجة الجلالية الكبرى، وقد مات عام 1602 وواصل أخوه دلي حسن حركته. والانتفاضة هي بداية عهد 'الهروب الكبير' الذي ترك فيه فلاحو الأناضول أرضهم جماعات.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["دفاع تيرياقي حسن باشا عن كانيجة", "d56a5e6a"], "d": ["حاصر الأرشيدوق فرديناند وحلفاؤه القلعة أكثر من شهرين، يريدون استرداد كانيجة التي فُتحت قبل سنة؛ وقاوم تيرياقي حسن باشا بقوة مؤلفة من 9000 رجل. ورد الهجمات العامة رغم عدم نيله عونًا من الخارج، وأجبر العدو على الانسحاب بخسائر فادحة بعمليات الخروج. وصار الدفاع ملحمة في الكتابة التاريخية العثمانية، وصار 'حصار كانيجة' نوعًا أدبيًّا قائمًا بذاته.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["وفاة محمد الثالث وجلوس أحمد الأول", "da735fde"], "d": ["جلس ابنه أحمد الأول، وهو في الرابعة عشرة من عمره، على العرش بعد وفاة محمد الثالث في 20 كانون الأول/ديسمبر. وكونه أول سلطان جلس على العرش في سن الطفولة ودون أن يخرج إلى السنجق يدل على أن نظام تربية الأمراء في الولايات قد انتهى فعلًا. وفي سلطنة أحمد الأول سيُترك قتل الإخوة وينتقل إلى مبدأ 'الأكبرية' (جلوس أكبر أفراد الأسرة الذكور على العرش).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["استرداد إسترغون", "7330f273"], "d": ["حاصر الصدر الأعظم لالا محمد باشا إسترغون التي فُقدت قبل عشر سنوات وضمها من جديد إلى الإدارة العثمانية. وفي الحملة نفسها خُلصت بست وفاتس كذلك، وأعاد العثمانيون ترتيب خطهم في المجر. وأتاح هذا النجاح الجلوس إلى المائدة في زيتفاتوروك في العام التالي من موقع قوي نسبيًّا؛ وستبقى إسترغون في يد العثمانيين حتى 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["انتصار سهل أوروج وقمع تمرد جانبولاد أوغلو", "30f93532"], "d": ["هُزم جانبولاد أوغلو علي باشا، الذي أقام إمارة مستقلة في حلب وسعى إلى التحالف مع توسكانا، هزيمة ثقيلة في سهل أوروج على يد الصدر الأعظم قويوجو مراد باشا. وبإعادة إقامة السلطة المركزية في سوريا كُسر أخطر فروع الموجة الجلالية. وأمّنت التصفية القاسية التي دامت سنتين لقويوجو مراد باشا الأمن في الأناضول ولو مؤقتًا.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["انتصار آلاجاير وقمع تمرد قلندر أوغلو", "55db0485"], "d": ["هُزم قلندر أوغلو، زعيم الجلالية الذي فرض الإتاوة على ناحيتي مانيسا وبورصة، في آلاجاير على يد قويوجو مراد باشا، واضطر إلى الفرار إلى إيران. وبهذا الانتصار تشتت آخر الجيوش الجلالية الكبرى في الأناضول. وعلى الرغم من أن تصفية قويوجو مراد باشا القاسية، التي يُروى أنه ملأ فيها الآبار التي حفرها بالعصاة الذين قتلهم، أمّنت النظام على المدى القصير، فإنها لم تعوّض خسارة الأناضول في السكان والإنتاج.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["منح أول عهدنامة لهولندا", "5d9d117e"], "d": ["تمكن سفير جمهورية الأراضي المنخفضة المتحدة كورنيليس هاخا من نيل عهدنامة من أحمد الأول بمثل نطاق ما أُعطي لفرنسا وإنجلترا. وبذلك نالت هولندا حق فتح سفارة في إسطنبول وقنصليات في الموانئ العثمانية والتجارة بعلمها الخاص. وترمز هذه العهدنامة إلى دخول القوى البحرية الشمالية، التي حلت محل البندقية في تجارة المتوسط، إلى السوق العثمانية.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["وفاة أحمد الأول وجلوس مصطفى الأول — نظام الأكبرية", "9901c09e"], "d": ["توفي أحمد الأول، وهو في الثامنة والعشرين من عمره، بعد مرض في المعدة دام واحدًا وخمسين يومًا، وأُجلس على العرش أخوه مصطفى الأول بدلًا من ابنه. وهكذا تُرك نظام الوراثة من الأب إلى الابن وانتُقل فعليًّا إلى نظام 'الأكبرية' الذي يجلس فيه أكبر أفراد الأسرة الذكور على العرش. وهذه السلطنة الأولى التي دامت ستة وتسعين يومًا هي كذلك بداية عهد تربية الأمراء في 'القفص'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["خلع مصطفى الأول وجلوس عثمان الشاب (عثمان الثاني)", "e0f552f2"], "d": ["خُلع مصطفى الأول بعد ستة وتسعين يومًا بحجة أن صحته النفسية غير سليمة، وصار ابن أحمد الأول عثمان الثاني، وهو في الرابعة عشرة من عمره، سلطانًا. ووفقًا للرواية المستندة إلى حسن بيزاده كان لرئيس الأغوات مصطفى آغا أثر في قرار الخلع هذا. ويُعدّ عثمان الشاب، بمشروعه إلغاء أوجاق الإنكشارية وإنشاء جيش جديد، أول اسم راديكالي في مناقشات الإصلاح العثمانية. وسيكلفه هذا المشروع حياته بعد أربع سنوات.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["معاهدة سراب — تجديد الصلح مع إيران", "e778aca8"], "d": ["أكدت معاهدة سراب التي عُقدت مع إيران بعد هزيمة پول شكسته شروط معاهدة ناصوح باشا لعام 1612 في معظمها؛ وخُفّضت كمية الحرير السنوية التي سيرسلها الصفويون من مئتي حمل إلى مئة حمل. وبذلك أُغلقت المرحلة الثانية من حروب الشرق التي استمرت منذ 1603. ولن يدوم الصلح طويلًا، إذ ستشتعل الحرب من جديد بخروج بغداد من اليد عام 1623.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["حملة خوتين ومعاهدة خوتين", "bc4c823c"], "d": ["لم يُتجاوز المعسكر المحصن الذي أقامه خودكيفيتش أمام خوتين في وجه الجيش الكبير الذي قاده عثمان الثاني بنفسه، ولم تُحصَّل نتيجة بعد هجمات دامت أشهرًا. وبموجب المعاهدة الموقعة في 9 تشرين الأول/أكتوبر اعتُبر نهر دنيستر حدًّا، وتعهد البولنديون بمنع غارات القوزاق. وعززت الحملة، التي لم تثمر نتيجة رغم تقديمها انتصارًا، عدم ثقة السلطان الشاب بالإنكشارية ونيته تصفية الأوجاق.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["الخلع الثاني لمصطفى الأول وجلوس مراد الرابع", "1b3a9e74"], "d": ["خُلع مصطفى الأول، الذي أُجلس على العرش للمرة الثانية بعد قتل عثمان الثاني، من جديد بعد سنة وثلاثة أشهر، وأُعلن مراد الرابع، وهو في الحادية عشرة من عمره، سلطانًا. وأدارت الدولة فعليًّا في السنوات التسع الأولى أمه كوسم سلطان ورجال القصر. وسيستولي مراد الرابع على الإدارة بنفسه ابتداءً من 1632 فيبدأ عهدًا من المركزية الشديدة.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["خسارة بغداد لصالح الصفويين", "db81be0c"], "d": ["سلّم ابنه درويش محمد، المدافع عن القلعة الداخلية، المدينة إلى قوات الشاه عباس في نهاية مساومات بكر صوباشي الذي ثار في بغداد مع الصفويين. وأثار فقدان إحدى مدن إرث الخلافة الرمزية ومعظم العراق سخطًا عظيمًا في إسطنبول. وسيكون استرداد بغداد الهدف الوحيد للسياسة العثمانية الشرقية خمس عشرة سنة.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["قمع تمرد أباظة محمد باشا المتمركز في أرضروم", "e6da2729"], "d": ["ثار بكلربك أرضروم أباظة محمد باشا على الإنكشارية بدعوى الثأر لقتل عثمان الثاني، وأمسك الأناضول الشرقية تحت سيطرته سنوات وقاوم المركز. واضطر إلى الاستسلام بحصار الصدر الأعظم خسرو باشا لأرضروم، وعُفي عنه وعُيّن في البوسنة. وكان انتهاء التمرد شرطًا مسبقًا لتمكن مراد الرابع من الخروج في حملة على إيران.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["أول إعدام لشيخ الإسلام: أخي زاده حسين أفندي", "a60a58c5"], "d": ["أُعدم شيخ الإسلام أخي زاده حسين أفندي قرب بويوك تشكمجه بحجة وساطته في الفوضى العسكرية وإرساله إلى السلطان تحذيرًا مكتوبًا في أصول القضاء. وكسر كونه أول شيخ إسلام عثماني يُعدم التقليد الراسخ الذي كان أشد العقوبات فيه على رجال العلمية هو النفي. وتُعدّ الواقعة رمزًا لتشدد سلطة مراد الرابع واختلال التوازن بين الدولة والعلماء.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["فتح مراد الرابع لإيروان", "b65a9b73"], "d": ["خرج مراد الرابع من إسطنبول في 28 آذار/مارس 1635، وحاصر إيروان في 28-29 تموز/يوليو وتسلّم القلعة في 8 آب/أغسطس؛ ثم دخل تبريز المخلاة وأمر بتدميرها. وبنى السلطان في قصر طوب قابي كشك إيروان تخليدًا للنصر. وكانت هذه الحملة أول حملة شرقية كبرى بعد انقطاع ثلاثين سنة قاد فيها السلطان الجيش بنفسه.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["خسارة إيروان لصالح الصفويين", "fbb8dd25"], "d": ["حاصرت قوات الشاه صفي إيروان بعد انسحاب الجيش العثماني واستردتها في ثمانية أشهر. وأظهر خروج القلعة من اليد بهذه السرعة مدى صعوبة السيادة الدائمة في القوقاز من الناحية اللوجستية. وستُترك إيروان في إيران أيضًا بمعاهدة قصر شيرين عام 1639، وسيتخلى العثمانيون عن دعوى أذربيجان.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["استرداد بغداد", "4d2f27f3"], "d": ["استرد مراد الرابع، الذي خرج من إسطنبول في 8 أيار/مايو 1638، بغداد التي كانت في يد الصفويين منذ خمس عشرة سنة، بعد حصار عنيف دام أربعين يومًا؛ واستشهد في الحصار الوزير طيار محمد باشا. وبفتح المدينة أُعيدت الإدارة العثمانية في العراق، ونال السلطان لقب 'فاتح بغداد'. وتثبّت الفتح بمعاهدة قصر شيرين في العام التالي فوضع أساس الحدود التركية - الإيرانية الحالية.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["وفاة مراد الرابع وجلوس السلطان إبراهيم", "e2ca1ca0"], "d": ["جلس على العرش بعد مراد الرابع، الذي توفي وهو في الثامنة والعشرين من عمره، أخوه إبراهيم، العضو الذكر الوحيد الباقي على قيد الحياة من الأسرة. وفي سلطنة السلطان الجديد، الذي عاش في القفص سنوات، زعزعت نفقات القصر والصراعات على النفوذ داخل القصر نظام الدولة. وبخلعه وقتله بعد ثماني سنوات سيقع في التاريخ العثماني ثاني قتل لسلطان.", "4c336200"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["استرداد قلعة آزاق من القوزاق", "e5fcf160"], "d": ["أُخليت قلعة آزاق التي استولى عليها قوزاق الدون عام 1637 أمام العملية المشتركة لسلطان زاده محمد باشا وخان القرم محمد كراي الرابع؛ وانسحب القوزاق بعد أن أحرقوا القلعة. وأغلق استرداد البوابة الشمالية للبحر الأسود المرحلة الخطرة التي امتدت فيها غارات القوزاق إلى مضيق إسطنبول. وستضيع القلعة عام 1696 هذه المرة لصالح القيصر الروسي بطرس الأول.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["بدء حملة كريت وفتح خانيا", "a1b0c77f"], "d": ["أُعلنت الحرب على البندقية بحجة أن قراصنة مالطة ضربوا سفينة الحج العثمانية ولجأوا إلى كريت، وأنزل الأسطول بقيادة يوسف باشا الجنود في الجزيرة. وبأخذ قلعة خانيا بعد حصار دام أربعة وخمسين يومًا أُقيمت أول قاعدة عثمانية دائمة في كريت. وبهذا بدأت أطول حروب التاريخ العثماني؛ ولن تُفتح الجزيرة فتحًا تامًّا إلا بعد أربع وعشرين سنة، في 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["فتح رسمو — تقسيم كريت إلى قسمين", "8f2c4353"], "d": ["بعد سنة من الاستيلاء على خانيا، سقطت قلعة رسمو في وسط الجزيرة أيضًا، ودخل النصف الغربي من كريت بأكمله في الإدارة العثمانية. ولم يبقَ في يد البندقية إلا العاصمة قنديّة وطرف الجزيرة الشرقي؛ وعاشت الجزيرة مقسمة إلى قسمين ثلاثًا وعشرين سنة. وكان الاستيلاء على رسمو الخطوة التي بدأت حصار قنديّة — وهنا بدأ أطول حصار في التاريخ.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["خسارة كليس لصالح البندقية", "5473c22c"], "d": ["شمل الهجوم المضاد للقائد البندقي ليوناردو فوسكولو في الجبهة الدلماسية من حرب كريت (قنديّة) كليس، التي كانت مركز سنجق منذ 1537؛ فانتقلت القلعة إلى البندقية. وجعل تركيز العثمانيين بكل قوتهم على كريت استرداد هذه الخسارة على حدود دلماسيا مستحيلًا — ولن تعود كليس إلى الإدارة العثمانية؛ ونُقل مركز السنجق إلى ليفنو.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["بدء حصار قنديّة", "13016b10"], "d": ["حاصر الجيش العثماني قنديّة، آخر معقل كبير للبندقية في الجزيرة، بعد أخذ خانيا ورشمو. وسُجّل هذا الحصار، الذي سيدوم واحدًا وعشرين عامًا، من أطول الحصارات في التاريخ العسكري العالمي. وفي أثناء الحصار ستنقل محاولات الأسطول البندقي سد مضيق جناق قلعة الحرب إلى قلب بحر إيجه.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["قتل الوالدة الكبرى كوسم سلطان", "9d763f79"], "d": ["قُتلت كوسم سلطان، وهي في نحو الثانية والستين من عمرها، حين وُجدت في غرفة في الحريم على يد باش لالا أوزون سليمان آغا ورجاله الذين تحركوا بأمر توران سلطان أم محمد الرابع. ويُعدّ موت هذه المرأة القوية من الأسرة التي وجّهت سياسة الدولة في عهد ثلاثة سلاطين النهاية الفعلية للعهد المسمى 'سلطنة النساء'. وفتحت السلطة الشاغرة الطريق إلى توليه كوبريلي محمد باشا الصدارة العظمى بصلاحيات استثنائية بعد خمس سنوات.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["هزيمة جناق قلعة وخسارة بوزجه أضه وليمنوس", "e01a1f7e"], "d": ["أباد انتصار الأميرال البندقي موتشينيغو البحري الكبير أمام مضيق جناق قلعة في حزيران/يونيو 1656 الأسطول العثماني تقريبًا بالكامل؛ ثم احتُلت بوزجه أضه وليمنوس وساموثراكي. وبدخول المضيق تحت الحصار البندقي ارتفعت أسعار الغذاء في إسطنبول وانتشر الخوف من هجوم على العاصمة. وكانت هذه الكارثة السبب المباشر في تعيين كوبريلي محمد باشا في الصدارة العظمى بشروط وصلاحيات استثنائية في أيلول/سبتمبر 1656.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["انتصار جناق قلعة واسترداد بوزجه أضه", "603da863"], "d": ["هزم الأسطول الذي عبأه كوبريلي محمد باشا الأسطول البندقي أمام المضيق في 19 تموز/يوليو 1657؛ ثم استردت القوات بقيادة كورد باشا بوزجه أضه في 25 آب/أغسطس، وأخلى البنادقة الجزيرة تمامًا في 30 آب/أغسطس. وفي تشرين الثاني/نوفمبر خُلصت ليمنوس كذلك فكُسر حصار جناق قلعة وأُعيد فتح طريق تموين إسطنبول. وعبر كوبريلي بنفسه إلى الجزيرة وأمر بإصلاح التحصينات؛ وهذا النجاح هو أول مكسب عسكري كبير لعهد الكوبريليين.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["استرداد ليمنوس من البندقية", "a4c3c69b"], "d": ["عادت ليمنوس، التي استولت عليها البندقية في تموز/يوليو 1656، إلى الدولة العثمانية في تشرين الثاني/نوفمبر 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["فتح ينوفا (Ineu) وحملة ترانسلفانيا", "d1089616"], "d": ["سار كوبريلي محمد باشا في حملة لمعاقبة أمير ترانسلفانيا جورج راكوتشي الثاني الذي خرج في حملة على بولندا دون إذن وانتهك الحماية العثمانية، فاتجه عبر بلغراد وأخذ قلعة ينوفا الاستراتيجية. وعُيّن أمير جديد على ترانسلفانيا، فذُكّرت رابطة التبعية بشدة. وكانت هذه الحملة الحلقة الأولى في محاولة العثمانيين إعادة إقامة سلطتهم في أوروبا الوسطى. وكانت ترانسلفانيا أصلًا إمارة تابعة للعثمانيين؛ وكان أخذ ينوفا لا فتحًا من دولة أجنبية، بل انتزاعًا لهذه القلعة من إدارة الإمارة وربطها بسنجق عثماني مباشرة؛ وبقيت بقية الإمارة في وضع التابع.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["قمع تمرد أباظة حسن باشا", "4ba74321"], "d": ["أطلق أباظة حسن باشا، الذي جمع خلفه بكلربكات الأناضول وأغوات السكبان ضد تصفيات كوبريلي محمد باشا القاسية، تمردًا كبيرًا طالب فيه بعزل الصدر الأعظم. وقُمع التمرد في حلب وأُزيل زعماؤه؛ وكان ذلك آخر مقاومة جماعية لباشوات الولايات ضد المركز. وصارت سلطة كوبريلي بذلك غير قابلة للجدل، وارتقى منصب الصدارة من جديد إلى مكانة المركز التنفيذي الحقيقي للدولة.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["فتح فاراد (Oradea)", "0e6ad300"], "d": ["أُخذت قلعة فاراد ومدينتها في إطار الحملة المنظمة ضد أمير ترانسلفانيا جورج راكوتشي الثاني الذي أعلن الحرب على العثمانيين. وبسقوط إحدى القلاع المفتاحية في ترانسلفانيا أُسست في المنطقة ولاية عثمانية جديدة (ولاية فاراد). وأقلق الفتح الهابسبورغ وكان من الأسباب المباشرة للحرب العثمانية - النمساوية التي ستبدأ بعد ثلاث سنوات. ومن الأماكن الأخرى التي ضُمّت في التاريخ نفسه: فارات. وهنا أيضًا لم تؤخذ الأرض من دولة أجنبية: فقد كانت ترانسلفانيا إمارة عثمانية تابعة أصلًا؛ وإن صيرورة فاراد ولاية لم تفعل سوى أخذ إدارة هذه المدينة من الإمارة التابعة وربطها بالسلطان مباشرة، تمامًا كما حدث في ينوفا قبل سنتين.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["معركة سان غوتهارد (St. Gotthard)", "61ebc1f2"], "d": ["أوقف الجيش الأوروبي المتحالف بقيادة مونتيكوكولي القوات العثمانية التي عبرت نهر راب، فتكبدت خسائر فادحة. وتُعدّ المعركة منعطفًا في التاريخ العسكري لإظهارها بوضوح لأول مرة تفوق إطلاق نار المشاة المنضبطين بالأسلحة النارية على هجوم الفرسان العثمانيين. ورغم الهزيمة تمكن العثمانيون من نيل شروط مواتية في معاهدة فاسفار التي وُقّعت بعد تسعة أيام.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["معاهدة فاسفار", "089c978c"], "d": ["نصّت المعاهدة التي وُقّعت رغم هزيمة سان غوتهارد على بقاء أويفار وفاراد مع العثمانيين، وترك ترانسلفانيا محايدة تحت الحماية العثمانية، ودفع النمسا 'هدية' قدرها 200.000 قرش. وهذا الصلح الذي دام عشرين سنة من النادر أن يربح فيه الطرف الخاسر في الحرب على المائدة. وسيغذي استياء الرأي العام الهابسبورغي من المعاهدة الحركة المجرية الوسطى، وبصورة غير مباشرة حملة فيينا عام 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["بدء حكم الدايات في الجزائر", "e99faa51"], "d": ["عزل أوجاق الجزائر وطائفة الرياس (قباطنة القرصنة) آخر الآغوات، وانتخبوا الحاج محمد داي مدى الحياة. ومنذ هذا التاريخ لم يحكم الجزائر بكلربك يعيّنه إسطنبول، بل داي ينتخبه الأوجاق المحلي من بين صفوفه؛ واقتصرت الصلة العثمانية على قراءة اسم السلطان في الخطبة والسنجق وواجب الحملات. وهكذا تحولت الجزائر من ولاية إلى أوجاق — وقد عاشت تونس التحول نفسه عام 1705 مع الحسينيين، وطرابلس الغرب عام 1711 مع القرمانليين.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["بدء حملة بولندا — محمد الرابع وفاضل أحمد باشا على رأس الجيش", "75e15a39"], "d": ["طلبت إسطنبول من ملك بولندا التخلي عن الهجمات، لما استمرت هجمات بولندا على هتمان أوكرانيا بيترو دوروشنكو الذي دخل الحماية العثمانية؛ ولما لم يأتِ جواب إيجابي اتُّخذ قرار الحملة على بولندا. وتحرك الصدر الأعظم فاضل أحمد باشا إلى بولندا في 4 حزيران/يونيو 1672 بالجيش الذي كان السلطان فيه. وستنتهي الحملة بفتح قامانيتشة ومعاهدة بوجاش.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["فتح قامانيتشة وتأسيس ولاية بودوليا", "c3f4f6d0"], "d": ["تسلّمت قامانيتشة، التي تُعدّ أقوى قلاع بولندا في الشرق، بعد حصار دام تسعة أيام؛ وأدى محمد الرابع في 2 أيلول/سبتمبر أول صلاة جمعة في الجامع الذي حُوّل من الكاتدرائية. وجُعلت القلعة مركزًا وأُسست ولاية بودوليا، وبلغت الراية العثمانية أقصى الشمال في أراضي أوكرانيا الحالية. وستبقى قامانيتشة الطرف الشمالي الغربي للإمبراطورية حتى معاهدة كارلوفتش عام 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["قره مصطفى باشا يتسلم أومان من بولندا", "0d3543a0"], "d": ["تسلّم قره مصطفى باشا، الذي أُرسل ضد بولندا، أومان من القلاع التي في يد بولندا؛ وبقيت المدينة في الإدارة العثمانية حتى كارلوفتش.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["فتح قلعة جيهرين", "a17cedd0"], "d": ["حاصر الصدر الأعظم مرزيفونلو قره مصطفى باشا، بقيادته المباشرة بعد العملية التي لم ينتج منها ملك إبراهيم باشا شيئًا في السنة السابقة، قلعة جيهرين المحصنة (19/21 تموز/يوليو) وأخذها في 21 آب/أغسطس. وأجبر سقوط القلعة، رمز التنافس العثماني - الروسي على هتمانية القوزاق في أوكرانيا، روسيا على الصلح. وكان هذا النجاح أحد مصادر ثقة مرزيفونلو التي ستتجه إلى فيينا.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["معاهدة باغجه سراي — أول صلح رسمي مع روسيا", "df82bc0b"], "d": ["وُقّع بين الدولة العثمانية وروسيا صلح لمدة عشرين سنة، باعتبار نهر أوزو (الدنيبر) حدًّا، في نهاية مفاوضات جرت بوساطة خان القرم عقب حملات جيهرين. وتُعدّ هذه المعاهدة وثيقة بداية العلاقات العثمانية - الروسية لكونها أول معاهدة شاملة بين الدولتين. وبفضل الصلح أُمّنت الجبهة الشرقية فأمكن توجيه الجيش إلى أوروبا الوسطى.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["منح براءة ملك المجر الوسطى لإمري توكولي", "3cd8d51d"], "d": ["بدأ يُعدّ النبيل المجري البروتستانتي إمري توكولي، الذي ثار على ضغط الهابسبورغ، 'ملكًا منتخبًا لوسط المجر' ابتداءً من نيسان/أبريل 1682، وقدّم له بكلربك بودين إبراهيم باشا في 16 أيلول/سبتمبر شارات الإمارة. وبهذا أُقيمت دولة مجرية تابعة جديدة تحت الحماية العثمانية. وجعل هذا التدخل الحرب مع النمسا حتمية، فبدأ السلسلة المؤدية إلى حصار فيينا الثاني في العام التالي.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["خسارة آيا مافرا (لفكادا) لصالح البندقية", "e6905fee"], "d": ["قصف أسطول البندقية المنضمة إلى العصبة المقدسة المدينة ثم احتل جزيرة آيا مافرا في البحر الأيوني. وبسقوط بريفيزه في العام نفسه كُسرت رقابة العثمانيين على مدخل الأدرياتيك. وكانت هذه الخسائر الخطوات الأولى في العملية التي سيستولي فيها موروسيني على المورة كلها في ثلاث سنوات.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["خسارة كورون لصالح البندقية", "2ed762bc"], "d": ["استولت القوات البندقية بقيادة موروسيني على قلعة كورون في الطرف الجنوبي الغربي لشبه جزيرة المورة؛ وستبقى المدينة بعد ذلك في الإدارة البندقية ثلاثين سنة. وكان سقوط كورون أول مكسب كبير للعملية البندقية الرامية إلى فتح المورة. ولم تُسترد القلعة إلا في 1715 على يد الجيش العثماني بقيادة سلحدار علي باشا.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["استرداد أثينا — انسحاب البندقية", "03393b46"], "d": ["أدرك موروزيني، الذي قصف الأكروبوليس في أيلول/سبتمبر 1687 ونسف البارثينون، بعد أن أمضى الشتاء في أثينا أنه لن يستطيع الصمود في المدينة. وإثر وباء الطاعون وصعوبة التموين وتعافي القوات العثمانية، أخلت الحامية البندقية المدينة وانسحبت إلى المورة. وهكذا عادت أثينا إلى الإدارة العثمانية دون قتال، غير أن الدمار الذي لحق بالبارثينون لم يمكن تداركه.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["استسلام ليبوفا (ليبا) لكارافا — انتقالها إلى النمسا", "7f0a8d38"], "d": ["بعد حصار أنطونيو كارافا الذي دام ثلاثة أيام، استسلمت ليبوفا بين 12 و22 حزيران/يونيو 1688 ووقعت في يد النمسا. واستردّ العثمانيون المدينة لاحقًا، واستولت عليها النمسا من جديد عام 1691؛ وفي حملة 1695 استعاد العثمانيون السيطرة.", "9ddd4e2f"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["صد حصار البندقية لإغريبوز", "aae7e6a0"], "d": ["حاول موروسيني، الذي اتجه إلى إيجه بعد الاستيلاء على المورة، أن يأخذ إغريبوز بحصار دام أكثر من ثلاثة أشهر؛ لكنه اضطر إلى الانسحاب بخسائر فادحة أمام التحصينات التي قُوّيت في شتاء 1687-1688 ومقاومة الحامية. وأوقف هذا الفشل تقدم البندقية في إيجه وزعزع هيبة موروسيني العسكرية. وستبقى إغريبوز في يد العثمانيين في كارلوفتش أيضًا.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["خسارة قلعة كانيجة لصالح النمسا", "553b45f3"], "d": ["فقدت كانيجة، التي ضُرب عليها حصار محكم من جيش الهابسبورغ المؤلف من 60.000 رجل ابتداءً من كانون الثاني/يناير 1690، بعد أن قاومت أشهرًا دون عون، باتفاق التسليم الذي وقّعه آخر حراسها مصطفى باشا. وبذلك انتهت سيادة عثمانية دامت تسعين سنة في القلعة التي ارتبطت بدفاع تيرياقي حسن باشا الملحمي. وكان فقدان كانيجة انهيار آخر معقل عثماني كبير في غرب المجر.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["وفاة سليمان الثاني", "d2478080"], "d": ["توفي سليمان الثاني، الذي أُجلس على العرش عام 1687 بعد أن أمضى نحو أربعين سنة في القفص، وهو مريض يتابع استعدادات الجيش، في أدرنة نحو ظهر يوم الجمعة 22 حزيران/يونيو 1691؛ وامتدت سلطنته ثلاث سنوات وثمانية أشهر ويومين. وكان الصدر الأعظم قد أعطى مسبقًا التعليمات اللازمة لإجلاس أخيه أحمد على العرش في حال وفاة السلطان. وصُلّي على الجنازة في اليوم نفسه في كشك العرض؛ ونُقل جثمانه إلى إسطنبول ودُفن في ضريح السلطان سليمان القانوني إلى يمينه.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["جلوس أحمد الثاني على العرش", "52947b14"], "d": ["جلس أخو سليمان الثاني، أحمد الثاني، وهو في التاسعة والأربعين من عمره، على العرش في أدرنة إثر وفاة سليمان الثاني. وصادفت سلطنته أشد سنوات حروب العصبة المقدسة؛ وبعد شهرين من جلوسه استشهد الصدر الأعظم فاضل مصطفى باشا في سالانكامن. وفي المقابل كان نظام المالكانة الذي طُبّق في عهده من أهم الترتيبات التي غيّرت البنية الطويلة الأمد للمالية العثمانية.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["وفاة محمد الرابع في أدرنة", "17388b7e"], "d": ["أُحضر محمد الصياد، الذي خُلع عام 1687، إلى أدرنة في أثناء حملة سليمان الثاني على المجر عام 1689، وشهد أيضًا سلطنة أخيه الآخر أحمد الثاني. وتوفي في هذه المدينة التي أحبها كثيرًا. ونُقل جثمانه إلى إسطنبول ودُفن في ضريح أمه تورهان سلطان بجوار يني جامع.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["وفاة أحمد الثاني في أدرنة", "c6306c08"], "d": ["توفي أحمد الثاني، الذي قضى سلطنته التي دامت أربع سنوات في الحروب، في أدرنة بسبب الاستسقاء (الوذمة) وهو في الثانية والخمسين من عمره. ونُقل جثمانه إلى إسطنبول ودُفن في ضريح السلطان سليمان القانوني. وخلفه ابن أخيه مصطفى الثاني.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["استيلاء الإيرانيين على البصرة", "a9cdf3a3"], "d": ["بينما كانت الدولة العثمانية مشغولة في الغرب بحروب الحلف المقدس، تعرضت البصرة بعد وباء الطاعون عام 1690 للنهب أولًا من شيخ المنتفق مانع، ثم من خان الحويزة فرج الله. واستفاد الإيرانيون من هذه الفوضى فاستولوا على المدينة عام 1696 وتركوا فيها حرسًا.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["معاهدة إسطنبول — ترك آزاق لروسيا", "79db4724"], "d": ["لم يكن ممكنًا في كارلوفتش سوى عقد هدنة لسنتين مع روسيا؛ ووُقّع الصلح الدائم في إسطنبول بعد مساومات شاقة دامت سنة ونصفًا. وتخلت الدولة العثمانية رسميًّا لروسيا عن قلعة آزاق التي فقدتها عام 1696 والأراضي المحيطة بها، وتنازلت عن الضريبة السنوية التي ينالها خان القرم من موسكو. وفي المقابل نالت روسيا حق إبقاء سفير دائم في إسطنبول؛ وبذلك سُجّل الوجود الروسي على الساحل الشمالي للبحر الأسود قانونيًّا.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["استرداد دالتبان مصطفى باشا القرنة والبصرة", "7adb777d"], "d": ["سار دالتبان مصطفى باشا، الذي عُيّن واليًا على بغداد وسر عسكر البصرة بعد معاهدة كارلوفجه، نحو الجنوب بقوات حلب والرقة وسيواس وقرمان وبأسطول نهري نزل من بيره جك. وأطاع شيوخ القبائل المحيطة واحدًا بعد آخر، وترك داود خان حارس إيران في البصرة المدينة، فدخلت القرنة والبصرة من جديد في الإدارة العثمانية.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["وفاة مصطفى الثاني", "626c394d"], "d": ["توفي مصطفى الثاني، الذي ترك العرش لأخيه أحمد الثالث بحادثة أدرنة، بعد نحو خمسة أشهر من خلعه في أدرنة التي أحبها كثيرًا. وانضم إلى مرضه حزنه على التطورات الأخيرة. وتذكر بعض المصادر الغربية أن الاعتقاد بأنه سُمّم شاع بين الناس.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["بدء حكم المماليك (الكولمن) في بغداد", "abe52618"], "d": ["ببداية تعيين حسن باشا الجورجي الأصل واليًا على بغداد بدأ عهد هيمنت فيه على العراق طبقة حاكمة تربّت من مماليكها بدلًا من الولاة الذين يعيّنهم المركز. وترسخ النظام بولاية سليمان باشا عام 1749، واضطر الباب العالي إلى تعيين واحد من المماليك الذين استولوا على النفوذ بدلًا من تعيين من يشاء. ومع أن هذا البنيان شبه المستقل أفاد في الدفاع عن الحدود الإيرانية، فإنه أضعف رقابة السلطة المركزية على العراق قرنًا ونصفًا.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["تأسيس الأسرة الحسينية في تونس", "cb1a98f9"], "d": ["استولى حسين بن علي، آغا السباهية التركي الأصل، على البايلك في فراغ السلطة الذي نشأ عن غزو القوات الجزائرية لتونس، وكسب الشرعية بإعلانه ولاءه للسلطان العثماني. وحكمت الأسرة التي أسسها تونس بين 1705-1735 و1756-1957؛ وحل محل إدارة الأوجاق نظام بايلك ينتقل من الأب إلى الابن. وبذلك نشأ أول مثال على بنى أسرية مرتبطة بالمركز لكنها مستقلة ذاتيًّا فعليًّا في أوجاقات الغرب.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["أخذ وهران (Oran) والمرسى الكبير من الإسبان", "b67ce06a"], "d": ["استولت قوات بكلربك أوجاق الجزائر، بعد حصار طويل، على وهران وميناء المرسى الكبير اللذين كانا في يد الحامية الإسبانية منذ قرنين. وكان ذلك أكبر نجاح حققته أوجاقات الغرب، التي تحت الحماية العثمانية، ضد إسبانيا في غرب المتوسط، وأمّن الجناح الغربي للجزائر. وستتعرض المدينة للاحتلال الإسباني من جديد في 1732، ولن تُسترد نهائيًّا إلا في 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["معاهدة بروت — استرداد آزاق وتايغان", "bac5d2a1"], "d": ["نصّت المعاهدة المؤلفة من سبعة بنود التي وُقّعت باستسلام الجيش الروسي المحاصر على نهر بروت على إعادة قلعة آزاق إلى العثمانيين مع أرضها وذخيرتها. وكان على تحصينات تايغان وكامينكا ويني قلعة أن تُهدم، ولا يبني الطرفان قلاعًا جديدة في هذه المناطق. وانهار نظام الأسطول والقواعد الذي أقامه بطرس الأول في فورونيج وآزاق طوال ست عشرة سنة؛ وتأخر نزول روسيا إلى البحر الأسود نحو خمسين سنة.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["تأسيس الأسرة القرمانلية في طرابلس الغرب", "e1105d4a"], "d": ["استولى ضابط الفرسان أحمد القرمانلي على الحكم في طرابلس الغرب التي أضجرها تنازع آغوات الأوجاق، وأضفى الصفة الرسمية على وضعه ببراءة البكلربكية التي نالها من إسطنبول. ونشأت بيد أحمد باشا وابنه محمد باشا وحفيده يوسف باشا أسرة حاكمة دامت بين 1711 و1835؛ وظهر بنيان شبه مستقل أنشأ أسطوله الخاص ووقّع معاهدات مباشرة مع الدول الأوروبية. ولن ينتهي هذا العهد إلا في 1835 بربط الولاية بالمركز مباشرة.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["معاهدة أدرنة مع روسيا", "14901a70"], "d": ["أُعلنت الحرب مرتين أخريين بسبب عدم الوفاء بما وُعد به في بروت، وأخيرًا وُقّع صلح دائم في أدرنة بقبول الروس التزاماتهم. وأكدت المعاهدة شروط بروت؛ وتعهدت روسيا بألا تتدخل في شؤون بولندا وأن تنسحب من أراضي القوزاق وألا تعيق عودة ملك السويد شارل الثاني عشر الحديدي الرأس إلى بلاده. وأتاح إغلاق الجبهة الشمالية بذلك للدولة العثمانية أن تحول وجهها إلى جبهة المورة والبندقية. ومن الأماكن الأخرى التي ضُمّت في التاريخ نفسه: خوتين.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["إعلان الحرب على البندقية — الاستعداد لحملة المورة", "d970b122"], "d": ["اتُّخذ قرار الحرب في الديوان بحجة دعم البندقية للمتمردين في الجبل الأسود ومصادرتها السفن التجارية العثمانية وإرهاقها المورة التي أخذتها في كارلوفتش بالضرائب الثقيلة. وانتهت الحملة التي أعدها الصدر الأعظم سلحدار داماد علي باشا في العام التالي باسترداد شبه جزيرة المورة كلها في أقل من مئة يوم. غير أن هذا النجاح سيحرك النمسا ويفتح باب حرب أشد ثقلًا بكثير في 1716.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["إستنديل (تينوس): تسليم آخر جزر البندقية في إيجه", "4abec891"], "d": ["رست أمام إستنديل، آخر جزيرة بقيت في يد البندقية في إيجه، الأسطول الذي خرج لحملة المورة. وسلّمت الجزيرة، التي حملت العلم البندقي مائة وخمسين سنة أخرى بفضل سكانها اللاتين رغم سقوط دوقية ناكسوس عام 1566، بعد حصار قصير دون إراقة دماء. وهكذا انمحى آخر أثر للبندقية في بحر إيجه وصار البحر بأكمله بحرًا داخليًا عثمانيًا.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["فتح أنابولي — القلعة المفتاحية للمورة", "62a5808a"], "d": ["سقطت أنابولي، عاصمة البندقية في المورة وأقوى تحصيناتها، باحتلال طابية باليميدي بعد قصف دام تسعة أيام. وكسر الاستيلاء السريع على القلعة المقاومة في سائر شبه الجزيرة. واكتمل فعليًا هنا استرداد المورة التي فُقدت في كارلوفجه.", "9b883577"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["استسلام مودون", "43faa909"], "d": ["بعد سقوط أنابولي، حوصرت قلعة مودون في الطرف الجنوبي الغربي للمورة، من الجيش برًا ومن الأسطول بحرًا، وسلّمت في وقت قصير. وكان هذا الميناء، الذي استخدمته البندقية مائتي سنة في حملاتها في شرق المتوسط، محطة إلزامية تأخذ منها السفن الماء والمؤن. وأنهى فقدانه قدرة الأسطول البندقي على الحركة في إيجه.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["استسلام كورون — اكتمال حملة المورة", "e4b9c8a4"], "d": ["بتسليم قلعة كورون التي تمسك مدخل خليج ميسينيا، انتهت الإدارة البندقية في شبه جزيرة المورة نهاية تامة. واستُردت شبه الجزيرة التي فُقدت في كارلوفجه بأكملها بعد ثلاثة أشهر فقط من افتتاح الحملة. وفي استمرار الحملة نفسها، استُولي في أيلول/سبتمبر 1715 على جزيرة آيا مافرا (لفكادا) في البحر الأيوني من البندقية أيضًا. وأجبرت هذه السرعة البندقية على إدخال النمسا في الحرب، وانفتح بعد ثلاث سنوات الطريق إلى باساروفجة.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["الاستيلاء على جزيرة تشوخا (كيثيرا)", "494de6c6"], "d": ["تسلّم الأسطول جزيرة تشوخا في الطرف الجنوبي للمورة بعد اكتمال شبه الجزيرة. وكانت الجزيرة، التي تراقب الممر بين البحر الأيوني وإيجه، موقعًا أماميًا استخدمته البندقية لمراقبة هذه المياه. غير أنها لم تبقَ الجزيرة العثمانية الوحيدة المحتفَظ بها: فقد أُعيدت إلى البندقية بعد ثلاث سنوات في باساروفجة.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["تحالف النمسا والبندقية — باب الحرب العثمانية - النمساوية 1716-1718", "99511ca2"], "d": ["بعد أن استرد العثمانيون المورة من البندقية، وقّعت النمسا معاهدة تحالف مع البندقية زاعمة أن معاهدة كارلوفتش قد انتُهكت؛ وطلب الأمير أوجين في رسالة كتبها إلى الصدر الأعظم إعادة الأماكن المأخوذة من البندقية. وفي المشورة التي جرت في معسكر داود باشا أُعلنت الحرب على النمسا بضغط من الصدر الأعظم علي باشا، ونُيلت لذلك فتوى من شيخ الإسلام.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["خروج الصدر الأعظم علي باشا في حملة النمسا", "2fbdce42"], "d": ["خرج السردار الأكرم علي باشا في حملة النمسا بجيش يزيد على 100.000 بعد إعلان الحرب على النمسا؛ وتوجه الأسطول في الصيف نفسه إلى كورفو. وسيسير الجيش من بلغراد على بتروفارادين، وسيستشهد الصدر الأعظم في الهزيمة في أوائل آب/أغسطس.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["هزيمة بتروفارادين (Petrovaradin) — استشهاد داماد علي باشا", "265c1d81"], "d": ["التقى الجيش العثماني، الذي عبر الدانوب عبر بلغراد، بالقوات النمساوية بقيادة الأمير أوجين أمام بتروفارادين؛ وأجبر هجوم الإنكشارية في الضربة الأولى متاريس العدو، لكن الصفوف تشتتت بانهيار جناح الفرسان. واستشهد الصدر الأعظم سلحدار داماد علي باشا برصاصة في جبهته، ووقع المعسكر والمدفعية بالكامل في يد العدو. وكانت هذه الهزيمة، التي تسميها الوقائع العثمانية 'سنة بتروفارادين'، الحلقة الأولى في سلسلة أدت إلى فقدان تيمشوارة وبلغراد في العام التالي.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["فشل حصار كورفو", "b2aa7011"], "d": ["هجم قره مصطفى باشا سردار المورة من البر، وقبطان باشا جانم خوجة محمد باشا من البحر على كورفو؛ وكانت الجزيرة القاعدة المفتاحية للبندقية في الأدرياتيك. غير أن التحصينات القوية جدًّا للقلعة والإمدادات التي جلبها الأسطول البندقي وأنباء الهزيمة الواردة من جبهة الدانوب أدت إلى رفع الحصار. وأطفأ عدم أخذ كورفو المناخ الذي ارتفع باسترداد المورة، ونقل ثقل الحرب إلى المجر.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["خسارة تيمشوارة (Timişvar) لصالح النمسا", "27fe1365"], "d": ["سار الأمير أوجين، بعد هزيمة بتروفارادين، مباشرة على تيمشوارة، وسُلمت القلعة بالأمان في نهاية حصار جاوز أربعين يومًا. وهكذا خرجت من اليد المدينة التي فُتحت عام 1552 في عهد القانوني والتي عُدّت مدة 164 سنة، بوصفها مركز بكلربكية، العمود الشرقي للدفاع عن المجر. وبسقوط تيمشوارة انتقلت منطقة البانات بأكملها إلى النمسا ودُفع الحد العثماني إلى جنوب الدانوب.", "3f3368fd"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["تسليم قلعة هارام (بلانكا الجديدة) للنمسا — خروج ضفة الدانوب في البانات من اليد", "38ee4c6d"], "d": ["سار الجنرال النمساوي للفرسان ميرسي، المكلف بأخذ بقية البانات بعد سقوط تيمشوارة، في 14 تشرين الثاني/نوفمبر على هارام (بلانكا الجديدة) الواقعة على ضفة الدانوب؛ وعندما بلغ القلعة في 16 تشرين الثاني/نوفمبر سلّمت الحامية العثمانية المؤلفة من 200 رجل برفع الراية البيضاء بشرط الانسحاب الحر. وبذلك انتقل إلى النمسا خط الدانوب في البانات الجنوبية الذي كان في يد العثمانيين منذ 1552.", "8026e3e4"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["معاهدة باساروفجة — كُسبت المورة وفُقدت بلغراد والبنات", "d46aa216"], "d": ["كانت المورة قد استُردت من البندقية، غير أن النمسا التي دخلت الحرب تفوقت على مائدة المفاوضات بانتصاراتها في بيتروفارادين وبلغراد. فأبقت المعاهدة الموقعة بوساطة إنجلترا وهولندا المورة في يد العثمانيين، وفي المقابل تُرك للنمسا شمال صربيا مع بلغراد والبنات والأفلاق الصغرى؛ وبحسب تعبير TDV «تُرك شمال البوسنة بأكمله للنمسا» — فتنتقل إلى النمسا على الخريطة منذ هذا اليوم قلاع مثل دوبيتسا البوسنية وبرود البوسنية على السافا (رسم المفوضون الحد النهائي واحدًا واحدًا، ولا يعدّد TDV هذه القلاع بأسمائها)؛ أما البندقية فاحتفظت بمواقعها مثل بريفزة وتشوخا على الساحل الأيوني. وبمعاهدة التجارة (الأهدنامة) الموقعة في اليوم نفسه خُفضت الرسوم الجمركية المأخوذة من البضائع النمساوية من خمسة بالمئة إلى ثلاثة. وبينما سجلت المعاهدة تراجع الدولة العثمانية في وسط أوروبا، أرست الأرضية لعصر التوليب (1718-1730) بالسلم الذي فتحته لسبع وعشرين سنة: ففي إدارة نوشهرلي داماد إبراهيم باشا كانت أول مطبعة عثمانية (1727، إبراهيم متفرقة)، ولجان الترجمة، وملاحظات اللقاح ضد الجدري، وحياة القصر والثقافة الجديدة من نتاج سنوات السلم هذه.", "3a9f1433"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["الحملة الشرقية: أخذ تفليس وبدء الحرب الإيرانية", "78343dc2"], "d": ["أرسلت الدولة العثمانية جيشًا إلى الشرق حتى لا يُترك الفراغ بالكامل للنفوذ الروسي، إثر انهيار الدولة الصفوية بالغزو الأفغاني ونزول روسيا إلى سواحل بحر قزوين. وربطت جورجيا بالإدارة العثمانية بأخذ تفليس؛ ثم استمر التقدم باتجاه كنجه وإيروان ونخجوان. وكانت هذه الحملة، التي جرت خلف المظهر السلمي لعصر التوليب، بداية مغامرة شرقية طويلة ستدوم ثلاث عشرة سنة وتنتهي بإعادة كل ما كُسب.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["حملة إيران 1723: الدخول إلى شروان وجورجيا", "c81189fc"], "d": ["إثر انهيار الدولة الصفوية بالغزو الأفغاني، فُتحت حملة نحو الشرق بحجة منع روسيا من النزول إلى سواحل بحر قزوين. ودخل جيش أرضروم تفليس عبر جورجيا ودخل فرع شروان شماخي، فاستردا الأراضي التي فُقدت قبل مائة وثلاثين سنة. وكانت هذه الحملة آخر تقدم كبير للدولة العثمانية في القوقاز.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["الاستيلاء على كرمانشاه — باب زاغروس", "ad14799f"], "d": ["اجتاز جيش بغداد ممرات زاغروس واستولى على كرمانشاه، التي تُعدّ الباب الغربي لإيران. وكانت المدينة على طريق القوافل والجيوش من بغداد إلى أصفهان، وكان الاستيلاء عليها يؤمّن أمن إيالة العراق الشرقي. وبدأ هذا التقدم سباق تقاسم بين الدولة العثمانية وروسيا في الأرض الإيرانية المتفككة.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["مقاسمة نامة إسطنبول — تقاسم إيران مع روسيا", "fce8eec2"], "d": ["وُقّعت معاهدة تقسيم بوساطة السفير الفرنسي لمنع المواجهة بين العثمانيين وروسيا على أرض الدولة الصفوية المنهارة. وتُركت السواحل الغربية والجنوبية لبحر قزوين لروسيا، وتُركت جورجيا وشروان وأذربيجان ومدن غرب إيران للدولة العثمانية. وهذا التقاسم الذي بدا مكسبًا كبيرًا على الورق سيصبح فعليًّا بلا أثر بعد قليل بصعود نادر شاه.", "36a04f61"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["الاستيلاء على نخجوان", "bdf14d0a"], "d": ["استولت القوات العثمانية المتقدمة على طول آراس على نخجوان وأوردوباد؛ وضُمت جلفا إلى لواء نخجوان. وربطت المدينة، بوصفها الباب الشمالي الغربي لإيران، بإيالة ريفان المؤسَّسة حديثًا. وهكذا بلغ الحد العثماني من جديد أقصى خط شرقي له في عهد القانوني.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["فتح همدان", "e1339a97"], "d": ["استولى الجيش، السائر شرقًا من كرمانشاه، على همدان على العتبة الغربية للهضبة الإيرانية بعد حصار طويل. وكانت المدينة آخر المحطات الكبرى على طريق أصفهان، وهي أبعد نقطة شرقية استطاعت الجيوش العثمانية بلوغها منذ حملة العراقين. وسجلت المعاهدة المبرمة مع روسيا في العام نفسه، «معاهدة إسطنبول»، على الورق تقاسم إيران المتفككة بين الدولة العثمانية وروسيا.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["إعادة فتح ريفان", "88acabef"], "d": ["دخلت ريفان، القلعة المفتاحية لوادي آراس، من جديد في الإدارة العثمانية بعد حصار عسير دام تسعين يومًا. وحُصّنت القلعة، التي بُنيت عام 1583 وفُقدت عام 1604، هذه المرة بحامية أقوى. وكان طول الحصار مؤشرًا على أن الجيش العثماني لم يعد يتقدم بسهولة. وربطت بإيالة ريفان أيضًا نواحي كاربي (أوتش كيليسه) وشرور وماكو وشوره غول.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["الاستيلاء على تبريز — ضمّ أذربيجان", "e502a4f7"], "d": ["استسلمت تبريز، التي أُعيد حصارها بعد محاولة فاشلة قبل عام، للجيش العثماني إثر معارك شوارع ضارية دارت من زقاق إلى زقاق. ودخلت مرند ومراغة وسوك بولاغ (مهاباد)، التابعة لإيالة تبريز، في الإدارة العثمانية أيضًا. وفي العام نفسه استُولي كذلك على لوري وكنجة وأردبيل وخرّم آباد، فاحتُلّت فعليًا المناطق التي آلت إلى العثمانيين بموجب «مقاسمة نامة إسطنبول». وكان هذا الاتساع الذي بلغته الدولة في الشرق أبعد حدّ لها منذ عهد معاهدة فرهاد باشا؛ غير أن الاحتفاظ به أثقل الجيش والخزينة بعبء شديد.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["فتح كنجة — نهاية حملة القوقاز", "875bca7a"], "d": ["سُلّمت كنجة، الهدف الأخير لعملية القوقاز، بوصفها مركز قره باغ بين الكر وآراس. وبإتمام خط شروان وريفان ونخجوان وكنجة، بلغت الدولة العثمانية في القوقاز اتساعها عام 1590. غير أن هذا المكسب كان قصير العمر: فصعود نادر شاه سيستعيد المنطقة كلها في غضون عشر سنوات.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["معاهدة همدان — ضمّ غرب إيران إلى الدولة العثمانية", "94a29dc3"], "d": ["انتهت الحرب التي استمرت أربع سنوات بمعاهدة وُقّعت مع الحاكم الأفغاني أشرف شاه، واعتُرف قانونيًا بأراضي غرب إيران التي احتلتها الدولة العثمانية. وقبل أشرف شاه في مقابل ذلك خلافة السلطان العثماني، وتعهّد بأن تُقرأ الخطبة في إيران باسم السلطان. غير أن هذا الانتصار الدبلوماسي لم يدم طويلًا؛ فقد كان الهجوم المضاد الذي بدأه نادر شاه عام 1730 سيمحو مكاسب المعاهدة في غضون بضع سنوات.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["استيلاء حكيم أوغلو علي باشا على أرومية", "eac7f64d"], "d": ["في حملة إيران، استولى حكيم أوغلو علي باشا أولًا على أرومية، ثم على تبريز التي أُخليت للعثمانيين في 15 تشرين الثاني/نوفمبر 1731. ولا تذكر TDV يوم الاستيلاء على أرومية؛ ويُعرف فقط السنة وأنه سبق تبريز.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["معاهدة أحمد باشا — إعادة القسم الأكبر من غرب إيران", "590d839f"], "d": ["إثر انتصار نادر شاه في ملاير وهجمات الإيرانيين المتتالية، وقّع والي بغداد أحمد باشا نصّ صلح دون الرجوع إلى المركز. فبموجب المعاهدة عُدّ نهر آراس حدًّا فاصلًا، وأُعيدت إلى إيران مدن غرب إيران مثل همدان وكرمانشاه وأردلان وأردبيل وتبريز، وبقيت كنجة وتفليس في يد العثمانيين. وقوبل هذا النص بردّ فعل غاضب في إسطنبول، ورآه نادر شاه أيضًا غير كافٍ، فاندلعت الحرب من جديد قبل أن ينقضي عام 1732.", "b7cf810a"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["فقدان وهران ثانيةً لمصلحة إسبانيا", "20485027"], "d": ["وصل أسطول إنزال كبير أرسله ملك إسبانيا فيليب الخامس بقيادة الكونت مونتيمار إلى وهران، فهزم قوات أوجاق الجزائر واستردّ المدينة. وكان الميناء الذي فُتح قبل أربع وعشرين سنة سيبقى ستين عامًا أخرى في يد حامية إسبانية. وقد أظهر هذا الفقدان حدود قوة أوجاقات الغرب في غرب البحر المتوسط، ولم يمكن تعويضه إلا بالفتح النهائي لوهران عام 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["إصلاح أوجاق القُمبرة على الطراز الأوروبي وتأسيس قمبرخانة", "d980cf2a"], "d": ["نظّم قمبراجي أحمد باشا، وهو فرنسي الأصل دخل الخدمة العثمانية، بدعم من الصدر الأعظم حكيم أوغلو علي باشا، أوجاق القمبرة فجعله وحدة نظامية ذات رواتب مرتبة على الطراز الأوروبي. وتلقّى ثلاثمائة جندي جُمعوا من البوسنة تدريبًا منتظمًا قائمًا على الحساب والهندسة؛ وأُعدّت نظامات جديدة للتشكيلات والتجهيزات والتقاعد، وصُنع بالتقنية الحديثة مائة مدفع قنابل وخمسون ألف قنبلة. وتُعدّ القمبرخانة التي كانت تُدرَّس فيها الهندسة النواة الأولى لتعليم الهندسة العسكرية الحديثة في الدولة العثمانية.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["وفاة أحمد الثالث", "455f7fba"], "d": ["أمضى أحمد الثالث، الذي خُلع عام 1730 بثورة بترونا خليل، السنوات الست الأخيرة من حياته في جناح السلاطين المخلوعين من قصر طوب قابي، وتوفي في الثالثة والستين من عمره. ودُفن في ضريح جدته تورهان سلطان بجوار يني جامع في باغجه قابي.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["معاهدة إسطنبول — التخلي عن جنوب القوقاز لإيران", "8c205aab"], "d": ["انتهت الحرب الإيرانية الثانية التي دامت أربع سنوات بمعاهدة وُقّعت عقب هزيمة أرباجاي وفقدان كنجة وتفليس. فانسحبت الدولة العثمانية من جميع أراضي جنوب القوقاز وغرب إيران التي استولت عليها منذ عام 1723، وعاد الحدّ إلى خط قصر شيرين لعام 1639. وبقي من حملات الشرق التي دامت ثلاث عشرة سنة عبء مالي ثقيل وخزينة خاوية؛ وفي المقابل كان إغلاق الجبهة الشرقية مكسبًا حيويًا للحرب الجديدة التي بدأت مع روسيا.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["سقوط قلعة أوزي (أوتشاكوف) في يد الروس", "f93e61f3"], "d": ["حاصر الجيش الروسي بقيادة المارشال مونيخ قلعة أوزي عند مصبّ الدنيبر؛ وانهار الدفاع بانفجار مستودع الذخيرة، وسقطت القلعة بخسائر بشرية فادحة. وقد فتح فقدان أوزي، التي كانت تُعدّ مفتاح الساحل الشمالي الغربي للبحر الأسود، الطريق إلى القرم أمام الروس وأثار ذعرًا كبيرًا في إسطنبول. وفي العام التالي أخلاها الروس بسبب الوباء وصعوبة التموين فعادت إلى العثمانيين.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["انتصار بانيالوكا — تحرير البوسنة", "f603865a"], "d": ["حين دخلت القوات النمساوية البوسنة وحاصرت بانيالوكا، سارع والي البوسنة حكيم أوغلو علي باشا إلى النجدة بقوات جمعها من الأهالي، وألحق هزيمة ثقيلة بعدوّ متفوق عددًا. وقد أفشل هذا الانتصار خطة النمسا لاحتلال البوسنة منذ خطوتها الأولى، واستُردّ شمال الإيالة بأكمله. وكانت بانيالوكا إحدى نقاط التحول التي رفعت معنويات الجيش العثماني الذي كان يتراجع باستمرار أمام النمسا بعد عام 1683.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["انتصار هيسارجق (غروتسكا) — فتح الطريق إلى بلغراد", "2101cdff"], "d": ["وقع الجيش النمساوي، الذي كان يتقدم لحماية بلغراد، في كمين في مضيق ضيق على ضفة الدانوب، ومُني بخسائر فادحة في معركة استمرت طوال اليوم. وبينما كانت قوات المارشال فاليس تنسحب إلى بلغراد في فوضى، بلغ الجيش العثماني أمام القلعة وبدأ الحصار. وكان هيسارجق أحسم انتصار ميداني يُحرز على النمسا منذ كارلوفجه، وأدّى مباشرة إلى استرداد بلغراد.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["معاهدة نيش — الصلح مع روسيا وتحييد آزاق ووقف غارات القرم", "674f974e"], "d": ["اضطرت روسيا، التي بقيت وحدها بعد أن قبلت النمسا الصلح في بلغراد، إلى إنهاء الحرب بوساطة السفير الفرنسي فيلنوف. فهُدمت تحصينات قلعة آزاق وأُعلنت المنطقة أرضًا محايدة بين الدولتين؛ وقبلت روسيا شرط ألا تُبقي سفنًا حربية أو تجارية في البحر الأسود. وهكذا تأجّل هدف روسيا في الوصول إلى البحار المفتوحة جيلًا آخر، وخرجت الدولة العثمانية من مائدة المفاوضات رابحة للمرة الأخيرة في القرن الثامن عشر.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["عودة أوزي من الاحتلال الروسي: تسليم القلعة بعد هدم تحصيناتها بموجب صلح 1739", "7ecc2bef"], "d": ["كان الروس قد استولوا على أوزي في 11 تموز/يوليو 1737. وبموجب الصلح الذي عُقد مع روسيا عام 1739 سُلّمت القلعة إلى العثمانيين بعد هدم تحصيناتها؛ وظلّت أوزي في يد العثمانيين حتى عام 1788 قبيل معاهدة ياش.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["الدفاع عن الموصل — صدّ نادر شاه", "c03ffbc1"], "d": ["بعد أن استولى نادر شاه على كركوك وأربيل ووصل إلى الموصل، قصف المدينة بالمدافع أربعين يومًا ونظّم هجمات عامة متتالية. وقد أجبر الدفاع الذي قاده الوالي حسين باشا الجليلي، وسلّح فيه أهل المدينة أيضًا، الجيش الإيراني على رفع الحصار بخسائر فادحة. ومنع صمود الموصل خروج العراق بأكمله من اليد، ورسّخ نفوذ أسرة الجليلي في المدينة قرنًا كاملًا.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["تحالف الدرعية — تأسيس الإمارة السعودية الأولى في نجد", "188751bf"], "d": ["أجار الأمير محمد بن سعود في الدرعية العالم محمد بن عبد الوهاب الذي طُرد من العيينة، وعقد معه تحالفًا يضع السلطة السياسية في خدمة الدعوة الدينية. وقد بدأ هذا الاتفاق تاريخًا جديدًا لأسرة آل سعود، ووحّد إمارات الواحات المتفرقة في نجد حول حركة واحدة. وستمتد هذه القوة في غضون نصف قرن إلى كربلاء ومكة والمدينة، وستضطر الدولة العثمانية إلى الدفاع عن سيادتها في الحجاز.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["معاهدة كردان — نهاية الحروب العثمانية الإيرانية", "1d3a919e"], "d": ["جُدّد بالمعاهدة التي وُقّعت بعد الحرب الأخيرة التي دامت أربع سنوات حدّ قصر شيرين لعام 1639 دون تغيير؛ ولم يحقق الطرفان أي مكسب إقليمي. وبقي إصرار نادر شاه على الاعتراف بالجعفرية مذهبًا خامسًا دون مقابل، وقُرّر في المقابل أن يؤدي الحجاج الإيرانيون الحج بحرية وأن يتبادل الطرفان السفراء. وهكذا انتهت فعليًا الحروب العثمانية الإيرانية التي تجاوزت قرنين؛ وقد بقي هذا الحدّ إلى اليوم محفوظًا في معظمه.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["وفاة محمود الأول وجلوس عثمان الثالث على العرش", "30203700"], "d": ["توفي محمود الأول، الذي استرد في سلطنته التي دامت أربعًا وعشرين سنة الأراضي المفقودة بمعاهدة بلغراد ودعم إصلاح أوجاق القمبرة، وهو عائد من صلاة الجمعة. وخلفه أخوه عثمان الثالث الذي عاش في القفص حتى بلغ الثامنة والخمسين من عمره. وبدأت سلطنة قصيرة قلقة؛ وساد في عهد عثمان الثالث، الذي بدّل ستة صدور عظام في ثلاث سنوات، ركود واضح في شؤون الدولة.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["وفاة عثمان الثالث وجلوس مصطفى الثالث على العرش", "3ac10f85"], "d": ["بعد سلطنة دامت ثلاث سنوات، توفي عثمان الثالث، فاعتلى العرش مصطفى الثالث المنفتح على أفكار الإصلاح والمهتم اهتمامًا وثيقًا بشؤون الدولة. وحاول السلطان الجديد، مستندًا إلى خبرة الصدر الأعظم كوجه راغب باشا، إصلاح المالية وتجديد الجيش؛ وأُنشئت في هذه الفترة المدفعية السريعة التي أسسها البارون دو توت. غير أن الحرب الروسية التي دخلتها الدولة عام 1768 ستطغى على جميع مكاسب سلطنته التي دامت سبع عشرة سنة.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["إعلان الحرب على روسيا — حادثة بالتا وبدء حرب 1768-1774", "9c6aabe0"], "d": ["حين اقتحمت الوحدات الروسية والقوزاقية، وهي تطارد اتحاد بار في بولندا، بلدة بالتا على الحدود العثمانية وأحرقتها، قرّر الديوان الحرب وسُجن السفير الروسي في يدي قولة. وقد سارت الحرب، التي دُخلت دون استعداد عسكري جدي وأُعلنت قبل ستة أشهر، سيرًا سيئًا منذ بدايتها. وستتحول هذه المواجهة التي ستستمر ست سنوات، بغارة تشسمة وهزيمة قارطال واحتلال القرم، إلى إحدى أثقل سلاسل الهزائم في التاريخ العثماني.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["فقدان قلعة خوتين لمصلحة الروس", "66d43ea4"], "d": ["بعد أن صُدّت محاولتان للجيش الروسي بقيادة الأمير غوليتسين، انسحب الجيش إثر الهزيمة التي مُني بها الصدر الأعظم بين كامانيتشه وخوتين، وأخلى الحراس القلعة. وأدّى خروج أقوى تحصين عثماني شمال الدانوب من اليد دون مقاومة إلى فتح أبواب الأفلاق والبغدان أمام الروس. وقد احتُلّت الإمارتان في العام نفسه؛ ولم تُسترد خوتين إلا عام 1774 بمعاهدة كوتشوك قاينارجه.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["هزيمة سهل قارطال (كاغول)", "6f408eaf"], "d": ["بعد ثلاثة أسابيع من إحراق الأسطول في تشسمة، تفرّق الجيش العثماني الرئيسي على الدانوب في سهل قارطال أمام قوات المارشال روميانتسيف التي كانت أصغر منه عددًا بكثير لكنها منضبطة. ووقعت المعسكرات والأثقال ومئات المدافع في يد العدو؛ وتكبّدت الوحدات الهاربة خسائر فادحة وهي تعبر الدانوب. وأدّى تدمير الأسطول والجيش البري معًا في الصيف نفسه إلى سقوط كيلي وآق كرمان وإسماعيل وبندر الواحدة تلو الأخرى، وإلى احتلال القرم.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["الاحتلال الروسي لشبه جزيرة القرم", "217837b0"], "d": ["اجتازت الجيوش الروسية، التي كانت قد استولت على بوجاق قبل عام، بقيادة الأمير دولغوروكوف أور قابي، وغزت شبه جزيرة القرم بأكملها. وخُلع الخان عن عرشه وأُجلس صاحب كراي الموالي لروسيا، فكانت الخطوة الأولى في فصل الخانية عن الدولة العثمانية. وكان فقدان القرم، التي ظلت منذ ثلاثة قرون الدرع الشمالي للدولة، بداية مسار انتهى بالاستقلال عام 1774 ثم بالضم المباشر عام 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["وفاة مصطفى الثالث وجلوس عبد الحميد الأول على العرش", "42cba8e2"], "d": ["خلف أخو مصطفى الثالث عبد الحميد الأول، الذي أمضى ثلاثًا وأربعين سنة في قفص القصر، أخاه الذي توفي في أحرج لحظات الحرب الروسية، وجلس على العرش وهو في التاسعة والأربعين. واضطر السلطان الجديد، الذي ورث أصعب فترات الدولة، إلى مواجهة الشروط الثقيلة لمعاهدة كوتشوك قاينارجه التي ستُوقّع في العام نفسه. وسيمرّ عهده الذي دام خمس عشرة سنة بفقدان القرم وحرب روسية جديدة، وسينتهي بالسكتة التي أصابته وهو يقرأ خبر سقوط أوزي عام 1789.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["هزيمة قوزلجة — الهزيمة المؤدية إلى كوتشوك قاينارجه", "8e0542f9"], "d": ["هُزمت القوات العثمانية المحتشدة أمام شومنو في قوزلجة أمام الأذرع المتحدة لسوفوروف وكامينسكي، وتفرّق القسم الأكبر من الجيش. وبهذه الهزيمة لم تبقَ في البلقان قوة قادرة على المقاومة؛ فحاصرت طلائع الروس شومنو وصار مقرّ الصدر الأعظم مهددًا. وجلوس الدولة إلى المائدة في كوتشوك قاينارجه قبل أن ينقضي شهر، وقبولها شروطًا ثقيلة استثنائيًا، نتيجة مباشرة لهذه الهزيمة.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["التخلي عن بوكوفينا (شمال البغدان) للنمسا", "190f9caa"], "d": ["استفادت النمسا من الضعف الذي سببته كوتشوك قاينارجه، فطالبت بمنطقة بوكوفينا التي تصل بين البغدان وترانسلفانيا، وحصلت على هذه الأرض بالتهديد والرشوة دون أن تدخل الحرب. وقد قسم فقدان هذه المنطقة الخصبة الاستراتيجية الواقعة جنوب غربي خوتين إمارة البغدان فعليًا إلى قسمين. وعُدّ هذا التخلي الذي تمّ دون إطلاق رصاصة واحدة من أوضح المؤشرات على أن الدولة العثمانية لم تعد تملك القدرة على الردع.", "dc1e97dd"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["احتلال إيران للبصرة", "0161e709"], "d": ["استولى صادق خان، أخو حاكم الزند كريم خان، على البصرة بعد حصار دام سنة، وفقدت الدولة العثمانية أهم موانئها على الخليج العربي. وقد زعزع الاحتلال مباشرة طريق التجارة الهندية وإيرادات التمر واللؤلؤ والدفاع الجنوبي للعراق. ولم تُسترد المدينة إلا عام 1779، في أثناء صراعات العرش التي نشبت في إيران بوفاة كريم خان.", "838306ba"]},
"OLAYLAR_EK5:1779-03-10:0":{"b": ["تنقيح نامة عينلي قوّاق — تسوية مؤقتة بشأن القرم", "9b3b0468"], "d": ["وقّعت الدولتان، اللتان أوشكتا على الحرب بسبب من سيتولى خانية القرم، بوساطة فرنسا نصّ إيضاح في قصر عينلي قوّاق. فقبلت روسيا سحب جيشها من القرم، وقبلت الدولة العثمانية الاعتراف بخانية شاهين كراي الموالي لروسيا؛ وأُكّد حق السلطان الديني في الخلافة على القرم. وهذا التوازن الهش الذي سيستمر أربع سنوات انهار تمامًا عام 1783 بضمّ روسيا شبه الجزيرة ضمًّا مباشرًا.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["بناء قلعة أنابا — خط الدفاع القوقازي", "be92a80f"], "d": ["حين فُقدت القرم بعد كوتشوك قاينارجه، شُرع في بناء قلعة جديدة عند مصب نهر كوبان للحفاظ على النفوذ العثماني في القوقاز. وصارت أنابا، التي أُسست على أنقاض مستعمرة جنوية، بسوقها وحماماتها ودكاكينها التي تجاوزت المئتين والخمسين، مدينة تصل سريعًا بالقبائل الشركسية. وبقيت القلعة ثمانيًا وأربعين سنة أبعد موقع أمامي للدولة العثمانية في مواجهة نزول روسيا إلى القوقاز.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["عزل الصدر الأعظم خليل حميد باشا وإعدامه", "c44001ca"], "d": ["عُزل الصدر الأعظم المصلح خليل حميد باشا، الذي أظهر عبد الحميد الأول رضاه عن خدماته في مناسبات عدة، فجأة قبيل صباح 31 آذار/مارس 1785 ونُفي إلى غاليبولي وصودرت جميع أمواله. وأُسندت إليه أولًا إيالة الحبشة وسنجق جدة ومشيخة الحرم المكي؛ وبينما كان يمضي نيسان/أبريل 1785 في الاستعداد للسفر في بوزجه آدا، عُزل من هذه الولاية أيضًا، وقتله بفرمان الإعدام الصادر كاراكتخدازاده علي، من رجال جزائرلي غازي حسن باشا. وأُرسل رأسه المقطوع إلى إسطنبول وعُرض في أورتا قابي. وبحسب TDV فُسّر هذا السقوط المفاجئ باتهام تدبير مؤامرة لخلع السلطان وإجلاس الشاهزاده سليم، غير أن الأسباب الحقيقية لعلها كانت السخط على صمته عن ضم القرم وعداء الأوساط التي أضرت بها إصلاحاته ومعارضة غازي حسن باشا.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["إعلان الحرب على روسيا — بدء الحرب العثمانية الروسية 1787-1792", "3bfb870c"], "d": ["إثر رحلة كاترين الثانية الباذخة إلى القرم وإخضاعها جورجيا لحمايتها، قرّر الديوان الحرب بهدف التراجع عن الضم، وسُجن السفير الروسي في يدي قولة مرة أخرى. غير أن الجيش لم يكن جاهزًا والخزينة كانت خاوية والبحث عن حلفاء لم يُفضِ إلى نتيجة. وستنتهي الحرب التي ستدوم خمس سنوات بسقوط أوزي مصحوبًا بالمذبحة، وفقدان إسماعيل، والشروط الثقيلة لمعاهدة ياش.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["دخول النمسا الحرب — الصراع على جبهتين", "ae912290"], "d": ["أعلن الإمبراطور النمساوي يوسف الثاني الحرب على الدولة العثمانية، عملًا بالتحالف السري الذي عقده مع روسيا عام 1781، وتحرك نحو بلغراد والبوسنة. واضطر الجيش العثماني فجأة إلى القتال على جبهتين معًا: روسيا في الشمال والنمسا في الغرب. ورغم الانتصارات التي أُحرزت على النمساويين في لازارتخانه ومحاديه وشبش، فإن الجبهة الغربية ستنهار أيضًا بفقدان بلغراد عام 1789.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["التحالف العثماني البروسي", "03b88e51"], "d": ["وقّع سليم الثالث، الذي بحث عن حلفاء في أوروبا فور جلوسه على العرش، معاهدة تحالف مع بروسيا تنصّ على المساعدة المتبادلة؛ فتعهدت بروسيا بإعلان الحرب على روسيا والنمسا، وتعهدت الدولة العثمانية ألا تعقد صلحًا قبل استرداد القرم. وكان هذا أول نصّ تحالف متبادل حقيقي في التاريخ العثماني مع دولة أوروبية، ودلّ على التخلي عن المفهوم الكلاسيكي «لا تحالف مع الكفار». ولم تدخل بروسيا الحرب، لكنها أجبرت النمسا على الصلح ومهّدت الطريق لمعاهدة زشتوي.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["سقوط قلعة إسماعيل ومذبحتها", "6a296b0c"], "d": ["استُولي على قلعة إسماعيل، التي كانت تُعدّ أقوى تحصينات دلتا الدانوب، في يوم واحد بهجوم عام دموي نظّمه الجنرال سوفوروف؛ وأُعمل السيف في الحامية وأهل المدينة إلى حد بعيد. وقد أحدثت هذه المذبحة التي لقيت صدًى واسعًا في أوروبا صدمة عميقة في الرأي العام العثماني، وكسرت العمود الفقري لخط الدفاع على الدانوب. وستُسترد القلعة بعد عام بمعاهدة ياش، لكن مصير الحرب كان قد تحدد.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["معاهدة زشتوي — إغلاق الجبهة النمساوية", "58741f1d"], "d": ["بفضل ضغط بروسيا وانشغال النمسا في الغرب بالثورة الفرنسية، توصلت الدولتان إلى صلح على أساس الحدود السابقة للحرب. وأعادت النمسا جميع الأماكن التي احتلتها، بما فيها بلغراد؛ ولم تقبل الدولة العثمانية سوى تصحيحات صغيرة على الحدود الكرواتية. وأتاح إغلاق الجبهة الغربية بهذه الشروط للدولة العثمانية أن تجمع كل قواها ضد روسيا، وحدّ من الخسارة في معاهدة ياش.", "45643640"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["معاهدة ياش — الفقدان النهائي للقرم وحدّ نهر تورلا", "a56fd194"], "d": ["عُدّ نهر تورلا (دنيستر) حدًّا بموجب المعاهدة التي وُقّعت في ختام حرب دامت خمس سنوات؛ فبقيت ضفة النهر اليسرى لروسيا والضفة اليمنى للدولة العثمانية، وخرجت أوزي وما حولها نهائيًا من اليد. وتخلّت الدولة العثمانية تمامًا عن أمل استرداد القرم واعترفت قانونيًا بضم 1783؛ وأُعيدت الأفلاق والبغدان مع إعفاء من الضرائب مدة سنتين. وبقبول التزام بتعويض حرب قدره اثنا عشر مليون قرش، تُرك شمال البحر الأسود لروسيا بصورة دائمة. الأماكن الأخرى التي انضمت في التاريخ نفسه: إسماعيل.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["إخلاء الإسبان وهران وتسليمها للجزائر", "9f95cee6"], "d": ["لما دمّر زلزال 1790 القلعة والمدينة إلى حد كبير، لم تعد إسبانيا قادرة على تحمل حاميتها المكلفة التي أبقتها ثلاثة قرون، فاتفقت مع أوجاق الجزائر وسلّمت وهران والمرسى الكبير دون حرب. وهكذا صُفّي آخر موقع أوروبي على ساحل شمال إفريقيا. وسيبقى الجزائر العثمانية مسيطرًا على الساحل كله ثمانيًا وثلاثين سنة حتى الاحتلال الفرنسي.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["الحكم الفعلي لعثمان باز وان أوغلو في ويدين", "0ce70361"], "d": ["استولى عثمان باز وان أوغلو، الذي ثار على ترتيبات النظام الجديد، على ويدين بعد أن أجبر واليها على الفرار، وحصّنها بخنادق عميقة على طول الدانوب. وفي عام 1797، في ذروة قوته، جمع ما يقرب من ثمانين ألف مقاتل وبسط سيطرته على نيغبولو وزشتوي وروسجق وصوفيا ونيش؛ وقدّم نفسه مصلحًا لا متمردًا. وانتهى حصار الباب العالي الذي دام شهورًا في 1798-1799 دون نتيجة، فحكم شمال بلغاريا حكمًا شبه مستقل حتى وفاته عام 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["افتتاح مهندسخانة بري همايون", "e9a3a34b"], "d": ["افتُتحت مدرسة الهندسة البرية في خاص كوي لتخريج ضباط المدفعية والتحصينات والخرائط لجيش النظام الجديد؛ وكانت نظير مدرسة الهندسة البحرية التي أُسست عام 1773 في الجيش البري. وفي برنامجها دُرّست الجبر والهندسة والميكانيكا والتحصينات والبالستيات، وتُرجمت من اللغات الأوروبية كتب في الرياضيات والمدفعية. وتُعدّ هذه المدرسة، التي تُعتبر جذر تعليم الهندسة الحديث في تركيا، بداية جامعة إسطنبول التقنية اليوم.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["إعلان الحرب على فرنسا والتحالف مع روسيا وإنجلترا", "80e95bd7"], "d": ["إثر احتلال نابليون لمصر، نقضت الدولة العثمانية صداقتها التقليدية مع فرنسا التي دامت قرنين ونصفًا، وأعلنت عليها الحرب. وفي المسار نفسه تحالفت لأول مرة في تاريخها مع روسيا، وسمحت للأسطول الروسي بالمرور عبر المضائق إلى البحر المتوسط؛ ثم وُقّع تحالف مع إنجلترا أيضًا. وبفضل هذه التحالفات انتُزعت الجزر الأيونية من الفرنسيين، غير أن فتح المضائق أمام أسطول أجنبي شكّل سابقة ذات ثمن باهظ في المستقبل.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["الاستيلاء على بريفزة من الفرنسيين — معركة نيكوبوليس", "d8e5e892"], "d": ["حين سقطت جمهورية البندقية عام 1797، وقعت الجزر الأيونية وبريفزة وبارغا وفونيتسا على البر في يد فرنسا. فسار والي يانينا علي باشا التبدلنلي على بريفزة مستفيدًا من الحرب التي نشبت إثر احتلال فرنسا لمصر، وألحق بالحامية الفرنسية هزيمة ثقيلة في أنقاض نيكوبوليس خارج المدينة. وهكذا دخل هذا الميناء، الذي تُرك للبندقية في باساروفجة، بعد ثمانين سنة في الإدارة العثمانية.", "eeebcaf6"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["الدفاع عن عكا — صدّ نابليون", "56b5c45b"], "d": ["حاصر نابليون، وهو يتقدم من مصر إلى سوريا، عكا ونظّم هجمات متتالية استمرت شهرين؛ وكان الدفاع عن المدينة بقيادة جزار أحمد باشا، بدعم الأسطول الإنجليزي وبوحدات النظام الجديد التي أُرسلت من إسطنبول. واضطر نابليون إلى رفع الحصار والانسحاب إلى مصر، فدفن حلمه بالتوغل شرقًا أمام هذه الأسوار. وقوبل الخبر في إسطنبول بفرح عظيم، وعُدّ دليلًا على أن الجيش المدرَّب الذي أُنشئ حديثًا اجتاز أول امتحان جدي له.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["غارة الوهابيين على كربلاء", "522341ed"], "d": ["دخلت القوات الوهابية القادمة من نجد كربلاء ونهبت المدينة ودمّرت ضريح الإمام الحسين وقتلت أكثر من ثلاثة آلاف شخص. ولم يستطع ولاة المماليك العثمانيون في العراق منع الغارة؛ وأثار الحدث ردّ فعل عنيفًا في إيران وفي إسطنبول معًا. وكان هذا الهجوم إعلانًا بأن الحركة السعودية لم تعد إمارة واحة، بل تحولت إلى قوة إقليمية تهدد مدن الدولة العثمانية المقدسة.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-12:0":{"b": ["ضم كارتلي كاخيتي (جورجيا الشرقية) إلى روسيا", "3b650c5e"], "d": ["حُلّت مملكة كارتلي كاخيتي، التي قبلت الحماية الروسية عام 1783 وتعرضت للحملة الإيرانية المدمرة عام 1795؛ وأُعلنت إقليمًا روسيًا بأمر مؤرخ في 12 أيلول/سبتمبر 1801، وبدأ ترسيخ النظام الإداري الروسي. وفقدت جورجيا استقلالها اعتبارًا من هذا التاريخ؛ وفي غضون سنوات دخلت ميغريليا (1803) وإيميريتيا وغوريا (1804) أيضًا في السيادة الروسية، وبلغت روسيا الحد العثماني في القوقاز.", "957f5cd5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["جلاء الفرنسيين عن مصر", "00cfdc8c"], "d": ["نتيجة العمليات المشتركة البرية والبحرية للقوات العثمانية والإنجليزية، سُلّمت القاهرة أولًا ثم الإسكندرية، وأُرسلت القوات الفرنسية بالسفن إلى بلادها. وبانتهاء الاحتلال الذي دام ثلاث سنوات عادت مصر على الورق إلى الإدارة العثمانية، غير أن الصراع على السيادة بين البكوات المماليك والفرق الألبانية دفع البلاد إلى الفوضى. وقد مهّد هذا الفراغ في غضون بضع سنوات لصعود محمد علي الكافالي.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["معاهدة باريس — إعادة إقامة السلام مع فرنسا", "1b76991f"], "d": ["أنهت المعاهدة التي وُقّعت بعد جلاء الفرنسيين عن مصر حالة الحرب بين الدولة العثمانية وفرنسا رسميًا، وجُددت الامتيازات القديمة. وسُمح للسفن التجارية الفرنسية بدخول البحر الأسود؛ وفي المقابل اعترفت فرنسا بوحدة الأراضي العثمانية. ومنح إقرار السلام سياسة سليم الثالث الخارجية، التي كانت محصورة إلى جانب روسيا وإنجلترا، مجالًا جديدًا للمناورة.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["استيلاء الوهابيين على الطائف", "7b791359"], "d": ["حاصرت القوات الوهابية بقيادة سعود بن عبد العزيز الطائف ونهبتها في أول تحرك نحو الحجاز؛ وسقطت المدينة بوصفها أول باب مفتوح على الأراضي المقدسة. وكان ذلك بالنسبة إلى السلطان العثماني، حامل لقب خادم الحرمين، ضربة هزّت شرعية سلطنته مباشرة. وبعد شهرين ونصف سيزحف الجيش نفسه إلى مكة.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["استيلاء الوهابيين على مكة لأول مرة", "21157c05"], "d": ["بعد شهرين ونصف من سقوط الطائف، دخلت القوات الوهابية مكة وهدمت الأضرحة وأقامت نظامًا وفق فهمها؛ واضطر الشريف غالب إلى الانسحاب إلى جدة. وتردّد صدى إغلاق طرق الحج في العالم الإسلامي كله، وأجبر إسطنبول على طلب مساعدة عسكرية من والي مصر محمد علي. ولن تدوم هذه السيطرة الأولى إلا ثلاثة أشهر.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["استرداد الشريف غالب مكة", "83d08dff"], "d": ["حاصر الشريف غالب، الذي كان قد انسحب إلى جدة، مكة بالقوات التي جمعها، واستردّ المدينة من الوهابيين بعد حصار دام خمسة وعشرين يومًا؛ وقُرئت الخطبة باسم العثمانيين من جديد. ولن تدوم هذه السيطرة الثانية أيضًا، إذ ستستولي قوات سعود على المدينة مرة أخرى عام 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["بدء ثورة الصرب الأولى", "0f6e8767"], "d": ["حين قتل الدالاتية الإنكشاريون المتمردون، الذين استولوا على الحكم في بلغراد، وجهاء الصرب جماعيًا، بدأت مقاومة مسلحة بقيادة قره جورج. وقد تحولت الحركة، التي جرت في البداية ضد الدالاتية وحدهم مع بقاء الولاء للسلطان، سريعًا إلى ثورة قومية تطالب بالحكم الذاتي والاستقلال. واستولت القوات الصربية على بلغراد عام 1806؛ وكان هذا التمرد أولى حلقات حركات الاستقلال القومية في البلقان.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["احتلال الوهابيين للمدينة المنورة", "84e310d7"], "d": ["بعد مكة، وقعت المدينة المنورة أيضًا في يد القوات الوهابية؛ ووُزّعت خزينة الروضة المطهرة وهُدمت الأضرحة ذات القباب في المدينة. وهكذا خرجت المدينتان المقدستان معًا من السيطرة العثمانية، وتعذّر على قوافل الحج القادمة من الشام ومصر الانطلاق سنوات. ولم تُسترد المدينة المنورة إلا بعد سبع سنوات، عام 1812، على يد الجيش المصري بقيادة طوسون باشا ابن محمد علي باشا.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["بدء الحرب مع روسيا (الحرب العثمانية الروسية 1806-1812) وإغلاق المضائق", "ea170804"], "d": ["بعد انتصار نابليون في أوسترليتز، اقترب سليم الثالث من فرنسا وعزل أميري الأفلاق والبغدان رغم الضغط الروسي، فاحتلت الجيوش الروسية الإمارتين وبدأت الحرب. وأغلقت الدولة العثمانية المضائق أمام الأسطول الروسي؛ وفي المقابل انحازت إنجلترا إلى روسيا وأرسلت أسطولًا إلى إسطنبول. وستتداخل هذه الحرب التي ستدوم ست سنوات مع ثورة القباقجي وخلع سليم الثالث عن العرش، وستنتهي بفقدان بساربيا في معاهدة بوخارست عام 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["وصول الأسطول الإنجليزي إلى أمام إسطنبول (عملية داكوورث)", "195bb58f"], "d": ["أرادت إنجلترا إجبار الدولة العثمانية على قطع صلتها بفرنسا، فمرّرت الأسطول بقيادة الأميرال داكوورث عبر جناق قلعة وأرسته أمام إسطنبول. وبتوجيه من السفير الفرنسي سباستياني أيضًا، نفر أهل إسطنبول، وعُززت بطاريات الساحل في غضون أيام، واضطر الأسطول إلى الانسحاب قبل أن يقصف المدينة؛ وتكبّد في طريق العودة خسائر فادحة في جناق قلعة. وبتعرض العاصمة لتهديد من أسطول أجنبي من هذا القرب لأول مرة، وُضعت مسألة المضائق في قلب الدبلوماسية الأوروبية.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["خنق مصطفى الرابع حتى الموت", "eeb75c20"], "d": ["قُتل مصطفى الرابع المخلوع خنقًا بأمر أخيه محمود الثاني، إثر مقتل علمدار مصطفى باشا في غارة وإرادة المتمردين السير إلى القصر. ودُفن جثمانه في باغجه قابي في ضريح أبيه عبد الحميد الأول؛ وشاعت بين المتمردين إشاعة أن التابوت فارغ.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["معاهدة قلعة سلطانية — الصلح مع إنجلترا وقاعدة المضائق", "fe282117"], "d": ["انتهت الحرب بين الدولتين بالمعاهدة التي وُقّعت مع إنجلترا بعد فشل عملية داكوورث، وأُعيدت إلى التجار الإنجليز امتيازاتهم القديمة. وقيّد الحكم الوارد في النص، المعروف باسم «القاعدة القديمة»، أنه لا يجوز لأي سفينة حربية أجنبية أن تمر عبر المضائق في زمن السلم. وصار هذا المبدأ الأساس القانوني لجميع الترتيبات الدولية التي شكّلت نظام المضائق طوال القرن التاسع عشر.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["هزيمة سلوبوزيا — محاصرة جيش الدانوب", "54b60fd1"], "d": ["حوصر القسم الأكبر من الجيش العثماني، الذي عبر الدانوب أمام روسجق، في سلوبوزيا بمناورة التطويق التي نفذها كوتوزوف من الضفة المقابلة للنهر، وتُرك للجوع. واضطر آلاف الجنود إلى الاستسلام؛ وذابت القوة التي بيد الصدر الأعظم فعليًا، واضطر الباب العالي إلى طلب الهدنة بعد شهر. وهذه الهزيمة هي السبب المباشر لقبول التخلي عن بساربيا في معاهدة بوخارست عام 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["استرداد بلغراد وإخماد ثورة الصرب الأولى", "06f56f52"], "d": ["لم يستطع الثوار الصرب، الذين حُرموا من الدعم الروسي بمعاهدة بوخارست، الصمود أمام العمليات المشتركة للقوات القادمة من البوسنة والروميللي؛ فدخل خورشيد أحمد باشا بلغراد وأُخمدت الثورة التي دامت تسع سنوات إخمادًا تامًا. وفرّ قره جورج إلى النمسا، وعاد سنجق سمندرة إلى الارتباط المباشر بالإدارة العثمانية. غير أن التدابير القاسية التي طُبّقت ستفجّر بعد سنتين ثورة ثانية دائمة بقيادة ميلوش أوبرينوفيتش.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["ثورة الصرب الثانية ورئاسة ميلوش أوبرينوفيتش للكنَزات", "e6e82ad2"], "d": ["اندلعت ثورة جديدة بقيادة ميلوش أوبرينوفيتش ضد التدابير الثقيلة التي طُبّقت بعد إخماد الثورة الأولى؛ وفضّل الباب العالي هذه المرة التسوية على القوة. وبموجب الاتفاق اعتُرف بميلوش بصفة «الكنَز الأكبر»، وتُركت لكنَزات الصرب صلاحية جباية الضرائب وإدارة الشؤون الداخلية. وكانت هذه النواة الأولى للحكم الذاتي الفعلي نقطة بداية المسار الذي امتد إلى فرمان 1830 واستقلال 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["ثورة الأفلاق — عبور يبسيلانتي نهر بروت وتمرد فلاديميريسكو", "67d46a98"], "d": ["حاول ألكسندر يبسيلانتي، وهو جنرال في الجيش الروسي، عبور نهر بروت باسم الجمعية الودية (إتنيكي هيتيريا) لإطلاق ثورة يونانية عامة في الأفلاق والبغدان؛ وفي الأيام نفسها حرّك تودور فلاديميريسكو فلاحي البلاد. ولم تتحد الحركتان: فقد ردّ فلاديميريسكو على دعوة يبسيلانتي إلى القتال معًا ضد الأتراك بقوله «لم أثر على الأتراك بل على اليونانيين»، وقُتل بعد وقت قصير على يد رجال يبسيلانتي. وأخمدت القوات العثمانية الثورة في أيار/مايو، لكن نظام الأمراء الفناريين انتهى وانتقلت شرارة الثورة إلى المورة.", "935b260a"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["تأسيس الدولة السعودية الثانية في الرياض", "34dad3bd"], "d": ["بعد ست سنوات من سقوط الدرعية عام 1818 وانهيار الدولة السعودية الأولى، أخرج تركي بن عبد الله الحاميات المصرية من نجد وأسس إمارة سعودية جديدة مركزها الرياض. وآثرت البنية الجديدة البقاء في نجد متجنبة الامتداد إلى الحجاز، وابتعدت عن الصدام المباشر مع القوات العثمانية المصرية. وستستمر هذه الدولة الثانية حتى نهاية القرن، وتشكّل الحلقة الثانية من السلسلة المؤدية إلى تأسيس المملكة العربية السعودية الحالية. الأماكن الأخرى التي خرجت من اليد في التاريخ نفسه: الدرعية (نجد).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["معاهدة آق كرمان — تنازلات لصربيا والإمارتين", "c75f15d0"], "d": ["اضطرت الدولة العثمانية، التي بقيت بلا جيش مباشرة بعد إلغاء أوجاق الإنكشارية، إلى قبول معاهدة ثقيلة الشروط أمام إنذار روسيا. فأُكّد الحكم الذاتي الموعود لصربيا، وقُبل ألا يُعزل أميرا الأفلاق والبغدان دون موافقة روسيا، ومُنحت السفن التجارية الروسية حرية كاملة في المضائق. وحين أعلن الباب العالي بعد سنتين، بسبب المسألة اليونانية، أنه لا يعترف بالمعاهدة، ستعدّ روسيا ذلك مبررًا للحرب.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["تصفية نظام التيمار", "84d5d1d6"], "d": ["بعد سنة من إلغاء أوجاق الإنكشارية، حُوّل نحو 5.200 من فرسان السباهية أصحاب التيمار في ثلاثة وخمسين سنجقًا في الروميللي والأناضول، مع إيرادات تيمارهم، إلى فرسان عساكر المنصورة. وبذلك انتهى فعليًا نظام التيمار، الذي كان العمود الفقري لنظام الأرض والضرائب والجيش العثماني طوال أربعة قرون. وسُلّمت التيمارات الشاغرة إلى الخزينة، ومُهّد الطريق للانتقال إلى جيش مركزي بالرواتب ونظام ضرائب نقدية.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["تأسيس طب خانه عامره — بداية التعليم الطبي الحديث", "ac3e57c0"], "d": ["افتُتحت طب خانه عامره في شهزاده باشي بناءً على اقتراح كبير الأطباء مصطفى بهجت أفندي، لتخريج الأطباء والجراحين لجيش عساكر المنصورة المؤسَّس حديثًا. ونُظّمت الدروس وفق المنهج المعمول به في أوروبا، وكان التدريس في البداية بالفرنسية؛ وبعد سنوات أُسست جراح خانه عامره أيضًا ودُمجت المؤسستان. وتُعدّ هذه المدرسة، التي تُعتبر بداية التعليم الطبي الحديث في تركيا، أصل كلية الطب في إسطنبول اليوم.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["بدء الحرب العثمانية الروسية 1828-1829", "9dff4e05"], "d": ["بعد إحراق الأسطول في نافارين وإعلان الباب العالي أنه لا يعترف بمعاهدة آق كرمان، أعلنت روسيا الحرب من جبهتين معًا. ولأن أوجاق الإنكشارية كان قد ألغي لتوّه، وكان الجيش الجديد في طور التأسيس، كان الدفاع العثماني ضعيفًا منذ البداية؛ وفيما عبر الروس الدانوب استولوا في الشرق على قارص وأخالتسيخه. وستفرض الجيوش الروسية التي تقدمت خلال سنة حتى أدرنة الشروط الثقيلة لمعاهدة أدرنة عام 1829 واستقلال اليونان.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["أول معاهدة مع الولايات المتحدة الأمريكية", "d737516f"], "d": ["بموجب معاهدة التجارة والملاحة التي وُقّعت بعد سنوات من الاتصالات، نالت الولايات المتحدة مكانة الأمة الأولى بالرعاية في الأراضي العثمانية وحق المرور التجاري عبر المضائق. ونصّ بند سري منفصل على أن تبني الدولة العثمانية سفنًا في الأحواض الأمريكية متى شاءت وأن تشتري سفنًا جاهزة وأخشابًا؛ وصدّق مجلس الشيوخ الأمريكي على المعاهدة لكنه رفض هذا البند السري بأغلبية 27 صوتًا مقابل 18. ومع ذلك لم يُغلق طريق السفن: فقد باع هنري إكفورد الدولة العثمانية سفينة جاء بها عام 1831، وأضاف الحرفيون الأمريكيون العاملون في عينلي قوّاق إلى الأسطول سفنًا من طراز جديد. وكانت هذه المعاهدة وثيقة أول علاقة شاملة أقامتها الدولة العثمانية مع دولة خارج أوروبا.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["إنهاء حكم المماليك في بغداد", "7e1d38a3"], "d": ["أعلن محمود الثاني، الذي اتبع سياسة المركزية، والي بغداد داود باشا عاصيًا لأنه لم يرسل المال المطلوب وقتل الموظف الذي جاء من المركز. فاستولت القوة بقيادة علي رضا باشا على المدينة بعد حصار دام تسعين يومًا، وصُفّي المماليك جميعًا تقريبًا. وبذلك انتهى حكم المماليك شبه المستقل المستمر منذ عام 1704، وارتبط العراق من جديد بالمركز ارتباطًا مباشرًا.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["تأسيس المكتب الحربي في ثكنة ماتشكا", "bf31c7d9"], "d": ["افتُتح مكتب الفنون الحربية في ثكنة ماتشكا لتزويد عساكر المنصورة المحمدية بضباط تدرّبوا على الطراز الأوروبي. ودُرّس الطلاب الرياضيات والخرائط والتحصينات واللغات الأجنبية؛ وبعد وقت قصير أُرسل طلاب إلى فيينا وباريس لتقوية الملاك. وكانت هذه المدرسة المكان الذي وُلد فيه تقليد الضابط الخريج من المدارس في الجيش العثماني، ومن ثم جيل الجندي المثقف الجديد الذي سيظهر في أواخر القرن التاسع عشر.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["ربط طرابلس الغرب بالمركز مباشرة — نهاية الأسرة القرمانلية", "faabcb96"], "d": ["إثر صراعات العرش داخل الأسرة القرمانلية وازدياد الضغط الأوروبي بعد احتلال فرنسا للجزائر عام 1830، تدخل الباب العالي مباشرة في طرابلس الغرب. فدخل الأسطول المرسل من إسطنبول المدينة، وعُزل آخر بكوات القرمانليين وجيء به إلى إسطنبول، وسُلّمت الإيالة إلى والٍ يعيَّن من المركز. وبانتهاء عهد الأسرة الذي دام 124 سنة، ترسخ آخر جزء من الأراضي في شمال إفريقيا تديره الدولة العثمانية مباشرة.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["إلغاء الدفترداريّة وتأسيس نظارة المالية", "89f8125e"], "d": ["أُلغي منصب الدفتردار، رأس النظام المالي العثماني الكلاسيكي، وأُسست نظارة المالية، وهي وزارة على الطراز الأوروبي، وجُمعت الخزائن المتفرقة في يد واحدة. وفي العام نفسه أُعيد تنظيم وحدات الباب العالي الأخرى تحت اسم النظارة، فانتُقل إلى بنية مجلس وزراء حديث. وكان هذا الترتيب من أهم الخطوات التي هيأت البنية الإدارية لفرمان التنظيمات الذي سيُعلن بعد سنة.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["استقرار الإنجليز في عدن", "ddbd556b"], "d": ["أنزلت إنجلترا جنودًا في ميناء عدن وبسطت سيطرتها على المدينة، استنادًا إلى اتفاقية التجارة والصداقة التي وقّعتها عام 1802 مع سلطان لحج أحمد بن عبد الكريم. وتحول هذا الميناء، الذي يمسك مدخل البحر الأحمر، إلى نقطة محورية في استراتيجية الإمبراطورية الإنجليزية بوصفه قاعدة تموين بالفحم على طريق الهند. ورغم أن ادعاء الدولة العثمانية في اليمن ظل قائمًا على الورق، فإن سيطرتها الفعلية على الساحل الجنوبي لم تعد بعد هذا التاريخ.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["العودة إلى ساحل تهامة: الاستيلاء على الحديدة وزبيد والمخا", "353982d2"], "d": ["نزلت القوات بقيادة توفيق باشا، تحت إشراف شريف مكة، إلى ساحل اليمن الذي ترك دون صاحب بانسحاب الجيش المصري عام 1840، وضمّت موانئ الحديدة وزبيد والمخا إلى الإدارة العثمانية. ورغم الرغبة في التقدم حتى صنعاء، عادت القوات إلى الحديدة بسبب مقاومة الأهالي؛ فبقيت المرتفعات في يد الأئمة الزيديين، واقتصرت السيادة العثمانية ثلاثًا وعشرين سنة على شريط تهامة. ولم يُسترد اليمن الداخلي إلا بحملة أحمد مختار باشا عام 1872.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["اتفاقية بالطه ليمانى: حماية عثمانية روسية مشتركة على الأفلاق والبغدان", "d3bb22e9"], "d": ["كانت القوات العثمانية والروسية قد احتلت الإمارتين معًا إثر انتقال ثورات 1848 إلى الأفلاق والبغدان. وبالاتفاقية الموقعة في بالطه ليمانى تقرر أن يُعيَّن الأمراء من قبل السلطان لمدة سبع سنوات بدلًا من الانتخاب، وأن تقيم الدولتان رقابة مشتركة في المنطقة. وبينما حفظ الاتفاق سيادة الدولة العثمانية على الورق، فقد منح روسيا حق شراكة فعلية، وعجّل انفصال إمارات الدانوب عن الدولة العثمانية.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["مسألة اللاجئين المجريين: لجوء كوسوت ورفاقه إلى الدولة العثمانية", "1c7d7ef4"], "d": ["بعد قمع الثورة المجرية 1848-1849 بالتدخل الروسي النمساوي، لجأ لايوش كوسوت وآلاف اللاجئين المجريين والبولنديين إلى الأراضي العثمانية. وطالبت النمسا وروسيا بشدة بتسليم اللاجئين؛ ورفض الباب العالي التسليم بدعم من إنجلترا وفرنسا، وأسكن المجموعة في كوتاهية. وأقام محيط كوسوت هنا نحو ثمانية عشر شهرًا، وأسلم مئات اللاجئين ودخلوا الخدمة العثمانية. وعُدّ الحدث من الانتصارات الدبلوماسية النادرة التي رفعت مكانة الدولة العثمانية في عهد التنظيمات في الرأي العام الأوروبي.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["تأسيس أنجمن دانش: أول أكاديمية عثمانية في إسطنبول", "6fda1365"], "d": ["أنجمن دانش، التي أُسست بقرار من مجلس المعارف العمومية، هي أول أكاديمية علمية عثمانية أُنشئت لإعداد الكتب العلمية والدراسية بالتركية. وافتُتحت بحفل في مبنى دار المعارف في 18 تموز/يوليو 1851؛ وكان من أعضائها المحليين والأجانب أحمد جودت باشا. ورغم قصر عمرها، فإن مؤلفات مثل «تاريخ» جودت باشا و«قواعد عثمانية» كانت من نتاج هذه المؤسسة، وعُدّت حجر الزاوية في صيرورة التركية لغة علم.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["انتصار أولتينيتسا: أول نجاح عثماني على جبهة الدانوب", "a660ad2f"], "d": ["في المرحلة الافتتاحية لحرب القرم، عبر القائد العام عمر لطفي باشا الدانوب وصدّ القوات الروسية في أولتينيتسا بخسائر فادحة. وأوقف الانتصار التقدم الروسي في مطلع الحرب، وأظهر لأوروبا القوة التي اكتسبها الجيش العثماني بالتدريب بعد التنظيمات. وهيأ هذا النجاح الأرضية النفسية التي سهّلت قرار إنجلترا وفرنسا دخول الحرب إلى جانب الدولة العثمانية.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["معاهدة التحالف مع إنجلترا وفرنسا في إسطنبول", "04809278"], "d": ["نصّت معاهدة التحالف الموقعة بين الدولة العثمانية وإنجلترا وفرنسا في حرب القرم ضد روسيا على أن تخوض الدول الثلاث عملياتها معًا وألا يعقد الحلفاء صلحًا منفردًا قبل انتهاء الحرب. وهكذا دخلت الدولة العثمانية للمرة الأولى في تاريخها في تحالف عسكري مع دول أوروبية كبرى بصفة طرف متساوٍ. وشكّلت هذه المعاهدة الأساس القانوني لقبول الدولة العثمانية رسميًا بعد سنتين في باريس في نظام الدول الأوروبية.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["تأسيس شهر أمانتي إسطنبول: أول تنظيم بلدي حديث", "be4af27f"], "d": ["كشفت أزمة البنية التحتية الناجمة عن تكدس جنود الحلفاء في إسطنبول وازدياد السكان في أثناء حرب القرم قصور الإدارة الكلاسيكية للمدينة القائمة على القضاء. وجُمعت في يد واحدة، بفضل شهر أمانتي المؤسَّسة على النماذج الأوروبية، أعمال النظافة والنرخ ومراقبة الأسواق والتعمير؛ وفي العام التالي أُسست في بيوغلو-غلطة دائرة البلدية السادسة منطقة تجريبية. وتُعدّ هذه الخطوة بداية العمل البلدي الحديث في الدولة العثمانية.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["معاهدة باريس: نهاية حرب القرم وقبول الدولة العثمانية في نظام الدول الأوروبية", "4aee0e2a"], "d": ["بمعاهدة باريس التي أنهت حرب القرم، أُعلنت الدولة العثمانية عضوًا متساويًا في القانون الدولي الأوروبي ووُضعت وحدة أراضيها تحت الضمان المشترك للدول الكبرى. وحُيّد البحر الأسود، وأُبطل ادعاء روسيا حماية الرعايا الأرثوذكس الذي حصلت عليه منذ كوتشوك قاينارجه، وأُعطي جنوب بساربيا (أقضية كيلي وقاهول وإسماعيل وبولغراد) إلى البغدان. غير أن المعاهدة نفسها جعلت فرمان الإصلاح التزامًا دوليًا، فأتاحت بذلك باب التدخل في الشؤون الداخلية.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["افتتاح قصر دولمه بهجه: نقل مركز الإدارة من طوب قابي", "71ad26d0"], "d": ["افتُتح القصر الذي طلبه عبد المجيد عام 1842 من أسرة باليان بعد أربع عشرة سنة من البناء، ونُقل مركز إدارة الدولة من طوب قابي، الذي دام أربعة قرون، إلى ضفة البوسفور. وبطرازه الأوروبي وسلمه البلوري وقاعة المعايدة، صار القصر التعبير الحجري عن طموح التنظيمات إلى التغريب. أما كلفته الهائلة فصارت أكثر بنود السنوات التي دخلت فيها المالية العثمانية دوامة الاستدانة الخارجية انتقادًا.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["اتحاد الأفلاق والبغدان بقيادة كوزا: ولادة رومانيا", "baef4da5"], "d": ["في الانتخابات التي أُجريت بعد معاهدة باريس، انتخبت الإمارتان معًا العقيد ألكسندرو يون كوزا أميرًا، وحققتا الاتحاد الفعلي. ورغم معارضة الباب العالي والنمسا، اضطُرّ إلى قبول الأمر الواقع بدعم من فرنسا. وسيتخذ هذا الاتحاد، الذي بقي تابعًا للدولة العثمانية على الورق، اسم رومانيا عام 1862، وسيعلن استقلاله من جانب واحد عام 1877؛ وهو نقطة تحول في تفكك السيادة العثمانية على الدانوب.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["حادثة كوللي: أول محاولة انقلاب على عبد المجيد في إسطنبول", "e3653b21"], "d": ["خطّطت جمعية سرية مختلطة من العسكريين والمدنيين، ناقمة على سياسة التنظيمات والمساواة التي منحها فرمان الإصلاح لغير المسلمين، لخلع السلطان عن العرش، فداهمتها السلطات في أثناء اجتماع في جامع قيليج علي باشا. وسُمّي الحدث بهذا الاسم لأن المتهمين حوكموا في ثكنة كوللي؛ وحوّلت أحكام الإعدام إلى نفي. ويُعدّ أول محاولة انقلاب في القصر أقدمت عليها منظمة أُسست لدواعٍ أيديولوجية في التاريخ العثماني.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["الحرب الأهلية الدرزية المارونية في جبل لبنان وأحداث دمشق", "5595fdd6"], "d": ["تحولت الاشتباكات التي اندلعت في أيار/مايو 1860 بمقتل درزيين قرب صيدا إلى أدمى حرب أهلية درزية مارونية في الجبل، وامتدت في تموز/يوليو إلى دمشق وانتهت بمقتل آلاف المسيحيين. وإثر إنزال فرنسا جنودها، أرسل الباب العالي فؤاد باشا إلى المنطقة بصلاحيات استثنائية؛ فجرت حركة قمع شديدة. وكانت الأحداث مبررًا للتدخل الأوروبي وسببًا مباشرًا لنيل لبنان وضعًا خاصًا.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["بدء صدور ترجمان أحوال: أول صحيفة تركية خاصة في إسطنبول", "24792957"], "d": ["ترجمان أحوال، التي أصدرها آغاه أفندي وتولى شناسي رئاسة تحريرها، أول صحيفة تركية تصدر دون دعم من الدولة. ودُوفع في المقدمة الواردة في عددها الأول عن حق الناس في أن يتكلموا في شؤونهم، وفتحت الصحيفة باب الأدب التركي الحديث أيضًا بنشرها مسرحية شناسي «زواج شاعر» مسلسلة. ويُعزى مولد مفهوم الرأي العام والصحافة المعارضة في الدولة العثمانية إلى هذا التاريخ.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["نظام جبل لبنان: وضع المتصرفية ذات الامتياز للبنان", "bf375603"], "d": ["جعل النظام الذي أُعدّ بضغط من الدول الكبرى بعد مجازر 1860 جبل لبنان متصرفية ذات امتياز مرتبطة بالباب العالي مباشرة، تُدار بمجلس إدارة مؤسَّس وفق التوازن بين الطوائف. واشتُرط أن يكون المتصرف من رعايا الدولة العثمانية من المسيحيين الكاثوليك وأن يُعرض تعيينه على موافقة الدول الكبرى؛ وكان أول متصرف داود باشا. وسيستمر هذا النظام حتى عام 1915، وسيشكّل نواة دولة لبنان الحديثة.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["وفاة عبد المجيد وجلوس السلطان عبد العزيز على العرش", "27204d7c"], "d": ["خلف أخو عبد المجيد عبد العزيز على العرش حين غلب السلّ عبد المجيد، الذي وقّع في سلطنته التي دامت اثنتين وعشرين سنة فرماني التنظيمات والإصلاح. وأعطى السلطان الجديد الأمل في سنواته الأولى بتدابير التوفير وعيشه البسيط، وجعل الأسطول إحدى القوى القليلة المعدودة في العالم. غير أن الدين الخارجي الثقيل وإفلاس 1875 وثورات البلقان ستتراكم في نهاية سلطنته وتهيّئ الأرضية لحركة الخلع عام 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["اتخاذ الإمارتين المتحدتين اسم رومانيا", "d960e3fc"], "d": ["الأفلاق والبغدان، اللتان اتحدتا فعليًا عام 1859 بانتخاب كوزا مرتين، جمعتا مجلسيهما وحكومتيهما تحت سقف واحد في بوخارست عام 1862 واتخذتا رسميًا اسم رومانيا. ورغم أن الدولة العثمانية احتفظت قانونيًا بصفة السيادة والجزية السنوية، فقد فقدت فعليًا رقابتها على الإمارة. ويُرمز بهذا التاريخ إلى نهاية النفوذ العثماني الذي دام أربعة قرون شمال الدانوب.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["ضم سواكن ومصوع ودهلك إلى مصر", "a0924860"], "d": ["مصوع، التي منحها السلطان عبد المجيد عام 1846 لوالي مصر محمد علي باشا مع سواكن على سبيل «سالیانه» (تخصيص إيراد)، أُدرجت في عهد الخديوي إسماعيل باشا مع دهلك وسواكن في أملاك مصر وتشكلت فيها قائمقامية. وهكذا انتقلت هذه الموانئ الثلاثة على الساحل الأفريقي للبحر الأحمر، مع بقائها قانونيًا أرضًا عثمانية، من الباب العالي مباشرة إدارةً إلى القاهرة، فدخلت في طبقة التبعية نفسها مع جارتها مصر والسودان.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["بدء ثورة كريت (1866-1869)", "3679b861"], "d": ["جعل التمرد الواسع الذي اندلع في الجزيرة بدعم صريح من اليونان مطلب نصارى كريت من الروم بالإينوسيس (الانضمام إلى اليونان) مسألة دولية للمرة الأولى. وكبّدت حرب الجبال الضارية التي دامت ثلاث سنوات الجيش العثماني خسائر فادحة، وأثارت صدى واسعًا في الرأي العام الأوروبي. ولم تخمد الثورة إلا عام 1868، حين توجه عالي باشا إلى الجزيرة وأنفذ النظام الذي منح امتيازات واسعة.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["جلاء آخر الحاميات العثمانية عن قلاع بلغراد وصربيا", "b34217db"], "d": ["بضغط من الدول الكبرى وإصرار الأمير ميخائيلو، قبل الباب العالي إخلاء آخر القواعد العسكرية التي بقيت في يده في صربيا؛ وفي 18 نيسان/أبريل 1867 أُنزل العلم العثماني عن قلعة بلغراد وسُلّمت المفاتيح إلى الأمير. وبذلك انتهى الوجود العسكري العثماني الفعلي القائم منذ عام 1521، وزالت آخر عقبة كبرى في طريق صربيا إلى الاستقلال. واختُزلت سيادة السلطان إلى مسألة علم رمزي وجزية فحسب.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["منح والي مصر لقب الخديوي", "09e10c12"], "d": ["نتيجة الضغط الشديد الذي مارسه إسماعيل باشا من الجيل الثالث للأسرة الكافالية والأموال التي ضخّها إلى إسطنبول، مُنح والي مصر لقب الخديوي الذي يؤكد تفوقه على سائر الولاة. وفي السنوات نفسها عُدّل نظام الوراثة بحيث ينتقل من الأب إلى الابن، ومُنحت مصر صلاحيات ذات طابع سيادي كالاستدانة الخارجية ومنح الأوسمة وإبقاء القنصليات. وتُعدّ هذه الخطوات الحلقة الأولى في السلسلة التي عجّلت انفصال مصر قانونيًا عن الدولة العثمانية.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["نظام كريت: امتيازات إدارية واسعة للجزيرة", "12052262"], "d": ["انتقل الصدر الأعظم عالي باشا بنفسه إلى الجزيرة لإنهاء الثورة التي دامت ثلاث سنوات، ومُنح الكريتيون بالنظام الذي نُشر بموافقة السلطان مجالس إدارة مختلطة ومحاكم محلية واستخدام الرومية في المعاملات الرسمية وتسهيلات ضريبية. وأبقى هذا الترتيب السيادة العثمانية في الجزيرة ثلاثين سنة أخرى. غير أن الامتيازات الممنوحة للسكان المسيحيين أضعفت مكانة الكريتيين المسلمين وبذرت بذور أزمة 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["افتتاح شورى الدولة: تأسيس مجلس الدولة العثماني", "70b16497"], "d": ["بالإرادة المؤرخة في 5 آذار/مارس 1868 قُسّم مجلس أحكام عدلية إلى قسمين، فأُوكلت الشؤون الإدارية التشريعية إلى شورى الدولة والشؤون القضائية إلى ديوان أحكام عدلية؛ وافتُتحت المؤسسة بحفل في الباب العالي وعُيّن مدحت باشا أول رئيس لها. وكُلّفت بإعداد مشاريع القوانين وحل المنازعات الإدارية وإجراء محاكمات الموظفين. وتُعدّ، بتركيبتها من الأعضاء المسلمين وغير المسلمين، أول تطبيق مؤسسي لفكرة الفصل بين السلطات في الدولة العثمانية.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["افتتاح قناة السويس: اختصار طريق الهند عبر مصر", "377ccd04"], "d": ["دام البناء الذي بدأ عام 1859 عشر سنوات، ودخلت القناة التي تربط البحر المتوسط بالبحر الأحمر بطول 163 كيلومترًا الخدمة في حفل مهيب. وحين اختُصر الطريق الواصل بين أوروبا والهند آلاف الأميال، صارت مصر فجأة نقطة محورية في التجارة العالمية. وستكون هذه القيمة الجيوستراتيجية السبب الرئيسي في احتلال إنجلترا لمصر بعد ثلاث عشرة سنة من افتتاح القناة؛ أما الدين الذي حملته القناة لمصر فسيدفع الخديوية إلى الإفلاس.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["تأسيس الإكسرخسية البلغارية: انفصال الكنيسة البلغارية عن الفنار", "33a8272c"], "d": ["بفرمان من السلطان أُسست كنيسة بلغارية مستقلة (إكسرخسية) منفصلة عن بطريركية الروم، وتُرك لاستفتاء الأهالي تحديد الأقضية التي ستتبع الإكسرخسية. ورغم أن الباب العالي اتخذ هذه الخطوة لكسر النفوذ الرومي، فقد جاءت النتيجة معاكسة: إذ تحولت الكنيسة إلى المركز المنظّم للهوية القومية البلغارية وللادعاء البلغاري في مقدونيا. وهكذا وُضعت الأرضية المؤسسية للتنافس البلغاري الرومي الصربي في البلقان وثورات 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["ضم عسير إلى الإدارة المباشرة", "4559e099"], "d": ["حين ازدادت القيمة الاستراتيجية للبحر الأحمر بافتتاح قناة السويس، رُئي أنه لا يمكن ترك جبال عسير، الواقعة في منتصف الطريق البري المؤدي إلى اليمن، دون رقابة. فدخلت قوات رديف باشا، الخارجة في حملة اليمن، أبها وربطت المنطقة بالإدارة العثمانية المباشرة، وأُسس سنجق عسير. ولم تستقر هذه السيادة قط استقرارًا تامًا بسبب الجغرافيا الجبلية ونفوذ الأدارسة.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["حملة مدحت باشا على نجد: إعادة إقامة السيادة العثمانية في الأحساء", "7db51461"], "d": ["استفاد والي بغداد مدحت باشا من صراع العرش داخل الأسرة السعودية، فأرسل جنودًا إلى الساحل الغربي للخليج العربي وربط منطقة الأحساء بولاية البصرة باسم سنجق نجد. وعُيّن عبد الله بن فيصل متصرفًا فأُقيمت السيادة العثمانية على الورق. وكانت الحملة تهدف إلى وقف انتشار النفوذ الإنجليزي في الخليج، وأدّت في العام نفسه إلى دخول قطر أيضًا تحت السيطرة العثمانية.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["وفاة الصدر الأعظم عالي باشا: نهاية جيل التنظيمات", "1cf0141c"], "d": ["بوفاة عالي باشا، الذي تحمل وحده سياسة التنظيمات بعد وفاة فؤاد باشا عام 1869، انقرض جيل الدبلوماسيين البارعين الذي أدار السياسة الخارجية للدولة ثلاثين سنة. وعزّزت إدارة محمود نديم باشا الذي خلفه، الموالية لروسيا والمتسلطة، حكم عبد العزيز الشخصي. وفي غضون خمس سنوات بعد وفاة عالي باشا أفلست المالية وثار البلقان وصار تغيير السلطنة أمرًا لا مفر منه.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["إقامة السيطرة العثمانية في قطر", "3b453165"], "d": ["بدعوة من الشيخ قاسم بن ثاني الذي كان تحت الضغط الإنجليزي، نزلت القوات العثمانية في شبه جزيرة قطر، وتحققت في خريف 1871 السيطرة العثمانية في المنطقة. ونُظّمت قطر قضاءً تابعًا لسنجق نجد، وعُيّن الشيخ قائمقامًا. وكانت هذه الخطوة أبرز مكسب للسياسة المتقدمة التي مارسها مدحت باشا ضد إنجلترا في الخليج؛ وخفق العلم العثماني في شبه الجزيرة حتى عام 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["فرمان الوراثة لتونس — البكوية لأسرة محمد الصادق باشا", "1509ebb0"], "d": ["بفرمان صدر بمساعي خير الدين باشا الذي أرسله باي تونس محمد الصادق باشا إلى إسطنبول مغتنمًا هزيمة فرنسا أمام بروسيا، مُنحت تونس بنظام الوراثة لمحمد الصادق باشا وذريته على أن تبقى مرتبطة بإسطنبول مباشرة. ونصّ الفرمان على ألا تُجرى مفاوضات حرب أو سلم دون إذن السلطان، وألا يُعطى أي جزء من البلاد لغيره، وأن تُلبّى طلبات الدولة العثمانية من الجنود. ولم تعترف فرنسا بالفرمان؛ وبعد عشر سنوات احتلت تونس.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["الاستيلاء على صنعاء: إعادة إقامة السلطة العثمانية في اليمن", "978e20a0"], "d": ["حين ازدادت القيمة الاستراتيجية للبحر الأحمر بافتتاح قناة السويس، أرسل الباب العالي إلى اليمن جيش الفرقة الاحتياطية بقيادة أحمد مختار باشا. وبالاستيلاء على صنعاء أُعيدت سلطة الدولة في اليمن الداخلي الذي فُقد فعليًا منذ قرنين، وصارت المنطقة ولاية. غير أن الصراع مع الأئمة الزيديين لم ينتهِ قط؛ وشكّلت ثورات 1891 و1898 و1904 أغلى جبهة داخلية للدولة العثمانية وأطولها أمدًا. الأماكن الأخرى التي انضمت في التاريخ نفسه: صنعاء، تعز.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["بدء ثورة الهرسك: تجدد اشتعال المسألة الشرقية", "571b18ec"], "d": ["ثورة الفلاحين المسيحيين حول نيفيسينيه بسبب الضرائب الثقيلة وضغط الأعيان امتدت سريعًا إلى الهرسك كلها، وغذّاها متطوعون جاؤوا من صربيا والجبل الأسود. وأدت الثورة إلى فرض النمسا وروسيا إصلاحات، وأطلقت في العام التالي الثورات البلغارية وإعلانات الحرب الصربية والجبل الأسودية. وبذلك انكسرت الحلقة الأولى من السلسلة الكبرى المؤدية إلى حرب 93 وفقدان البلقان بمعاهدة برلين.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["إفلاس المالية العثمانية: خفض مدفوعات الدين الخارجي إلى النصف", "2cac2fa5"], "d": ["حوّلت القروض التي أُخذت تباعًا منذ عام 1854 ونفقات حرب القرم وإنشاءات القصور ومجاعة الأناضول 1873-1874 عجز الميزانية إلى هوّة تجاوزت خمسة ملايين ليرة. وأعلنت حكومة محمود نديم باشا أن مدفوعات الفائدة وأصل الدين ستُخفض إلى النصف مدة خمس سنوات، فأعلنت فعليًا تأجيلًا للسداد. وأثار هذا القرار ردّ فعل كبيرًا في البورصات الأوروبية، وبدأ المسار الذي سينتهي بعد ست سنوات بقرار محرم وتأسيس إدارة الديون العمومية.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["خلع مراد الخامس وجلوس عبد الحميد الثاني على العرش", "cffb2271"], "d": ["عجز مراد الخامس، الذي اعتلى العرش بعد خلع عبد العزيز، عن القيام بمهامه بسبب حالته النفسية التي زعزعها موت عمه وحادثة حسن الجركسي؛ ولم يكن عقله سليمًا إلا في سبعة أيام من سلطنته التي دامت ثلاثة وتسعين يومًا. وخُلع بفتوى شيخ الإسلام وجيء بأخيه عبد الحميد الثاني مكانه. واعتلى السلطان الجديد العرش بعد أن وعد مدحت باشا بإعلان المشروطية؛ وكان عصر سيدوم ثلاثًا وثلاثين سنة يبدأ.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["مؤتمر الترسانة: فرض الدول الكبرى إصلاحات البلقان", "b5006a2c"], "d": ["طلب المؤتمر الذي عقدته الدول الكبرى في إسطنبول لحل أزمة البلقان تقسيم بلغاريا إلى ولايتين ذاتيتي الحكم وتطبيق إصلاحات في البوسنة والهرسك تحت رقابة دولية. وحاول الباب العالي مواجهة هذه المطالب بإصلاح دستوري، فأعلن القانون الأساسي بطلقات المدافع في يوم افتتاح المؤتمر. ورأى المندوبون ذلك مماطلة وتفرقوا في 20 كانون الثاني/يناير 1877؛ وبعد أربعة أشهر أعلنت روسيا الحرب.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["افتتاح أول مجلس مبعوثان في دولمه بهجه", "429bb279"], "d": ["اجتمع 115 نائبًا انتُخبوا وفق القانون الأساسي لأول مرة في 19 آذار/مارس 1877 في حفل أُقيم في قاعة المعايدة بقصر دولمه بهجه؛ وبذلك بدأ عهد المجلس النيابي في التاريخ العثماني. واستجوب النواب المسلمون وغير المسلمين الحكومة بشدة، وناقشوا إدارة الحرب ومسؤولية النظّار. وكانت هذه المعارضة الجريئة السبب الرئيسي الذي قصّر عمر المجلس.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["بدء الدفاع عن بلفنة: مقاومة غازي عثمان باشا", "0e04a878"], "d": ["سار عثمان باشا من ويدين إلى بلفنة لقطع الطريق على الجيش الروسي الذي عبر الدانوب في حرب 93 إلى إسطنبول، فحصّن البلدة بالطوابي والخنادق وبدأ دفاعًا أسطوريًا دام خمسة أشهر. وصُدّت بخسائر فادحة ثلاثة هجمات روسية رومانية كبرى متتالية، واضطر الجيش الذي أدار القيصر ألكسندر الثاني بنفسه إلى الحصار. وسُجلت بلفنة في التاريخ بوصفها أبرع نجاح دفاعي للجيش العثماني في القرن التاسع عشر.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["سقوط بلفنة: انهيار جبهة الدانوب", "185e7602"], "d": ["حاول عثمان باشا، الذي نفد زاده في الحصار الذي دام خمسة أشهر، الخروج عبر نهر فيد؛ وحين جُرح ووقع في الأسر استسلمت المدينة. وحيّا القادة الروس الباشا الذي أسروه وأعادوا إليه سيفه، ومُنح عثمان باشا لقب «غازي». وبسقوط بلفنة انفتح الطريق أمام الجيش الروسي؛ وسقطت صوفيا وفيليبه وأدرنة خلال شهرين، ووصلت طلائع الروس إلى يشيل كوي.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["احتلال القوات الروسية لصوفيا", "ef369d22"], "d": ["دخل الجيش الروسي، الذي اجتاز البلقان بعد سقوط بلفنة، صوفيا التي أصبحت دون دفاع. ولن تعود المدينة إلى الإدارة العثمانية، وستصبح فعليًا عاصمة إمارة بلغاريا ذات الحكم الذاتي في نهاية 1878، وفي عام 1879. وتخرج صوفيا على الخريطة من هذا التاريخ من الإدارة العثمانية المباشرة إلى الاحتلال الروسي المؤقت، ثم إلى الإدارة البلغارية ذاتية الحكم.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["هدنة أدرنة: سكوت السلاح في حرب 93", "1f899180"], "d": ["اضطر الباب العالي إلى طلب الهدنة بعد سقوط صوفيا وفيليبه وأدرنة تباعًا ووصول الجيش الروسي إلى سواحل مرمرة. وفرضت الهدنة الموقعة في أدرنة على الدولة العثمانية شروط الصلح الأولية، كالحكم الذاتي لبلغاريا واستقلال الجبل الأسود وصربيا ورومانيا وتعويض حرب ثقيل. وستتحول هذه الشروط بعد شهر إلى نص معاهدة في آيا ستيفانوس.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["تعطيل عبد الحميد الثاني مجلس المبعوثان إلى أجل غير مسمى", "e770b540"], "d": ["إثر النقد الشديد من النواب الذين حمّلوا الحكومة والقصر مسؤولية الحرب التي انتهت بكارثة، علّق عبد الحميد الثاني المجلس إلى أجل غير مسمى استنادًا إلى الصلاحية التي منحها له القانون الأساسي. وهكذا أُغلق أول برلمان عثماني عمل نحو أحد عشر شهرًا، وبدأ عصر الاستبداد الذي سيدوم ثلاثين سنة. ولم يتمكن المجلس من الاجتماع من جديد إلا بعد ثورة 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["معاهدة آيا ستيفانوس: مشروع بلغاريا الكبرى", "2c7cc611"], "d": ["كانت معاهدة آيا ستيفانوس، التي أنهت حرب 93، تؤسس بلغاريا ذاتية الحكم هائلة تمتد حتى بحر إيجه وتشمل مقدونيا، وتعترف باستقلال صربيا والجبل الأسود ورومانيا، وتترك قارص وأردهان وباطوم وبايزيد لروسيا، وتفرض فوق ذلك تعويض حرب يستحيل سداده. وأثار هذا النص، الذي ينزل بروسيا إلى البحر المتوسط، ردّ فعل عنيفًا من إنجلترا والنمسا. وأُعيد ترتيبه في مؤتمر برلين خلال أربعة أشهر دون أن يُطبَّق؛ ومع ذلك بقي الوثيقة التي أعلنت نهاية الروميللي العثمانية.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["التخلي عن قارص وأردهان وباطوم لروسيا — الألوية الثلاثة", "99bdfad2"], "d": ["بمعاهدة برلين تركت الدولة العثمانية قارص وأردهان وباطوم لروسيا مقابل جزء من تعويض الحرب؛ وبقي بايزيد ووادي ألاشكرد اللذان أُعطيا لروسيا في آيا ستيفانوس في يد العثمانيين. ورغم أن باطوم أُعطيت ميناء حرًّا، فلم تستطع الاحتفاظ بهذا الوضع إلا حتى عام 1886. وجعل الروس قارص ولاية تابعة للحكومة العامة لما وراء القوقاز مركزها تفليس؛ واضطر سكان الألوية الثلاثة، الذين بلغ عددهم 100.000، إلى الهجرة نحو أرضروم.", "e5049807"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["احتلال النمسا والمجر للبوسنة والهرسك ويني بازار", "e5f901df"], "d": ["استنادًا إلى الصلاحية التي منحتها معاهدة برلين، دخلت جيوش النمسا والمجر البوسنة؛ ورغم قبول الحكومة العثمانية بعدم المقاومة، حمل الأهالي المسلمون والأرثوذكس في سراييفو وموستار السلاح وأبدوا مقاومة ضارية ثلاثة أشهر. ولم يكتمل الاحتلال إلا في 20 تشرين الأول/أكتوبر 1878. وظلت السيادة القانونية للسلطان قائمة على الورق حتى عام 1908، غير أن البوسنة العثمانية التي دامت أربعة قرون خرجت فعليًا من اليد وبدأت موجة هجرة إسلامية كبيرة. الأماكن الأخرى التي خرجت من اليد في التاريخ نفسه: بانيالوكا.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["قرار محرم وتأسيس إدارة الديون العمومية", "02b7cc03"], "d": ["انتهت المفاوضات التي جرت بعد إفلاس 1875 مع ممثلي الدول الدائنة بقرار مؤرخ في 28 محرم 1299 (20 كانون الأول/ديسمبر 1881): خُفّض أصل الدين بأكثر من النصف، وفي المقابل نُقلت أكثر بنود الإيراد ريعًا، كرسوم الملح والتبغ والحرير والدمغة والأسماك، إلى إدارة الديون العمومية التي يديرها الدائنون مباشرة. وتحولت هذه الإدارة، التي استخدمت آلاف الموظفين، إلى تنظيم مالي مستقل داخل الدولة. ويُعدّ هذا التاريخ تاريخ انتهاء الاستقلال المالي العثماني فعليًا.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["سواكن — الميناء الوحيد الذي لم يسقط في يد المهدي", "5a37b198"], "d": ["في حين انتقلت جميع مناطق شرق السودان عدا سواكن، اعتبارًا من شباط/فبراير 1884، إلى سيطرة محمد أحمد المهدي، ظل الميناء قائمًا بالحماية العسكرية لقوة إنجليزية من ثلاث كتائب بقيادة الجنرال غراهام. وكانت هذه بداية مرحلة افترق فيها الوضع الفعلي عن الوضع القانوني: فرغم أن الساحل كان فعليًا تحت الرقابة العسكرية الإنجليزية، فإن ارتباطه الإداري سيُنتزع من مصر عام 1885 ويُربط مباشرة بولاية اليمن، أي بالباب العالي؛ واستمر هذا الترتيب حتى انتهى باحتلال فرنسا لزيلع عام 1888.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["مقتل مدحت باشا في سجن الطائف", "f4562261"], "d": ["كان مدحت باشا، مهندس القانون الأساسي ورمز المشروطية الأولى، قد وُجد مذنبًا في محكمة يلدز المتعلقة بوفاة عبد العزيز، وحُوّل حكم الإعدام إلى النفي، فأُرسل إلى الطائف. وبحسب ما ورد في موسوعة TDV، قُتل خنقًا في زنزانته ليلة 7-8 أيار/مايو 1884، وأُعلن أن السبب الرسمي مرض «شيربنجه». وصارت وفاته رمزًا لتصفية المعارضة الدستورية في عهد عبد الحميد الثاني.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["منح الألمان امتياز سكة حديد حيدر باشا — أنقرة", "5705b163"], "d": ["مُنح امتياز بناء خط حيدر باشا — أنقرة وتشغيله بإرادة سلطانية إلى المصرفي ألفريد فون كاولا ممثل دويتشه بنك، وأُسست شركة سكة حديد الأناضول. وكان هذا الامتياز نقطة تحول كسرت الاحتكار الإنجليزي الفرنسي في النقل والسياسة الخارجية العثمانية وأرست النفوذ الألماني. وبامتياز خط بغداد الذي سيُمنح للشركة نفسها بعد أحد عشر عامًا، سيولد حلم «برلين — بغداد»، وهو ما سيصبح أحد المحاور الرئيسية للتنافس بين القوى الكبرى قبيل الحرب العالمية الأولى.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["تأسيس جمعية الاتحاد العثماني في إسطنبول", "b7187939"], "d": ["أسس أربعة من طلاب الطبية العسكرية جمعية الاتحاد العثماني تنظيمًا سريًا ضد حكم الاستبداد؛ وتحولت هذه البنية سريعًا إلى جمعية الاتحاد والترقي التي ستجمع تحت سقفها جميع العناصر المعارضة في حركة تركيا الفتاة. والتحم التنظيم، القائم على أساس الخلايا، مع المنفيين في أوروبا والضباط في سالونيك. ومن هذه الخلية الطلابية الصغيرة خرج الملاك الذي سيعلن المشروطية الثانية عام 1908، وسيدير الدولة منفردًا بعد عام 1913.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["غارة البنك العثماني: عملية الطاشناق في غلطة", "08b3095f"], "d": ["اقتحمت مجموعة مسلحة من منظمة الطاشناقسوتيون الأرمنية مقرّ البنك العثماني العام في غلطة واحتجزت رهائن بهدف لفت انتباه أوروبا إلى المسألة الأرمنية، وهدّدت بنسف المبنى. وانتهت الأزمة بتدخل السفراء في مقابل إخراج المنفذين من البلاد على متن سفينة. وكانت الأحداث الدامية التي شهدتها إسطنبول في الأيام التالية للغارة حاسمة في تحول المسألة الأرمنية إلى أداة للتدخل الدولي.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["بدء الحرب العثمانية اليونانية 1897: جبهة تساليا", "33e490ab"], "d": ["إثر إنزال اليونان أسطولًا وجنودًا في كريت وهجمات العصابات على حدود الروميللي، أعلنت الدولة العثمانية الحرب. وتقدم الجيش العثماني، الذي دربته بعثة الإصلاح الألمانية، بسرعة في تساليا، فاستولى في شهر واحد على يني شهر وتشاتالجا ودومكه؛ وتفرق الجيش اليوناني. وبتدخل الدول الكبرى أُعيدت الأراضي المكتسبة، غير أن الحرب بقيت الانتصار العسكري الحاسم الوحيد في عهد عبد الحميد الثاني، ولم تمنع الفقدان الفعلي لكريت.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["منح الألمان امتياز خط قونية — بغداد", "fd8b6cbd"], "d": ["إثر زيارة القيصر فيلهلم الثاني لإسطنبول ودمشق عام 1898، مُنحت شركة سكة حديد الأناضول امتيازًا أوليًا لخط يمتد من قونية إلى بغداد والبصرة. وكان مشروع سكة حديد بغداد يعني بالنسبة إلى الدولة العثمانية تقوية الرقابة المركزية على الولايات العربية، وبالنسبة إلى ألمانيا الوصول إلى الخليج العربي. وكان هذا المشروع، الذي عارضته إنجلترا وروسيا بشدة، من أكثر ملفات التنافس الإمبريالي المؤدي إلى الحرب العالمية الأولى إثارة للجدل.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["بدء بناء سكة حديد الحجاز في دمشق", "62f58f68"], "d": ["بدأ بناء الخط الذي أمرت به إرادة عبد الحميد الثاني المؤرخة في 2 أيار/مايو 1900 بحفل رسمي أُقيم في دمشق في 1 أيلول/سبتمبر 1900. وقد اختصر المشروع، الذي نُفذ بتبرعات جُمعت بالكامل من العالم الإسلامي وبجهد المهندسين العسكريين العثمانيين، رحلة الحجاج بين دمشق والمدينة من أربعين يومًا إلى خمسة أيام. وكان عملًا مرموقًا يعزز السلطة المعنوية للخلافة واستثمارًا استراتيجيًا يقوّي الرقابة العسكرية على الحجاز.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["برنامج مورتسشتيغ: رقابة إصلاحية دولية في مقدونيا", "4c7464da"], "d": ["إثر ثورة إيليندن، التقى الإمبراطوران الروسي والنمساوي في مورتسشتيغ وأعدّا حزمة إصلاحات جديدة لمقدونيا. ونصّ البرنامج على أن يُوضع إلى جانب المفتش العام العثماني وكيلان مدنيان أجنبيان، وأن تُعاد هيكلة الدرك على يد ضباط أوروبيين، وأن تُغيَّر الحدود الإدارية وفق أساس القومية. ورغم أن الباب العالي قاوم بحجة المساس بحقوق السيادة، فقد اضطر إلى القبول أمام الضغط المشترك؛ وكان البرنامج من العوامل الأساسية التي سرّعت التنظيم الاتحادي بين الضباط الشباب.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["وفاة مراد الخامس", "396659a7"], "d": ["عاش مراد الخامس، الذي بقي على العرش نحو ثلاثة أشهر عام 1876 ثم خُلع، ثمانيًا وعشرين سنة سجينًا تحت حراسة مشددة بعد محاولات إعادته إلى العرش، وتوفي بالسكري. ودُفن إلى جانب أمه في ضريح الجديد خواتين في يني جامع. وسُجل في التاريخ بوصفه أقل السلاطين العثمانيين بقاءً على العرش.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["فقدان صنعاء لمصلحة الإمام يحيى", "e7f876cb"], "d": ["انتهت الثورة التي بدأها الإمام الزيدي يحيى حميد الدين عام 1904 بسقوط صنعاء بعد حصار في نيسان/أبريل 1905؛ وخرجت المدينة من الإدارة العثمانية، وظهر الجوع والوباء طوال الحصار. وقد جعلت جغرافيا اليمن الجبلية وطول خطوط التموين والشرعية المحلية للإمامة الزيدية السيادة العثمانية هناك هشة منذ تأسيسها. وستُسترد المدينة بعد خمسة أشهر بخسائر فادحة، غير أن المسألة اليمنية لن تُغلق حتى عام 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["اغتيال يلدز: قنبلة ضد عبد الحميد الثاني", "1ee2e1a6"], "d": ["نفذت منظمة الطاشناقسوتيون محاولة الاغتيال بتفجير عربة لاندو مفخخة بقنبلة موقوتة لدى خروج السلطان من صلاة الجمعة؛ وأنقذ عبد الحميد تأخره بضع دقائق بالحديث مع شيخ الإسلام. وقُتل في الانفجار ستة وعشرون شخصًا وجُرح أكثر من خمسين. وزاد الحدث من حدة هوس السلطان بالأمن وإدارة الاستبداد القائمة على جهاز الجواسيس؛ وكان موضوع قصيدة توفيق فكرت «بر لحظة تأخر».", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["استرداد صنعاء: إخماد ثورة الإمام يحيى", "dec3b8f9"], "d": ["انتهت الثورة التي بدأت عام 1904 بقيادة الإمام الزيدي يحيى بسقوط صنعاء في نيسان/أبريل 1905، وظهر في المدينة الجوع والوباء. واستردّت جيوش الدعم بقيادة علي رضا باشا وأحمد فيضي باشا المدينة بخسائر فادحة في عملية جرت بين 15 تموز/يوليو و1 أيلول/سبتمبر 1905 وأسندتها أيضًا القوات في تعز، وأُخمدت الثورة. وكلّفت العمليات في اليمن الجيش العثماني عشرات الآلاف من الخسائر وعبئًا ماليًا هائلًا؛ وكان الخوف من «النفي إلى اليمن» بين الضباط في الروميللي في مقدمة الشكاوى التي غذّت التنظيم الاتحادي.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["انعقاد أول مجلس مبعوثان في المشروطية الثانية", "e7fd2716"], "d": ["افتُتح المجلس، الذي تشكل بانتخابات على درجتين أُجريت بعد انقطاع ثلاثين سنة، بخطاب السلطان في 17 كانون الأول/ديسمبر 1908، وانتُخب أحمد رضا بك، زعيم حركة تركيا الفتاة، رئيسًا له. وكان المجلس، المؤلف من نواب أتراك وعرب وألبان وروم وأرمن ويهود، آخر محاولة كبرى لمثال العثمانية. غير أن استقلال بلغاريا وضم البوسنة وإعلان انضمام كريت إلى اليونان كانت قد ألقت بظلالها على هذا التفاؤل قبل أن يُفتتح المجلس.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["جيش الحركة وخلع عبد الحميد الثاني: جلوس محمد الخامس رشاد على العرش", "6a65a704"], "d": ["إثر حادثة 31 مارس، دخل جيش الحركة، الذي انطلق من سالونيك، إسطنبول من أربعة محاور في ليلة 22-23 نيسان/أبريل، واستسلم قصر يلدز في 24 نيسان/أبريل. وقرر مجلس الأمة العمومي في 27 نيسان/أبريل خلع عبد الحميد الثاني؛ وأُرسل السلطان إلى سالونيك، وأُجلس مكانه أخوه محمد الخامس رشاد. وبذلك انتهى الحكم الشخصي الذي دام ثلاثًا وثلاثين سنة، غير أن عهدًا جديدًا حلّ محله صار فيه السلطان رمزًا وكان الاتحاد والترقي يحكم بدعم من الجيش.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["ثورة ألبانيا: مقاومة مسلحة في كوسوفو وإشقودرة", "93ed30c6"], "d": ["حرّضت سياسة الضرائب المركزية للحكومة الاتحادية وحملة جمع السلاح وجدل الأبجدية اللاتينية العشائر الألبانية، التي كانت تُعدّ حتى ذلك اليوم من أكثر العناصر ولاءً للدولة. ورغم أن الجيش بقيادة محمود شوكت باشا أخمد الثورة بشدة، فقد تجدد الاضطراب عامي 1911 و1912. وأنهكت هذه الثورات الجيش العثماني عشية حرب البلقان، كما عجّلت ولادة الحركة القومية الألبانية.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["معاهدة أوشي: التخلي عن طرابلس الغرب وبنغازي لإيطاليا", "4ffa1fd2"], "d": ["لم يستطع الباب العالي، أمام استعداد دول البلقان للحرب، أن يقبل الاشتباك على جبهتين، فوقّع صلحًا سريًا مع إيطاليا في بلدة أوشي السويسرية وتخلى عن طرابلس الغرب وبنغازي. وهكذا فقدت الدولة العثمانية آخر أراضيها في إفريقيا؛ وفي المقابل وُعد بإعادة رودس والجزر الاثنتي عشرة التي احتلتها إيطاليا، غير أن هذا الوعد لم يتحقق قط. وحين وُقّعت المعاهدة كانت حرب البلقان قد بدأت منذ مدة.", "d54a35d9"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["احتلال اليونان لليمنوس", "9555af1d"], "d": ["احتل الأسطول اليوناني ليمنوس في حرب البلقان الأولى؛ وصار ميناء مودروس في الجزيرة قاعدة لحصار مضيق جناق قلعة. وتُركت الجزيرة لليونان في لوزان (24 تموز/يوليو 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["احتلال اليونان لثاسوس", "6c03c7f0"], "d": ["احتلت اليونان ثاسوس وساموثراكي في حرب البلقان الأولى.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["احتلال اليونان لساموثراكي", "911e82a3"], "d": ["احتلت اليونان ساموثراكي في حرب البلقان الأولى.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["احتلال اليونان لميديللي", "6b2b07ba"], "d": ["أنزل الأسطول اليوناني قواته في ميديللي؛ واستولى الجيش والأسطول اليونانيان على الجزيرة في نهاية حرب البلقان الأولى. وأكد مؤتمر لندن (أيار/مايو 1913) الوضع.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["إنزال يوناني في خيوس", "901c6539"], "d": ["أنزل اليونانيون قواتهم في خيوس التي قُصفت في 7 نيسان/أبريل 1912 في حرب البلقان الأولى؛ واستسلمت الحامية العثمانية في 3 كانون الثاني/يناير 1913. وتُركت الجزيرة لليونان بمعاهدة لوزان (24 تموز/يوليو 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["اغتيال الصدر الأعظم محمود شوكت باشا في إسطنبول", "68e60e63"], "d": ["قُتل محمود شوكت باشا، الذي عُيّن صدرًا أعظم بعد غارة الباب العالي، بإطلاق النار على عربته قرب جارشي قابي وهو في طريقه إلى نظارة الحربية. ونسب الاتحاد والترقي الاغتيال إلى المعارضة وبدأ موجة واسعة من الاعتقالات والإعدامات، وصُفّي حزب الحرية والائتلاف فعليًا. وبهذا الحدث تأسست بصورة قاطعة ديكتاتورية الحزب الواحد التي ارتكزت على ثلاثي أنور وطلعت وجمال.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["بدء حرب البلقان الثانية: خلاف الحلفاء على التقاسم", "48d088a2"], "d": ["اختلف حلفاء البلقان، الذين لم يستطيعوا تقاسم الأراضي التي أخذوها من الدولة العثمانية بمعاهدة لندن؛ وبدأت الحرب الثانية بهجوم بلغاريا على المواقع الصربية واليونانية. وحين دخلت رومانيا والجبل الأسود الجبهة ضد بلغاريا انهار الجيش البلغاري. وانتهزت الدولة العثمانية هذه الفرصة فتجاوزت خط مديه — إينز الذي رسمته معاهدة لندن، واستردت تراقيا الشرقية مع أدرنة.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["معاهدة إسطنبول: الصلح مع بلغاريا وتسجيل أدرنة", "c8c18b2d"], "d": ["اعتبرت المعاهدة الموقعة بين الدولة العثمانية وبلغاريا بعد حرب البلقان الثانية نهر مريج حدًّا، وسجّلت قانونيًا بقاء أدرنة وقرق كليسه وديموتيكا وتراقيا الشرقية في يد العثمانيين. وتُركت دده آغاج في بلغاريا (أما قوله فقد انتقلت إلى اليونان في تموز/يوليو 1913 بعد الاحتلال البلغاري في خريف 1912، وسُجّلت في اليونان بمعاهدة بوخارست في 10 آب/أغسطس 1913)، ونُظّم تبادل السكان المتبادل بين البلدين وحقوق المسلمين في بلغاريا. وهذا النص هو ضمان قطعة الأرض الوحيدة التي أمكن استردادها من كارثة البلقان. الأماكن الأخرى التي انضمت في التاريخ نفسه: كومولجينة.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["استرداد بوزجه آدا وإمروز — معاهدة أثينا", "ec084d09"], "d": ["من جزر شمال إيجه التي احتلتها اليونان في حرب البلقان، عُدّت بوزجه آدا وإمروز، اللتان تمسكان مدخل المضيق، في مفاوضات معاهدة أثينا لا غنى عنهما للدفاع عن جناق قلعة، فأُعيدتا إلى الدولة العثمانية. وبقيت الجزر الأخرى في اليونان. وكانت هاتان الجزيرتان آخر أراضي الإمبراطورية في إيجه، وتُركتا لتركيا في لوزان أيضًا.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["معاهدة أثينا: الصلح مع اليونان وتسليم سالونيك ويانينا", "8e94def7"], "d": ["اعترفت المعاهدة الموقعة بين الدولة العثمانية واليونان رسميًا بانتقال سالونيك ويانينا وجنوب مقدونيا، اللواتي فُقدن في حرب البلقان، إلى اليونان، وتخلّت عن الحقوق العثمانية على كريت. ونُظّمت بالتفصيل حقوق المسلمين الباقين في اليونان في الدين والملكية، ووضع الأوقاف، وتعيين المفتين. أما وضع جزر إيجه فتُرك دون حل، فظل مصدر توتر دائم بين الدولتين.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["توقيع معاهدة التحالف السرية العثمانية الألمانية في إسطنبول", "0472efb3"], "d": ["ما إن اندلعت الحرب في أوروبا حتى وُقّعت في قصر الصدر الأعظم سعيد حليم باشا معاهدة تحالف سرية بين الدولة العثمانية وألمانيا؛ ونصّ النص على أن تقف الدولة العثمانية إلى جانب ألمانيا في حال دخلت روسيا الحرب ضدها. وأُخفيت المعاهدة حتى عن مجلس الوزراء، ولم يعلم بها إلا أربعة أشخاص. وبعد ثلاثة أشهر ستُجرّ الدولة العثمانية فعليًا إلى الحرب بغارة البحر الأسود، وسيرتبط مصير الإمبراطورية بهذه الوثيقة.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["إلغاء الامتيازات الأجنبية من جانب واحد", "ec773d18"], "d": ["أعلنت الحكومة العثمانية، في وقت كانت فيه أوروبا مشغولة بالحرب، أنها ألغت من جانب واحد اعتبارًا من 1 تشرين الأول/أكتوبر 1914 الامتيازات الأجنبية التي تمنح الأجانب امتيازات قضائية ومالية وجمركية. وقوبل إنهاء نظام الامتيازات الذي دام أربعة قرون بحماسة استقلالية كبيرة داخل البلاد، وأُقيمت احتفالات في إسطنبول. واحتجت جميع الدول على القرار، بما فيها الحليفة ألمانيا؛ ولن تنتهي الامتيازات نهائيًا إلا في لوزان عام 1923.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["غارة البحر الأسود: قصف الأسطول العثماني للموانئ الروسية", "8ad4ef61"], "d": ["أبحرت السفينتان غوبن وبريسلاو (يافوز وميديللي)، اللتان هربتا من ألمانيا وانضمتا إلى الأسطول العثماني كأنهما «اشتُريتا»، إلى البحر الأسود بقيادة الأميرال سوشون، وقصفتا الموانئ الروسية وأغرقتا سفنًا. وأنهى هذا الأمر الذي أصدره أنور باشا سرًا عن مجلس الوزراء الحياد فعليًا. وفي غضون أسبوع أعلنت روسيا وإنجلترا وفرنسا الحرب، فدخلت الدولة العثمانية الحرب العالمية الأولى دخولًا لا رجعة فيه.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["استيلاء القوات الإنجليزية الهندية على الفاو — افتتاح الجبهة العراقية", "08663813"], "d": ["في صباح اليوم التالي لإعلان دول الوفاق الحرب على الدولة العثمانية، نزل لواء إنجليزي هندي كان ينتظر في البحرين في الفاو عند مصب شط العرب. وانسحبت الوحدة العثمانية الصغيرة في قلعة الفاو المتهدمة تحت نيران السفن الحربية، ووقعت محطة خط التلغراف الهندي في يد الإنجليز. وهكذا فُتحت الجبهة العراقية.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["إعلان الجهاد الأكبر: قراءة فتوى الجهاد في جامع الفاتح", "2a6174e8"], "d": ["قُرئت الفتاوى الخمس التي أصدرها شيخ الإسلام أورغوبلو خيري أفندي في جامع الفاتح باسم السلطان الخليفة، ودُعي جميع المسلمين إلى الجهاد ضد دول الوفاق. وكانت هذه الخطوة، التي علّقت عليها ألمانيا آمالًا كبيرة، تهدف إلى إثارة المسلمين في المستعمرات الإنجليزية والفرنسية. ولم تقع الانتفاضة العامة المنتظرة؛ بل على العكس، فإن ثورة أمير مكة الشريف حسين بدعم إنجليزي بعد سنتين أظهرت بمرارة حدود النفوذ السياسي للخلافة.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["استسلام القرنة للإنجليز", "621d36b0"], "d": ["استسلمت قوات والي البصرة صبحي بك، التي انسحبت إلى القرنة حيث يلتقي دجلة والفرات بعد سقوط البصرة، في صباح 9 كانون الأول/ديسمبر 1914 بعد اشتباكات 4-8 كانون الأول/ديسمبر.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["وضع مصر تحت الحماية الإنجليزية وإعلان السلطنة", "55d4e520"], "d": ["إثر دخول الدولة العثمانية الحرب، أعلنت إنجلترا أنها وضعت مصر، التي تحتلها فعليًا منذ عام 1882، تحت حمايتها رسميًا؛ وعُزل الخديوي عباس حلمي باشا الذي ظل وفيًا للدولة العثمانية، وجيء بحسين كامل مكانه بلقب «سلطان». وبذلك أُنهيت من جانب واحد السيادة العثمانية القانونية القائمة منذ عام 1517. ولم يعترف الباب العالي بالقرار، وبعد شهرين حاول استرداد مصر بحملة القناة.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["عملية صاري قاميش: كارثة على جبهة القوقاز", "5cbde7f0"], "d": ["ساق أنور باشا الجيش الثالث في الشتاء عبر جبال الله أكبر في مناورة لمحاصرة القوات الروسية، بهدف استرداد قارص وأردهان وباطوم اللواتي فُقدن عام 1878 وإثارة الأتراك في القوقاز. وبسبب قلة التجهيز الشتوي ونفاد التموين وعواصف الثلج التي بلغت ثلاثين درجة تحت الصفر، ذاب الجيش قبل أن يدخل المعركة؛ وهلك عشرات الآلاف من الجنود من البرد. وكانت العملية من أثقل كوارث الدولة العثمانية في الحرب، وتركت الجبهة الشرقية دون دفاع سنتين.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["حملة القناة الأولى: هجوم على السويس عبر صحراء سيناء", "02dd72f5"], "d": ["نظّم قائد الجيش الرابع جمال باشا هجومًا عبر صحراء سيناء بهدف تحرير مصر من الاحتلال الإنجليزي وإغلاق قناة السويس أمام الملاحة. ورغم أن القوات العثمانية بلغت الضفة الشرقية للقناة ونجح بعضها في العبور، فقد انسحبت أمام التفوق الإنجليزي وعدم وقوع الانتفاضة الشعبية المصرية المنتظرة. ولم تبلغ العملية هدفها، لكنها أحدثت تأثيرًا استراتيجيًا غير مباشر بإجبار إنجلترا على إبقاء قوة كبيرة في مصر.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["صدور قانون التهجير والتوطين (التهجير)", "2f2bc22c"], "d": ["إثر ثورة وان والتقدم الروسي، أصدرت الحكومة قانونًا مؤقتًا يجيز لقادة الجيش نقل السكان الذين عُدّ أنهم يخلّون بالأمن خلف الجبهة إلى مناطق أخرى، وصدّق السلطان عليه في 27 أيار/مايو 1915. ونتيجة التطبيق، سيق القسم الأكبر من السكان الأرمن في الولايات الشرقية والجنوبية من الأناضول نحو سوريا والموصل؛ ووقعت خسائر بشرية هائلة في أثناء النقل بسبب المرض والجوع والاعتداءات. وبقي القرار أثقل قضايا السنوات الأخيرة للدولة العثمانية وأكثرها إثارة للجدل حتى اليوم.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["استردت القوات العثمانية موش من الاحتلال الروسي", "fb1be113"], "d": ["بعد ستة أشهر من الاحتلال الروسي الأول لموش، دخلت الفرقة السادسة عشرة العثمانية البلدة في هجوم بتليس — موش المضاد.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["وقعت موش من جديد في يد الروس", "43ad8a03"], "d": ["إثر الهجوم الروسي المضاد أخلت المفرزة العثمانية موش؛ ودخلت البلدة من جديد في الاحتلال الروسي بين 22 و25 آب/أغسطس 1916 وبقيت فيه حتى ربيع 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["تحرير موش نهائيًا من الاحتلال الروسي", "f0e89703"], "d": ["استُردت موش، التي وقعت تحت الاحتلال الروسي في الحرب العالمية الأولى، نهائيًا بيد القوات العثمانية في 1 أيار/مايو 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["وفاة عبد الحميد الثاني في قصر بيلربيي", "c9662582"], "d": ["توفي عبد الحميد الثاني، الذي خُلع عن العرش عام 1909 وأُرسل أولًا إلى سالونيك ثم جيء به إلى إسطنبول عند فقدان المدينة في حرب البلقان، وكان محتجزًا في الإقامة الجبرية في قصر بيلربيي. وكان قد حاول خلال سلطنته التي دامت ثلاثًا وثلاثين سنة أن يكسب الوقت بإبعاد الدولة عن الحروب، لكنه عُرف أيضًا بإدارة الاستبداد. ودُفن في جنازة حاشدة في ضريح محمود الأول في ديوان يولو؛ وصادف موته سنة حرب كان النظام الذي أرساه قد صُفّي فيها منذ زمن.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["معاهدة بريست ليتوفسك: استرداد قارص وأردهان وباطوم", "da82636f"], "d": ["أغلقت المعاهدة الموقعة بين روسيا، التي انسحبت من الحرب بعد الثورة البلشفية، ودول التحالف الجبهة الشرقية، وأعادت إلى الدولة العثمانية قارص وأردهان وباطوم (الألوية الثلاثة) التي فقدتها بمعاهدة برلين عام 1878. وكان هذا المكسب الإقليمي الوحيد الذي أُحرز في التاريخ العثماني بعد أربعين سنة. غير أن المنطقة ستخرج من اليد من جديد بعد هدنة مودروس، وسيأتي الحل النهائي بمعاهدة قارص عام 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["دخلت القوات العثمانية أرتفين", "ca7d1778"], "d": ["اجتازت القوات العثمانية في 25 آذار/مارس حدود 1914، وسارت على الألوية الثلاثة التي أعادت بريست ليتوفسك حدودها إلى ما قبل 1878، ودخلت أرتفين في 28 آذار/مارس 1918. وكانت أرتفين قد تُركت لروسيا عام 1878 بوصفها جزءًا من سنجق باطوم؛ ولا تكتب مادة «أرتفين» في TDV عن العودة إلا «آذار/مارس 1918»، ويعطي اليوم ساري.", "224ac850"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["سقطت أردهان في يد الجيش التركي", "7fd9e3db"], "d": ["استولى الجيش العثماني في عملية الألوية الثلاثة على أردهان في 3 نيسان/أبريل 1918 بعد أرتفين؛ وكانت أردهان قد سقطت في حرب 93 عام 1877 وتُركت لروسيا عام 1878. وكانت قارص ستؤخذ بعد شهر، في 25 نيسان/أبريل.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["استرداد باطوم", "d37a1a0d"], "d": ["استردّ الجيش العثماني، المتقدم نحو الشرق إثر انسحاب روسيا من الحرب بمعاهدة بريست ليتوفسك، ميناء باطوم الذي فُقد عام 1878 بعد أربعين سنة. وكان هذا الميناء في الطرف الشرقي للبحر الأسود المنفذ البحري لنفط باكو. ولم يدم المكسب إلا سبعة أشهر؛ وستُخلى المنطقة بعد هدنة مودروس.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["الألوية الثلاثة: دخلت قارص الإدارة العثمانية", "02cbf0b3"], "d": ["تقرر في بريست ليتوفسك إعادة السناجق الثلاثة — قارص وأردهان وباطوم — التي فُقدت بمعاهدة برلين عام 1878؛ ودخل الجيش العثماني أردهان في 3 نيسان/أبريل، وباطوم في 14 نيسان/أبريل، وقارص في 25 نيسان/أبريل 1918، وأُقيمت الإدارة فعليًا. وعُدّت هذه الأراضي، المعروفة باسم «الألوية الثلاثة»، تعويضًا عن الخسارة المستمرة منذ حرب 93. وستخرج من اليد من جديد بعد الهدنة، ولن ترتبط بتركيا نهائيًا إلا بمعاهدة قارص عام 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["الاستيلاء على إغدير — التقدم في وادي آراس", "87ebf4d3"], "d": ["هزمت القوات التركية، في إطار التقدم الذي بدأ في شباط/فبراير 1918، الوحدات الأرمنية في سردار آباد شمال آراس، واستولت على إغدير في 20 أيار/مايو 1918. ولم تكن إغدير ضمن الألوية الثلاثة، بل كانت قضاء سورملي في ولاية إريفان؛ وأُقيمت فيها بعد نحو 180 سنة أول إدارة عثمانية في المنطقة.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["وفاة محمد الخامس رشاد وجلوس محمد السادس وحيد الدين على العرش", "d302ba07"], "d": ["توفي محمد الخامس رشاد، الذي مرت سلطنته التي دامت تسع سنوات بحروب طرابلس الغرب والبلقان والحرب العالمية، في أحرج مراحل الحرب، وجلس مكانه أخوه وحيد الدين باسم محمد السادس. وحاول السلطان الجديد أن يتحرر من وصاية الكادر الاتحادي؛ وحين وُقّعت الهدنة بعد أربعة أشهر اضطر إلى إدارة تصفية الإمبراطورية. وكان السلطان السادس والثلاثين والأخير للأسرة العثمانية.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["وصول أسطول الوفاق إلى أمام إسطنبول والاحتلال الفعلي للمدينة", "d10cb14d"], "d": ["بعد هدنة مودروس، رسا أسطول الحلفاء المؤلف من أكثر من ستين قطعة من السفن الإنجليزية والفرنسية والإيطالية واليونانية أمام دولمه بهجه، فوقعت إسطنبول تحت الاحتلال الفعلي. وللمرة الأولى بعد أربعمائة وخمس وستين سنة، صارت العاصمة تحت رقابة جنود أجانب. وكانت عبارة «يذهبون كما جاؤوا» التي يُروى أن مصطفى كمال باشا قالها في اليوم نفسه لما نزل إلى حيدر باشا ورأى المنظر، ستصبح إحدى الجمل الرمزية لحرب الاستقلال.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["الانسحاب في منطقة آراس: إخلاء إغدير", "57572ab4"], "d": ["وفقًا لحكم الانسحاب إلى ما وراء حدود 1914 الوارد في هدنة مودروس، أمر يعقوب شوقي باشا بأمر مؤرخ في 21 تشرين الثاني/نوفمبر بسحب الوحدات الواقعة خارج حدود بريست ليتوفسك حتى 4 كانون الأول/ديسمبر؛ وأُخلي إغدير وما حوله إخلاءً تامًا في هذا التاريخ. ثم هدم الأرمن حكومة آراس التركية في أواخر كانون الأول/ديسمبر 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["استقرار الإنجليز في أرتفين", "e2cb3153"], "d": ["لأن هدنة مودروس في 30 تشرين الأول/أكتوبر 1918 اشترطت انسحاب الجيش العثماني إلى ما وراء حدود 1914، أُخليت أرتفين واحتلها الإنجليز في 17 كانون الأول/ديسمبر 1918. وبحسب مادة «أرتفين» في TDV استمر الاحتلال الإنجليزي حتى نيسان/أبريل 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["الإدارة البريطانية في باطوم بعد مودروس", "9dd768fc"], "d": ["اضطرت الدولة العثمانية إلى الانسحاب من باطوم بموجب هدنة مودروس في 30 تشرين الأول/أكتوبر 1918؛ وأمسكت القوات البريطانية بالمدينة في 24 كانون الأول/ديسمبر 1918. وبقيت باطوم، التي جُعلت في نيسان/أبريل 1918 مركز سنجق مستقل، من هذا التاريخ حتى تموز/يوليو 1920 تحت الرقابة الإنجليزية.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["انتقال أردهان إلى السيادة الجورجية", "97cf47f6"], "d": ["احتلت القوات الجورجية في 20 نيسان/أبريل 1919 أردهان التي أُخليت بعد مودروس، في الأيام التي حلّ فيها الإنجليز حكومة القوقاز الجنوبية الغربية. وستستمر السيادة الجورجية حتى 23 شباط/فبراير 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["بريستون يسلّم إدارة قارص إلى الوالي الأرمني", "efa81cb0"], "d": ["ألغى القائد الإنجليزي بريستون، الذي حلّ حكومة القوقاز الجنوبية الغربية في 12-13 نيسان/أبريل 1919، الحكومة الشورية المؤقتة في 30 نيسان/أبريل 1919، وسلّم إدارة المدينة إلى الأرمني كارغانوف الذي عُيّن واليًا على قارص؛ وبدأ في قارص عهد الإدارة الأرمنية، واستمر حتى انتصار كاظم قره بكر في 30 تشرين الأول/أكتوبر 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["مؤتمر أرضروم: قرار المقاومة الوطنية في الولايات الشرقية", "41ef0457"], "d": ["افتُتح المؤتمر الذي دعت إليه جمعية الدفاع عن حقوق الأناضول الشرقي، بعد أن أُجّل بضغط إنجليزي، بستة وخمسين مندوبًا، وانتُخب رئيسًا له مصطفى كمال باشا الذي استقال من الجيش. وأعلن المؤتمر أن الوطن كلٌّ لا يتجزأ داخل الحدود الوطنية، وأن الانتداب والحماية غير مقبولين، وأن الأمة ستأخذ مصيرها بيدها إذا تفككت الحكومة. وستشكل هذه القرارات بعد ستة أشهر نواة نص الميثاق الملي.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["مؤتمر سيواس: توحيد المقاومة الوطنية تحت سقف واحد", "0e9ad36b"], "d": ["وحّد المؤتمر الذي بدأ أعماله في سلطانية سيواس في 4 أيلول/سبتمبر 1919 جمعيات الدفاع عن الحقوق في أرجاء البلاد تحت اسم جمعية الدفاع عن حقوق الأناضول والروميللي، وانتُخبت هيئة تمثيلية. ورُفض عرض الانتداب الأمريكي بعد نقاشات طويلة. وبالبيان الذي صدر في 11 أيلول/سبتمبر صار النضال الوطني حركة سياسية مشروعة ذات مركز واحد، وبدأ صراع قوة صريح مع حكومة إسطنبول.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["بروتوكول أماسيا: لقاء حكومة إسطنبول مع الهيئة التمثيلية", "40e6a6ab"], "d": ["بعد سقوط داماد فريد وتشكيل حكومة علي رضا باشا، أُرسل ناظر البحرية صالح باشا إلى أماسيا للقاء الهيئة التمثيلية. وبالبروتوكولات التي تم التوصل إليها، اعترفت حكومة إسطنبول فعليًا بوجود الحركة الأناضولية؛ وقُبل انعقاد مجلس المبعوثان وإجراء الانتخابات بحرية والحفاظ على الحدود الوطنية. وكان هذا أول مكسب سياسي رسمي حققته حرب الاستقلال أمام إسطنبول.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["إقرار الميثاق الملي في آخر مجلس عثماني", "6322865e"], "d": ["اشترط نص العهد الملي الذي وقّعه 121 مبعوثًا في آخر مجلس مبعوثان عثماني الوحدة غير القابلة للتجزئة للأراضي التي تقع داخل خط مودروس ويعيش فيها أغلبية مسلمة تركية، والاستفتاء في الولايات العربية وتراقيا الغربية، وإلغاء الامتيازات، والاستقلال السياسي والمالي التام. وأُقر النص بالإجماع في 17 شباط/فبراير 1920 وأُعلن للعالم. وكان هذا البيان البرنامج السياسي لحرب الاستقلال بقدر ما كان خريطة الحدود التي ستُدافع عنها في لوزان؛ وكان السبب المباشر لاحتلال دول الوفاق إسطنبول رسميًا في 16 آذار/مارس.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["بقاء أرتفين في جورجيا عند انسحاب الإنجليز", "6d086b06"], "d": ["بحسب مادة «أرتفين» في TDV استمر الاحتلال الإنجليزي حتى نيسان/أبريل 1920؛ وتركوا المدينة لجورجيا عند انسحابهم. وبقيت أرتفين في يد جورجيا حتى إنذار المجلس الوطني الكبير في 23 شباط/فبراير 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["تسليم باطوم إلى الإدارة الجورجية", "6523d095"], "d": ["جرى تسليم الإنجليز باطوم رسميًا إلى الجورجيين في 7 تموز/يوليو 1920 (ولا تذكر مادة «باطوم» في TDV سوى «تموز/يوليو 1920»). واحتجت حكومة أنقرة في 25 تموز/يوليو على التسليم بوصفه «احتلالًا».", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["معاهدة غومري: أول معاهدة دولية لحكومة المجلس الوطني الكبير", "9232c690"], "d": ["إثر استرداد جيش الجبهة الشرقية بقيادة كاظم قره بكر صاري قاميش وقارص، طلبت أرمينيا السلم، وبالمعاهدة الموقعة في غومري قبلت أنها لا تعترف بسيفر وتخلت عن مطالبها الإقليمية في الشرق. وكانت هذه المعاهدة الأولى التي وقّعتها حكومة أنقرة أولى الوثائق الدولية التي رفضت سيفر فعليًا، وفتحت أمام المجلس الوطني الكبير طريق الاعتراف القانوني. وهكذا ضُمن الحد الشرقي وصار ممكنًا نقل القوات إلى الجبهة الغربية.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["معركة إينونو الأولى: أول انتصار للجيش النظامي", "4add3719"], "d": ["أوقف الجيش النظامي المؤسَّس حديثًا القوات اليونانية المتقدمة من اتجاه بورصة في مواقع إينونو وأجبرها على الانسحاب. ورغم أن هذا النجاح كان محدود النطاق عسكريًا، فإن نتائجه السياسية كانت كبيرة جدًا: دُعيت حكومة أنقرة إلى مؤتمر لندن، وفُتح الطريق إلى معاهدة موسكو مع روسيا السوفييتية، وصدر قانون التشكيلات الأساسية. وترسخت بهذا الانتصار ثقة الرأي العام الداخلي في الجيش النظامي.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["معركة إينونو الثانية: كسر الهجوم اليوناني للمرة الثانية", "a974521c"], "d": ["بدأ الجيش اليوناني، الذي لم يصل إلى نتيجة في مؤتمر لندن، هجومًا جديدًا من اتجاهي بورصة وأوشاق، غير أنه أُوقف مرة أخرى على مرتفعات إينونو واضطر إلى الانسحاب. وكُتبت برقية مصطفى كمال باشا إلى عصمت باشا «لم تهزموا هناك العدو وحده، بل هزمتم أيضًا طالع الأمة المشؤوم» عقب هذا الانتصار. ورفعت المعركة المكانة الدولية لحرب الاستقلال وعجّلت عملية انسحاب إيطاليا من الأناضول.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["اتفاقية أنقرة: الصلح مع فرنسا وإغلاق الجبهة الجنوبية", "35fc32db"], "d": ["انتهت الحرب على الجبهة الجنوبية بالاتفاقية الموقعة في أنقرة مع فرنسا بعد انتصار صقاريا؛ وأخلت القوات الفرنسية تشوكوروفا والجنوب الشرقي، بما فيها أضنة وعنتاب ومرعش وأورفة، وانسحبت إلى الحدود السورية. وهكذا اعترفت إحدى دول الوفاق فعليًا بحكومة أنقرة، وانفتح أول صدع في جبهة سيفر. وأدت الأسلحة التي استلمت من المناطق المخلاة والوحدات التي تحررت دورًا حاسمًا في الإعداد للهجوم الكبير.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["هدنة مودانيا: تسليم إسطنبول والمضائق دون حرب", "ac0d9baf"], "d": ["إثر الهجوم الكبير ومواجهة الجيش التركي القوات الإنجليزية في جناق قلعة وإزميت، انتهى المؤتمر الذي اجتمع في مودانيا بعد مساومة عسيرة دامت أحد عشر يومًا بهدنة. وقُبل أن تُخلي اليونان تراقيا الشرقية حتى مريج خلال خمسة عشر يومًا وتسلّمها إلى الإدارة التركية، وأن تُسلَّم إسطنبول والمضائق أيضًا بمعاهدة الصلح. وهكذا انتهت المرحلة المسلحة من حرب الاستقلال بانتصار دبلوماسي أُحرز دون إطلاق رصاصة واحدة، وفُتح باب لوزان.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["مغادرة محمد السادس وحيد الدين إسطنبول وانتخاب عبد المجيد أفندي خليفة", "8ab0e847"], "d": ["غادر آخر السلاطين محمد السادس وحيد الدين، الذي صار وضعه موضع جدل بعد إلغاء السلطنة، إسطنبول صباح الجمعة 17 تشرين الثاني/نوفمبر 1922 على متن الطراد البريطاني ملايا متجهًا إلى مالطة. وبعد يومين، في 19 تشرين الثاني/نوفمبر، انتخب المجلس الوطني الكبير عبد المجيد أفندي خليفة دون سلطة سياسية. وبذلك انتهى فعليًا الحكم الأسري العثماني الذي دام ستمائة وثلاثًا وعشرين سنة؛ أما الخلافة فستستمر رمزية خمسة عشر شهرًا أخرى. واستقر وحيد الدين، الذي انتقل إلى مالطة ثم إيطاليا، في فيلا نوبل في سان ريمو؛ ولم يصل إلى نتيجة في طلباته للقبول في بلد مسلم، وتوفي هناك في 16 أيار/مايو 1926 مكررًا أنه لم يتنازل قط عن حقوقه في السلطنة والخلافة.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["وفاة آخر السلاطين محمد السادس وحيد الدين في سان ريمو", "7149ed0e"], "d": ["توفي محمد وحيد الدين، آخر السلاطين العثمانيين الذي استقر في مدينة سان ريمو الإيطالية بعد مغادرته إسطنبول، في 16 أيار/مايو 1926 قبل أن يعلم بانعقاد مؤتمر الخلافة (13 أيار/مايو 1926) الذي أعلن فيه أنه لم يتنازل قط عن حقوقه في السلطنة والخلافة. وكان في ضيق مالي شديد؛ وكان مدينًا لتجار سان ريمو بمبلغ 60.000 ليرة إيطالية، وحين علم الدائنون بوفاته أوقعوا الحجز على أثاث بيته.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["فتح قونور ألب منطقة بولو — مودرنو وقونورابا وبولو", "e245cd27"], "d": ["توجه قونور ألب، أحد قادة أورخان غازي، إلى المنطقة الجبلية شرق سقاريا، وربط مودرنو وقونورابا ومنطقة بولو بالإدارة العثمانية؛ وسُميت البلدة في سهل دوزجه باسمه. ولا يُعرف تاريخ الفتح الدقيق؛ والرواية قائمة على ما رواه عاشق باشازاده. وكانت المنطقة آنذاك ثغرًا تتداوله الأيدي بين الجنداريين وبيزنطة؛ وقرّب الفتح العثمانيين للمرة الأولى من الساحل الغربي للبحر الأسود. وبعد معركة أنقرة ستنتقل المنطقة من جديد إلى الجنداريين، لكنها ستُسترد نهائيًا في عهد الفاتح.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["الاستيلاء على بلدات بيزنطية جنوب مرمرة — ميخاليج وكرمستي وغوليازي", "9c61b8d4"], "d": ["بعد الاستيلاء على إزنيق وإزميت، دخلت البلدات التي بقيت في يد بيزنطة غرب سهل بورصة في الإدارة العثمانية واحدة بعد أخرى. وأتمت غوليازي حول بحيرة أولوآباد وكرمستي على نهر سوسورلوق وميخاليج الممر الذي يربط الساحل الجنوبي لمرمرة بأراضي قراسي. واستسلمت هذه البلدات دون حصار طويل بقطع ما حولها؛ وانحصر الوجود البيزنطي في المنطقة بذلك في خليج جمليك.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["انتقال كورنثة (كورنث) إلى إمارة المورة", "392495eb"], "d": ["كانت كورنثة، منذ عام 1358، إقطاعًا تابعًا لإمارة آخايا التي كانت في يد أسرة أتشياجولي الفلورنسية، وقد صارت عام 1395 في يد ثيودور، حاكم المورة البيزنطي. وبقيت المدينة بعد ذلك في إدارة الإمارة حتى الفتح العثماني.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["ضم إمارة الحاجي أمير — أردو وأونيه", "c064f07f"], "d": ["كانت الإمارة التركمانية التي أسسها بيرم بك حول أردو ووسّعها ابنه حاجي أمير في عقد 1350 دولة ساحلية صغيرة لكنها استراتيجية، مركزها في إسكي بازار اليوم: وكانت منطقة السيادة المستقلة الوحيدة بين سامسون وطرابزون. وكان الأمير سليمان قد أعلن ولاءه عام 1398 في حملة جانيك لبايزيد يلدرم، وعادت الإمارة بعد معركة أنقرة حرة. وفي عهد مراد الثاني، في السنوات نفسها التي صُفيت فيها إمارة بني تاج الدين، ضُمت أراضي الإمارة إلى الإدارة العثمانية المباشرة، واتحد ساحل البحر الأسود في يد واحدة من سامسون إلى غيرسون.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["فتح كورنثة (كورنث)", "87a2bc59"], "d": ["حوصرت قلعة أكروكورنثة ثلاثة أشهر في حملة الفاتح على المورة، وسُلّمت في النهاية صلحًا. وبذلك انتقل إلى العثمانيين برزخ كورنثة الذي يُعدّ باب المورة.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["ربط الجبل الأسود بالإدارة العثمانية — تسيتينيي", "7fdb7cc8"], "d": ["حين ترك آل تسرنويفيتش الحاكمون في زيتا سيادتهم عام 1496، ضُمت منطقة الجبل الأسود الجبلية، التي تقع في الفناء الخلفي لإشقودرة، إلى الإدارة العثمانية المباشرة، ونُظمت أولًا سنجقًا منفصلًا ثم جزءًا من سنجق إشقودرة. وتُرك دير تسيتينيي في مكانه بوصفه المركز الديني للمنطقة. ولم تعمل الإدارة هنا قط بالإحكام الذي كانت تعمل به في السهول بسبب قسوة الجغرافيا؛ وسيكون حكم الفلاديكا المنبثق من الدير نفسه بعد قرنين نواة الاستقلال الفعلي.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["قبول قلعة بايزيد السيادة العثمانية في حملة العراقين", "f29e2e17"], "d": ["حين جاء الصدر الأعظم إبراهيم باشا إلى جوار بينغول في حملة العراقين، قبلت قلاع وان وتوبراك قلعه وعوني وبايزيد، مع كثير من العشائر الكردية في المنطقة، الدخول في السيادة العثمانية. وكانت بايزيد قد انضمت إلى الدولة العثمانية في حملة يافوز عام 1514، لكن الصفويين استردوا المنطقة حين عاد الجيش.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["عودة تبريز إلى الصفويين — العودة من العراقين", "80b8b761"], "d": ["دخل الجيش تبريز في حملة العراقين، لكن لم تُترك في المدينة حامية دائمة لأن الهدف الأساسي كان بغداد. وحين عاد الجيش، الذي أمضى الشتاء في بغداد، غربًا، دخل الشاه طهماسب أذربيجان التي أُخليت واستردّ تبريز. وكان هذا النمط المتكرر للحروب العثمانية الصفوية: استُولي على تبريز خمس مرات ولم يمكن الاحتفاظ بها في أي منها؛ ولن تحصل المدينة على حامية عثمانية طويلة الأمد إلا عام 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["وقوع وان وأرجيش في يد طهماسب (انتهى الموقف العثماني في 1534-35)", "cb93d561"], "d": ["في المنطقة التي أخضعت وان للسيادة العثمانية عام 1534، صمد أولاما باشا في قلعة وان أمام الحصار الصفوي؛ ووقعت القلعة في يد الصفويين، وكانت القوات الصفوية التي حاصرت أرجيش قد انسحبت بمساعدة عثمانية. وحين بلغ القانوني أخلاط (23 أيلول/سبتمبر 1535) كانت وان قد صارت في يد طهماسب. وبقيت وان صفوية حتى عام 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["انتقال سنجق بايزيد إلى السيادة الصفوية (كانت وان وأرجيش صفويتين أصلًا عام 1535)", "806a2cf1"], "d": ["عاد سنجق بايزيد، في وسط الحد العثماني الصفوي، إلى يد إيران (يذكر Kaya 2017 ذلك «مع وان وأرجيش»؛ غير أن وان وأرجيش كانتا قد عادتا إلى الصفويين في 22 أيلول/سبتمبر 1535 بحسب Karataş 2025 وTDV — انظر المادة السابقة)؛ وخربت بعض أماكن السنجق في هذا التبادل. وتداولت الدولتان السنجق مرارًا حتى الربع الأخير من القرن السادس عشر.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["عودة سنجق بايزيد إلى العثمانيين في أثناء حملة نخجوان", "cf0171fa"], "d": ["في أثناء حملة القانوني الثالثة على إيران (نخجوان)، أُخضع سنجق بايزيد للإدارة العثمانية من جديد. وفي حملة 1554 كانت بايزيد قاعدة مهمة للجيش؛ ودخل السنجق نهائيًا في السيادة العثمانية عام 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["فقدان ريفان لمصلحة الشاه عباس", "34413cf2"], "d": ["حين تُركت الجبهة الشرقية دون دفاع في السنوات التي شلّت فيها ثورات الجلالية الأناضول، انتقل الشاه عباس، الذي أعاد تنظيم جيشه على الطراز الأوروبي، إلى الهجوم. وسلّمت قلعة ريفان، التي بناها فرهاد باشا عام 1583، بعد حصار دام سبعة أشهر. وانكسرت الحلقة الأولى من خط القوقاز الذي كُسب بمعاهدة فرهاد باشا، وكان جنوب القوقاز كله سيخرج من اليد خلال السنوات الثلاث التالية.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["فقدان تفليس وكنجة", "3fb51753"], "d": ["بعد سقوط ريفان تقدم الجيش الصفوي على طول وادي الكر؛ وخرجت من اليد واحدة بعد أخرى كنجة مركز قره باغ وتفليس عاصمة جورجيا. وكانت الدولة العثمانية في الوقت نفسه تخوض على جبهة النمسا حربًا طويلة دامت ثلاث عشرة سنة وتنشغل بالجلالية في الأناضول؛ ولم تكن هناك قوة تُرسل نحو الشرق. وهكذا انتهى فعليًا نظام إيالات القوقاز الواسع الذي أُسس بمعاهدة فرهاد باشا عام 1590.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["فقدان شروان — شماخي وباكو ودربند", "81beab11"], "d": ["كانت إيالة شروان على ساحل قزوين قد كُسبت بحملات أوزدمير أوغلو عثمان باشا في 1578-1585، وأدرّت على المالية العثمانية إيرادًا كبيرًا بوصفها المصدر الرئيسي لتجارة الحرير. وصفّت عملية الشاه عباس المتجهة شمالًا هذه الإيالة بالاستيلاء على شماخي وباكو ودربند تباعًا. ولم تكن الخسارة أرضًا فقط: فقد خرج طريق الحرير الإيراني المتدفق إلى أوروبا عبر الدولة العثمانية من الرقابة، وبدأت الدولة الصفوية تسوّق الحرير عبر المحيط الهندي.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["فقدان تعز", "65f20d53"], "d": ["ترك العثمانيون في 1038 (1629) تعز مع السيادة في اليمن إلى الإدارة القاسمية في صنعاء — وهي الخطوة الكبرى الأولى في المسار الذي استردّ فيه الأئمة الزيديون اليمن الداخلي.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["فقدان اليمن — سيادة الأئمة القاسميين", "49e83e3c"], "d": ["كانت اليمن إيالة عثمانية منذ عام 1538؛ غير أن مقاومة الأئمة الزيديين لم تنقطع قط. وامتدت الثورة التي بدأها الإمام القاسم في عهد ابنه المؤيد محمد إلى البلاد كلها، وحوصرت الحاميات العثمانية تباعًا. ولم يمكن إرسال تعزيزات في السنوات التي كان فيها مراد الرابع مركزًا على بغداد وريفان؛ وكانت تعز قد خرجت من اليد عام 1629، وأُخليت المخا في المرحلة الأخيرة من الانهيار نفسه في 22 تشرين الأول/أكتوبر 1635. وفي 1635 أخلت آخر القوات في صنعاء وزبيد اليمن أيضًا. وهكذا بقي الساحل الشرقي للبحر الأحمر مئتين وسبعًا وثلاثين سنة خارج الإمبراطورية، ولم يُسترد إلا عام 1872.", "7d62c00f"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["إخلاء المخا", "c6b3061a"], "d": ["أخلى مصطفى بك المخا في 10 جمادى الأولى 1045 (22 تشرين الأول/أكتوبر 1635) بالقوة والأسلحة الباقية؛ ثم عيّن الحسن بن القاسم، ابن الإمام القاسم، رجاله في زبيد والمخا وأقام الرقابة القاسمية على ساحل تهامة أيضًا.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["فقدان الأحساء لإمارة بني خالد", "a9b6131a"], "d": ["كانت الأحساء إيالة أُسست عام 1550 لإغلاق الساحل الغربي للخليج في وجه البرتغال؛ غير أنها كانت بعيدة جدًا عن إسطنبول عند نهاية طريق صحراوي واحد. وفي السنوات التي استنزف فيها حصار كريت الموارد، أخرجت قبيلة بني خالد في المنطقة الحامية العثمانية بقيادة براك بن غرير وأسست إمارتها. وبقي الساحل الغربي للخليج قرنًا ونصفًا في إمارات قبلية؛ وسينتقل إلى السعوديين عام 1795 وإلى العثمانيين من جديد عام 1871.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["فقدان بريفزة وفونيتسا لمصلحة البندقية — انفتاح ساحل إبيروس", "1201204c"], "d": ["استولت البندقية، التي انضمت إلى الحلف المقدس، قبل أن تبدأ حملة المورة، على قلعتين تمسكان مدخل خليج أمبراكيا: بريفزة وفونيتسا على الضفة المقابلة. وكانت آيا مافرا (لفكادا) قد سقطت في الصيف نفسه. وأتاحت هذه المواقع الثلاثة إدخال الأسطول بأمان من البحر الأيوني إلى داخل اليونان، وصارت قاعدة لعمليات المورة التي ستبدأ في العام التالي. وتُركت بريفزة وفونيتسا في باساروفجة للبندقية أيضًا؛ ولن تعودا إلى الإدارة العثمانية إلا عام 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["فقدان سولنوك — تفكك خط تيسا", "51c2c8ef"], "d": ["بعد سقوط أويفار في آب/أغسطس، اتجه الجيش الهابسبورغي جنوبًا وأخذ سولنوك، رأس الجسر على نهر تيسا. وكانت المدينة المعبر الآمن الوحيد بين بودين وترانسلفانيا؛ وكان فقدانها يعني انقطاع القلاع العثمانية في النصف الشرقي للمجر بعضها عن بعض. وكان لقطع طريق التموين حسم في حصار بودين في العام التالي.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["فقدان مودون للبندقية", "114c9cc0"], "d": ["كانت مودون في الطرف الجنوبي الغربي لشبه جزيرة المورة الميناء الذي فقدته البندقية قبل ثلاثة قرون ووصفته بأنه «إحدى عيني الدولة». وسُلّمت القلعة، التي حوصرت بعد سقوط كورون، بعد قصفها برًا وبحرًا في وقت واحد. وهكذا استولت حملة موروزيني في المورة على الساحل الغربي كله لشبه الجزيرة وانفتح الطريق إلى الداخل.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["فقدان بيتش", "99d54cf4"], "d": ["بعد سقوط بودين في أيلول/سبتمبر، نزلت القوات الهابسبورغية جنوبًا غرب الدانوب وأخذت بيتش التي كانت عثمانية منذ عهد القانوني. وكانت المدينة، المعروفة بجامع غازي قاسم باشا، من أكثر مراكز سناجق إيالة بودين تطورًا. وكان فقدانها يعني انفتاح الطريق المنحدر إلى سهل موهاج؛ وسيقع في العام التالي هنا بالذات انهيار موهاج الثاني.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["فقدان سغدين", "9fbee1b2"], "d": ["كانت سغدين، عند التقاء نهري تيسا ومورش، الباب الجنوبي للسهل المجري وتمسك الطريق إلى إيالة تيميشوارا. وسلّمت القلعة، التي حوصرت بعد سقوط بودين وبيتش في الخريف نفسه، في وقت قصير. وكان فقدان ثلاث قلاع في فصل واحد علامة على أن البنية الإدارية العثمانية في المجر المؤسَّسة منذ 1541 بدأت تنهار.", "63dea9ab"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["فقدان بالي بادرة (باتراس) — الباب الشمالي للمورة", "b9cff63c"], "d": ["كانت بالي بادرة عند مدخل خليج كورنثة الميناء الذي يتحكم في الانتقال بين المورة والروميللي. وبعد أن أخذ الجيش البندقي المدينة، سقطت القلاع على ضفتي الخليج واحدة تلو الأخرى، وانعزلت شبه الجزيرة من البر تمامًا. وفي نهاية هذه العملية انتقلت المورة بأكملها إلى البندقية؛ وستُدار المنطقة حتى 1715 باسم «Regno di Morea».", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["تخلّي العثمانيين عن كورنثة (كورنث) للبندقية", "9a25b6b9"], "d": ["بعد سقوط باليا بادرا، تُركت كورنثة صلحًا للبنادقة وغادر أهلها المسلمون المدينة. وفي أغسطس 1687 كان جيش موروزيني يتجمع في كورنثة استعدادًا لحملة أثينا.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["فقدان إغري", "983391aa"], "d": ["كانت إغري قد أُخذت عام 1596 بحملة شارك فيها محمد الثالث بنفسه وصارت مركز إيالة تحمل اسمها. وصمدت هذه القلعة العثمانية الكبرى الأخيرة في شمال المجر سنة وهي محاصرة تمامًا بعد انهيار موهاج الثاني، وسلّمت بسبب الجوع. وبفقدانها صُفي الجناح الشمالي للدولة العثمانية في المجر تصفية تامة.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["فقدان إشتولني بلغراد — مدينة تتويج الملوك المجريين", "c6147255"], "d": ["كانت المدينة التي توّج فيها الملوك المجريون ودُفنوا قرونًا قد أخذها القانوني عام 1543، وصارت من أهم مراكز سناجق إيالة بودين. وسلّمت القلعة، التي قطع ما حولها تمامًا بعد نحو سنتين من سقوط بودين. وبهذا الفقدان انحصر الوجود العثماني غرب الدانوب في محيط سيريم وأوسييك.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["فقدان زيغتوار", "834910a7"], "d": ["كانت زيغتوار القلعة التي توفي فيها السلطان سليمان القانوني في حملته الثالثة عشرة والأخيرة عام 1566 في أثناء الحصار؛ ولذلك كان لها مكان رمزي في الذاكرة العثمانية. وبعد مئة وثلاث وعشرين سنة، وبعد سقوط جميع القلاع المحيطة بها، سلّمت القلعة المحمية بالمستنقعات. وهُدم الضريح الذي دُفنت فيه أحشاء القانوني والبلدة المحيطة به بعد انتقالهما إلى الإدارة الهابسبورغية.", "54f30d14"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["فقدان فاراد", "6cce360d"], "d": ["كانت فاراد القلعة المفتاحية المفتوحة على ترانسلفانيا التي أخذها كوبريلي محمد باشا عام 1660 وجعلها مركز إيالة تحمل اسمها. وسلّمت القلعة، التي بقيت وحيدة تمامًا بعد هزيمة سلانكمن، من الجوع بعد حصار دام نحو سنتين. وبفقدانها انتهى فعليًا النفوذ العثماني في ترانسلفانيا واستقرت السيادة الهابسبورغية شرق التيسا.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["فقدان يانوفا — إغلاق طريق ترانسلفانيا", "4b5e30d8"], "d": ["كانت يانوفا قلعة أُخذت عام 1658 وتمسك الصلة بين فاراد وتيميشوارا. وحين قُطع ما حولها فور سقوط فاراد، خرجت هي أيضًا من اليد. وهكذا عُزلت إيالة تيميشوارا عن الشمال تمامًا، وبقيت حتى كارلوفجه الأرض المجرية الوحيدة التي ظلت في يد العثمانيين.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["تأسيس حكم الفلاديكا في الجبل الأسود — الانفصال الفعلي لتسيتينيي", "a924b778"], "d": ["في السنوات التي أرخت فيها حرب الحلف المقدس الرقابة العثمانية في البلقان، صارت المطرانية على رأس دير تسيتينيي منصبًا ينتقل من الأب إلى الابن في أسرة بتروفيتش، ونالت المنطقة فعليًا إدارة منفصلة. وبفضل وعورة الجبال استمرت هذه الفلاديكية قرنين لا مستقلة تمامًا ولا تابعة تمامًا؛ ولن يُعترف باستقلالها قانونيًا إلا بمعاهدة برلين 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["استرداد كورنثة (كورنث)", "26f53e3a"], "d": ["كانت كورنثة أول محطة كبرى في حملة المورة التي قادها داماد علي باشا؛ واستعاد العثمانيون المدينة من البنادقة في يونيو 1715، وتقدموا من هناك إلى بقية شبه الجزيرة.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["هجوم نادر: فقدان تبريز ونخجوان وهمدان وكرمانشاه ومراغة وقصر شيرين", "d95efd59"], "d": ["فُقدت مدن غرب إيران، التي أُخذت بين عامي 1723 و1727 باستغلال انهيار الدولة الصفوية، واحدة بعد أخرى بهجوم نادر خان الذي استولى فعليًا على السلطة في إيران. ووقعت أردبيل وخلخال في أذربيجان في يد نادر أيضًا. ولقي فقدان همدان وكرمانشاه وقصر شيرين صدًى ثقيلًا في إسطنبول؛ وكان عدم خروج الجيش للحملة وانتظاره في أسكودار ومحاولة التستر على الخسارة من الأسباب المباشرة لثورة بترونا خليل التي اندلعت بعد ستة أسابيع.", "3affcf18"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["هزيمة باغافارد (أرباجاي) — فقدان القوقاز لمصلحة نادر خان", "4262f54c"], "d": ["أمكن الاحتفاظ عشر سنوات بإيالات القوقاز التي أُخذت عام 1723-1725 باستغلال انهيار الدولة الصفوية. وألحق نادر خان، الذي استولى فعليًا على السلطة في إيران، هزيمة ثقيلة بالجيش العثماني في باغافارد قرب ريفان؛ وفقد السردار عبد الله باشا كوبريلي حياته في ساحة المعركة. وبعد الهزيمة أُخليت ريفان وتفليس وكنجة وشروان في غضون أشهر. وعاد الحد الشرقي إلى خط قصر شيرين لعام 1639، على أن يتأكد ذلك عام 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["فقدان بندر لمصلحة الروس", "0daca453"], "d": ["بعد هزيمة سهل قارطال، كان الجيش العثماني قد انسحب إلى جنوب الدانوب وبقيت القلاع بين البغدان وأوزي وحدها. وأُخذت بندر، التي تمسك نقطة عبور نهر تورلا، بالهجوم بعد حصار دام شهرين؛ ونُهبت المدينة. وكسر فقدان القلعة الحلقة الوسطى لخط دفاع شمال البحر الأسود، وسقطت بعدها آق كرمان وكيلي. وستُعاد بندر في كوتشوك قاينارجه، لكنها ستُفقد مرة أخرى عام 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["دخول إمارة آل صباح في الكويت تحت الحماية العثمانية", "3584dba0"], "d": ["بحسب مادة «الكويت» في TDV أسست قبيلة العتوب القادمة من نجد الميناء في مطلع القرن الثامن عشر، وتسلّمت أسرة آل صباح الإدارة نحو نهاية القرن. وفي السنوات نفسها التي وقعت فيها الأحساء في يد السعوديين، دخلت الإمارة، التي لم يبقَ أمامها خيار سوى الاستناد إلى البصرة أمام الضغط الوهابي، تحت الحماية العثمانية. وسيُرسَّم الرابط عام 1871 بترتيبات مدحت باشا في البصرة، وستُعدّ الكويت واحدًا من ثلاثة أقضية في سنجق البصرة؛ وتستند المطالبة الإقليمية اللاحقة للعراق إلى هذا السجل أيضًا.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["فقدان مكة لمصلحة الوهابيين", "2da23acd"], "d": ["توجهت الحركة الوهابية، التي وُلدت في نجد، إلى الحجاز في عهد سعود بن عبد العزيز؛ وبعد الطائف والمدينة سُلّمت مكة أيضًا للمرة الثانية — إذ سلّم أمير مكة الشريف غالب المدينة للوهابيين بشرط البقاء في الإمارة. وهُدمت الأضرحة وانقطع طريق قوافل الحج القادمة من الشام والقاهرة؛ وانقطعت في هذه السنوات أيضًا الصرة التي كان السلطان يرسلها كل عام إلى الحرمين — والاستثناء الوحيد للمخصصات التي استمرت دون انقطاع حتى 1915 هو عهد السيادة الوهابية. ولأن لقب حامي الحرمين كان من الركائز الأساسية لشرعية السلطان، كان هذا الفقدان ضربة سياسية ثقيلة تتجاوز فقدان الأرض؛ وسيستغرق استرداد المكان سبع سنوات ولن يتحقق إلا بجيش محمد علي باشا الكافالي.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["نهاية جمهورية دوبروفنيك — الاحتلال الفرنسي", "f8e27bf1"], "d": ["استولى الفرنسيون، الذين استقروا على ساحل دالماتيا بمعاهدة كامبو فورميو (1797)، على دوبروفنيك في 27 أيار/مايو 1806 وأنهوا الجمهورية التجارية الصغيرة. وهكذا انتهى وضع التبعية الذي دام ثلاثة قرون ونصفًا لدوبروفنيك التي حافظت على حكمها الذاتي وامتيازاتها التجارية بدفع الجزية للدولة العثمانية منذ عام 1458؛ وتنتقل المدينة وجزيرة ملييت (Mljet) التابعة للجمهورية على الخريطة إلى الإدارة الفرنسية المباشرة.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["فقدان سوخوم — انفتاح ساحل البحر الأسود الشرقي", "adc96bd4"], "d": ["في الحرب العثمانية الروسية 1806-1812، توجه الأسطول الروسي إلى الساحل الشرقي للبحر الأسود وأخذ سوخوم قلعه، التي استندت إليها السيادة العثمانية في أبخازيا. وكانت القلعة مركز الصلة بالقبائل القوقازية والتجارة الساحلية. وبفقدانها استقرت روسيا للمرة الأولى استقرارًا دائمًا على الساحل الشرقي للبحر الأسود؛ وانحصر النفوذ العثماني في القوقاز حول أنابا وبوتي.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["ترك بارغا للإدارة العثمانية", "66e0cc5d"], "d": ["كانت بارغا في يد البندقية منذ عام 1401 ولم تدخل قط الإدارة العثمانية؛ وبعد سقوط البندقية انتقلت تباعًا إلى فرنسا وإنجلترا. وتلخص مادة «تبدلنلي علي باشا» في TDV الوضع كما يلي: سُلّمت المدينة إلى الإنجليز ولم تُترك لإدارة علي باشا إلا عام 1819. وانتهى التسليم بهجرة القسم الأكبر من أهلها إلى الجزر الأيونية. وهكذا انضم إلى الإمبراطورية آخر الثلاثي بريفزة — بارغا — فونيتسا الذي تُرك للبندقية في باساروفجة؛ وستبقى بارغا عثمانية أربعًا وتسعين سنة.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["انتقال كورنثة (كورنث) إلى الثوار اليونانيين", "892dcdc6"], "d": ["خلال حرب الاستقلال اليونانية وقعت قلعة أكروكورنثة في أيدي الثوار، وأُسر قائد القلعة كامل بك.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["فقدان أنابولي (نافبليو) لمصلحة الثوار", "1a67fa50"], "d": ["سلّمت أنابولي، الميناء الأشد تحصينًا في المورة، من الجوع بعد حصار دام أكثر من سنة. وكانت القلعة منذ بداية الثورة آخر ركيزة كبرى للرقابة العثمانية في شبه الجزيرة؛ وبفقدانها صارت المورة بأكملها في يد الثوار. وستصبح المدينة بعد وقت قصير أول عاصمة للدولة اليونانية الجديدة.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["انتقال إينه بختي (ليبانتو) إلى الإدارة اليونانية", "c9d19d4b"], "d": ["خرجت إينه بختي، على الساحل الشمالي لخليج كورنثة والتي ظلت في يد العثمانيين حتى الثورة اليونانية، من اليد في نيسان/أبريل 1829 ودخلت الإدارة اليونانية؛ وحُوّل اسم البلدة إلى نافباكتوس القديمة. واختفى تمامًا سكان المدينة المسلمون واليهود وصارت بلدة صغيرة.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["الاحتلال الفرنسي للجزائر — نهاية أوجاق دام ثلاثة قرون", "0be8f568"], "d": ["اتخذت فرنسا من حادثة المروحة، التي نشأت عن خلاف حول دين مستحق، ذريعةً لها، فضربت حصارًا بحريًا على السواحل الجزائرية ثلاث سنوات، ثم أنزلت جنودها في سيدي فرج. وفي ختام حملة دامت ثلاثة أسابيع استسلم الداي حسين، وانتهى بذلك أوجاق الجزائر العثماني الذي استمر منذ عام 1516. ولم يقتصر الاحتلال على العاصمة، فقد خرجت في صيف العام نفسه من اليد تلمسان وشرشال والمدية في المناطق الداخلية. وكان إخضاع الساحل كله للسيطرة الفرنسية سيستغرق أربعًا وعشرين سنة أخرى.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["تسليم إغريبوز لليونان — مع الجزيرة (كاريستوس وأوريوي)", "7b524aa4"], "d": ["سُلّمت إغريبوز، التي شهدت اشتباكات كثيفة طوال حرب الاستقلال اليونانية لكنها بقيت في يد العثمانيين، لليونانيين عام 1831 بعد أن دخلت معاهدة الصلح حيز التنفيذ. وهاجر المسلمون من أهل المدينة، التي كانت قاعدة بحرية مهمة منذ عام 1470، جماعيًا إلى الأراضي العثمانية بعد أن باعوا جميع أموالهم بأسعار رخيصة جدًا؛ وبقيت المدينة خالية زمنًا طويلًا، ووصفها الرحالة الألماني فالميرايير عام 1842 بأنها مدينة أشباح.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["احتلال وهران (وهران) على يد الفرنسيين", "a8415d66"], "d": ["كانت وهران، التي تخلّت عنها إسبانيا دون قتال عام 1792، أكبر موانئ غرب الجزائر. ودخلت القوات الفرنسية المدينة بعد ستة أشهر من سقوط العاصمة. وكانت الحملة الغربية المنطلقة من هناك ستواجه سريعًا مقاومة الأمير عبد القادر التي استمرت خمس عشرة سنة.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["احتلال عنابة (بون)", "21f37fb1"], "d": ["عنابة، ميناء شرق الجزائر القريب من الحدود التونسية، استولت عليها القوات الفرنسية وجعلتها قاعدةً للزحف على قسنطينة. وكانت المدينة في الوقت نفسه أقرب ميناء أفريقي يقابل جزيرة سردينيا.", "1ca5b213"]},
"OLAYLAR_EK6:1833-03-31:0":{"b": ["تخلّي الدولة العثمانية عن أثينا للدولة اليونانية الجديدة", "98af5572"], "d": ["كانت أثينا عثمانية منذ عام 1456، وقد تبدّلت السيطرة عليها مرات عدة خلال حرب الاستقلال اليونانية، وعادت حامية الأكروبوليس عام 1827 إلى السيطرة العثمانية. ولما كانت المدينة تقع شمال الحدود التي رُسمت بموجب بروتوكول لندن، فقد أُحيلت إلى المملكة الجديدة وأخلت الحامية الأكروبوليس. وفي العام التالي أُعلنت أثينا عاصمةً لليونان بدلًا من نافبليو.", "6fca14a0"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["احتلال بجاية (بوجي)", "a8927e00"], "d": ["كان ميناء بجاية، حيث تنفتح جبال القبائل على البحر، آخر حلقة مستقلة في الخط الساحلي بين الجزائر وعنابة. وقد استُولي عليه بدعم من المدفعية البحرية، غير أن المنطقة الجبلية الداخلية خلفه لن تدخل تحت السيطرة الفرنسية إلا بعد ثلاثين سنة أخرى. وتشكّل هذه الاحتلالات الساحلية انحسار الجزائر العثمانية على الخريطة عامًا بعد عام.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["احتلال سطيف", "2073731a"], "d": ["بعد سقوط قسنطينة قبل عام، صعدت القوات الفرنسية إلى الهضبة واستولت على مدينة سطيف الرومانية القديمة وأقامت فيها حامية دائمة. وكانت سطيف نقطة تقاطع طرق القوافل بين الساحل والصحراء؛ وأظهر احتلالها أن فرنسا لم تعد تسيطر على الموانئ وحدها بل بدأت تسيطر على شبكة التجارة الداخلية أيضًا.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["احتلال بسكرة — فقدان باب الصحراء", "d895cad0"], "d": ["كانت بسكرة بابًا ينفتح على الصحراء عند السفح الجنوبي لجبال الأطلس، ومركز واحات النخيل. وباحتلالها، في السنوات التي بدأت فيها مقاومة الأمير عبد القادر تنكسر، بلغت السيطرة الفرنسية لأول مرة الشاطئ الشمالي للصحراء. وكان ما بعد ذلك حملة صحراوية تتقدم من واحة إلى واحة.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["احتلال تقرت — خروج الجزائر كلها من اليد", "33c056e2"], "d": ["بالاستيلاء على تقرت، مدينة الواحة في شمال الصحراء، اكتمل الاحتلال الذي بدأ عام 1830 في النصف الشمالي من الجزائر الحالية. وكانت الدولة العثمانية في هذه السنوات تقاتل في حرب القرم إلى جانب فرنسا؛ ومع أنها لم تتخلَّ رسميًا قط عن مطالبتها القانونية بالجزائر، فإنها لم تستطع من الناحية الفعلية أن تخطو خطوة واحدة. وكانت طرابلس الغرب الأرض الوحيدة التي بقيت في يدها في شمال أفريقيا.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["سقوط الأبيض — انتقال كردفان إلى قوات المهدي", "58299f62"], "d": ["انتشرت الحركة التي أطلقها محمد أحمد، الذي أعلن نفسه مهديًا، بسرعة في وجه إدارة مصر في السودان. وسقطت الأبيض، مركز كردفان، بعد حصار دام أربعة أشهر، وأصبحت عاصمة الثورة؛ وأتاحت الخزينة ومخازن السلاح في المدينة للحركة أن تتحول إلى جيش. وكان السودان من الناحية القانونية لا يزال أرضًا تابعة للخديوية المصرية المرتبطة بالدولة العثمانية، ولذلك فإن الخسارة تسقط على الخريطة من جسم الإمبراطورية.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["سقوط الخرطوم — فقدان السودان كله", "d4b98464"], "d": ["بعد حصار دام عشرة أشهر دخلت قوات المهدي الخرطوم، عند ملتقى النيل الأزرق بالنيل الأبيض؛ وقُتل حاكم المدينة غوردون، وتأخرت القوة البريطانية المرسلة لنجدته يومين. ومنذ هذا التاريخ بقي السودان كله، بما فيه سنار ودنقلة وكردفان، أربع عشرة سنة تحت إدارة الدولة المهدية. ولن تدخل المنطقة في الإدارة المشتركة البريطانية المصرية إلا عام 1899، وقد انقطعت الصلة العثمانية بها تمامًا.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["الاحتلال الإيطالي لمصوع — فقدان الساحل الغربي للبحر الأحمر", "c333b95b"], "d": ["احتلت إيطاليا ميناء مصوع، مركز ولاية الحبشة، مستفيدةً من الاضطراب الذي عمّ السودان بثورة المهدي؛ وقد شكّل ذلك نواة إريتريا الإيطالية. وخرجت سواكن في الشمال وأرخبيل دهلك في البحر في العملية نفسها. وبذلك انتهت السيادة العثمانية على الساحل الغربي للبحر الأحمر، المستمرة منذ عهد السلطان سليم الأول، وأصبح البحر مياهًا أجنبية على ضفتيه.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["الاحتلال الإيطالي لرودس", "e08662c5"], "d": ["أرادت إيطاليا في حرب طرابلس الغرب أن تحمل الدولة العثمانية على الجلوس إلى مائدة التفاوض، فنقلت الحرب إلى البحر المتوسط وأنزلت جنودها في رودس. وسُلّمت الجزيرة في غضون أيام قليلة. وبذلك لم تعد رودس، التي فتحها القانوني عام 1522 بعد حصار طويل وبقيت في يده ثلاثمئة وتسعين سنة، أكبر قاعدة جزرية للإمبراطورية في شرق المتوسط؛ ومع أنها عُدّت احتلالًا مؤقتًا في معاهدة أوشي، فإنها لم تُسترد بعد ذلك.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["الاحتلال الإيطالي لجزر الدوديكانيز", "200aacf2"], "d": ["في غضون أسبوع من الاستيلاء على رودس احتل الأسطول الإيطالي الجزر المجاورة أيضًا؛ وسيُطلق على هذا الأرخبيل لاحقًا اسم «الدوديكانيز». وكانت معظم الجزر تبعد أميالًا قليلة عن الساحل الأناضولي، وتتحكم في المعبر الجنوبي الشرقي لبحر إيجة. وعُدّ الاحتلال مؤقتًا في معاهدة أوشي مقابل التخلي عن طرابلس الغرب، غير أن إيطاليا لم تُخلِ الجزر قط؛ وستُسلَّم إلى اليونان عام 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["احتلال إسطنكوي (كوس)", "ab246c62"], "d": ["كانت إسطنكوي، الحلقة الأخيرة في حملة الدوديكانيز، جزيرة خصبة كثيفة السكان تقع قبالة شبه جزيرة بودروم مباشرة. وبهذا الاحتلال دخلت جميع الجزر في الركن الجنوبي الشرقي من بحر إيجة تحت السيطرة الإيطالية، وطُوّق الساحل الجنوبي الغربي للأناضول من أوله إلى آخره بسلسلة من الجزر الأجنبية.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["إعلان استقلال إيكاريا (نيكاريا)", "c4452033"], "d": ["في جزيرة إيكاريا الصغيرة الواقعة بين ساموس وخيوس، ثار الأهالي في أجواء الغموض التي خلّفتها الاحتلالات الإيطالية، وأخرجوا الدرك العثماني من الجزيرة، وأعلنوا «دولة حرة» دامت خمسة أشهر، لها علمها وطوابعها ومجلسها. وفي نوفمبر 1912 انضمت الجزيرة إلى اليونان. وعلى الرغم من صغرها، فإن هذه الواقعة دليل واضح على كيفية تفكك الإدارة المركزية في بحر إيجة.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["خروج ساموس من الإدارة العثمانية", "3a862f2b"], "d": ["كانت ساموس إمارة ذات حكم ذاتي تدفع الجزية للدولة العثمانية منذ عام 1832، ويحكمها أمير تعيّنه إسطنبول. وفي الفراغ الذي أحدثته حرب طرابلس الغرب، استولت حركة الاتحاد مع اليونان في الجزيرة على الإدارة وانتهى نظام الإمارة ذات الحكم الذاتي فعليًا؛ وأعلنت الجزيرة في العام نفسه انضمامها إلى اليونان. وكانت هذه الجزيرة، التي لا تبعد عن الساحل الأناضولي سوى كيلومترين، من أولى الأراضي التي فُقدت في بحر إيجة.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["سقوط يانيا — فقدان إبيروس وبارغا", "d42fce18"], "d": ["استسلمت يانيا، التي حوصرت خمسة أشهر في حرب البلقان، بعد سقوط مواقع بيزاني؛ وانتقلت إبيروس كلها إلى اليونان مع المدينة. وخرجت بارغا، التابعة لسنجق يانيا، من اليد في هذا التاريخ أيضًا، وانتهت إدارة عثمانية دامت أربعًا وتسعين سنة. وكان فقدان يانيا يعني إغلاق آخر نافذة للإمبراطورية على الأدرياتيك.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["سقوط أدرنة في يد البلغار", "459d2e56"], "d": ["بعد حصار دام خمسة أشهر ونصف الشهر، استسلمت أدرنة وقد نفدت ذخيرتها وأقواتها؛ وأُسر شكري باشا. وعُدّ سقوط المدينة، وهي عثمانية منذ عام 1361 وظلت عاصمة اثنتين وتسعين سنة، أقسى ضربة في حرب البلقان. وستُستعاد أدرنة بعد أربعة أشهر في حرب البلقان الثانية، بالإفادة من انهيار بلغاريا على الجبهات الأخرى.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["فقدان ينبع لصالح قوات الشريف حسين", "e291c816"], "d": ["امتدت الثورة التي أطلقها الشريف حسين في يونيو إلى ساحل البحر الأحمر؛ وسقطت ينبع، ميناء المدينة المنورة، في أيدي الثوار بدعم من الأسطول البريطاني. وأصبح الميناء المدخل الرئيسي لتدفق السلاح والمال من الخارج إلى الثورة. وبذلك انقطعت صلة قوات فخري باشا في المدينة المنورة بالبحر، وبقيت المدينة وحدها عند طرف سكة حديد الحجاز.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["معركة غزة الثالثة — فقدان غزة وخان يونس", "c142a069"], "d": ["بعد محاولتين فاشلتين اخترق اللنبي الجبهة في هجومه الثالث بالالتفاف من بئر السبع، فانهار خط غزة الذي ظل ستة أشهر صامدًا. وأُخليت غزة وخان يونس إلى جنوبها في اليوم نفسه. وكان هذا الاختراق بداية تفكك الجبهة الفلسطينية؛ وستسقط القدس بعد خمسة أسابيع.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["احتلال كوموتيني (غوميلجينه) — فقدان تراقيا الغربية", "904d813c"], "d": ["تراقيا الغربية، التي دخلت بعد مودروس أولًا تحت سيطرة قوات الوفاق، تُركت لليونان بقرار مؤتمر سان ريمو، ودخل الجيش اليوناني كوموتيني. وكانت المنطقة، التي استُردت من بلغاريا عام 1913، آخر أرض فقدتها الإمبراطورية في الروملي. وستُنظَّم أوضاع السكان الأتراك فيها بعد ثلاث سنوات في لوزان بنظام الأقليات.", "e3d0605f"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["تفكك الدولة الإيلخانية: وفاة أبي سعيد بهادر خان", "0f187469"], "d": ["وفقًا لمادة «الإيلخانيون» في موسوعة الإسلام التركية (TDV)، أدت وفاة أبي سعيد دون وريث إلى تفتت الدولة الإيلخانية التي حكمت إيران قرنًا؛ فاستفاد الأمراء من صراعات العرش وأسسوا أسرًا محلية كالجلائريين والقره قويونلو والمظفريين والسربداريين في خراسان وأسرة أرتنا. وقسّم هذا التفكك المنطقة إلى فسيفساء من الإمارات ستدوم قرنًا؛ وفي النهاية ستُوحَّد من جديد بحملات تيمور.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["إخضاع تيمور القسم الأكبر من إيران لسلطانه", "1cee2b82"], "d": ["وفقًا لمادة «تيمور» في موسوعة الإسلام التركية (TDV)، فإن تيمور، الذي صفّى الأسر المحلية التي خلفت الإيلخانيين، كالسربداريين والكرت والمظفريين، واحدة بعد أخرى منذ أوائل عقد 1380، أخضع فعليًا القسم الأكبر من إيران لسلطانه أثناء «الحملة ذات السنوات الثلاث» في 1386-1388؛ أما الضربة النهائية لأسرة المظفريين فستُوجَّه عام 1393. وبذلك رُبطت المنطقة من جديد بسلطة مركزية واحدة بعد تفتت دام قرنًا.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["انتصار آراس: قره يوسف يهزم التيموري أبا بكر ميرزا", "4b61a75a"], "d": ["بعد وفاة تيمور عام 1405، عاد أمير القره قويونلو قره يوسف من المنفى، واستولى على أونيك وأعاد تملّك أراضيه في شرق الأناضول، ثم زحف على أبي بكر ميرزا، حفيد تيمور الذي كان يُعدّ صاحب أذربيجان والعراقين، وهزمه على ضفاف نهر آراس. ولم يمنح هذا الانتصار تبريز للقره قويونلو: فتذكر مادة `tebriz` في TDV أن المدينة كانت عام 1408 في يد أبي بكر ميرزا؛ والمعركة التي أكسبت أذربيجان هي معركة سردرود في 13 أبريل 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["انتصار سردرود: تبريز وأذربيجان تنتقلان إلى القره قويونلو", "1f0a429d"], "d": ["هزم قره يوسف التيموري أبا بكر ميرزا للمرة الثانية بعد آراس، في سردرود قرب تبريز؛ وأكسب هذا الانتصار أذربيجان للقره قويونلو. ثم كلّف قره يوسف بسطام بك بفتح العراق العجمي؛", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["وباء الطاعون في إسطنبول وانتقال السراي إلى أدرنة", "70c7a163"], "d": ["وفقًا لمادة إسطنبول في موسوعة الإسلام التركية (TDV)، فإن الإسكان السريع والكثيف في المدينة هيّأ الأرضية لانتشار الأوبئة من حين إلى آخر؛ وخلال وباء الطاعون عام 1466 انسحب البلاط وأركان الدولة مؤقتًا إلى أدرنة. وقد تكبّد عدد سكان المدينة خسائر جسيمة في مثل هذه الأوبئة.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["إنهاء أوزون حسن لدولة القره قويونلو", "ef68399e"], "d": ["وفقًا لمادة أوزون حسن في موسوعة الإسلام التركية (TDV)، هزم أوزون حسن، سلطان الآق قويونلو، جهان شاه، سلطان القره قويونلو، في منطقة بينغول-سنجق وقتله في 12 ربيع الآخر 872 / 10 نوفمبر 1467؛ وهُزم ابن جهان شاه، حسن علي، في مرند في سبتمبر 1468، وقُتل أمام همدان في أبريل-مايو 1469، وبذلك قُضي نهائيًا على دولة القره قويونلو. وانتقلت الأراضي إلى سيادة الآق قويونلو؛ وسوف تتسع الدولة في العقد التالي حتى بلغت دواخل إيران.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["افتتاح مدارس صحن ثمان للتدريس", "021f2a83"], "d": ["وفقًا لمادة صحن ثمان في موسوعة الإسلام التركية (TDV)، فإن هذه المدارس الثماني التي أُنشئت ضمن مجمع الفاتح صُمّمت بوصفها أرفع مؤسسة تعليمية في عصرها، وشكّلت قمة التسلسل الهرمي للعلمية العثمانية. وعُدّ التدريس فيها والتخرج منها في القرون التالية أرفع درجة في مسيرة القضاء والتدريس.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["اكتمال قصر طوب قابي (السراي الجديد)", "d2db6323"], "d": ["وفقًا لمادة قصر طوب قابي في موسوعة الإسلام التركية (TDV)، تختلف مصادر العصر في تاريخي بداية البناء ونهايته؛ وبحسب تاريخ 883 (1478) الوارد في كتابة باب همايون، كان البناء الذي بدأ بأمر الفاتح في عام 1465 على الأرجح قد اكتمل في معظمه حتى هذه السنة، وحلّ القصر محل مركز الدولة في القصر القديم. وبذلك انتقل السلطان إلى مقره الجديد الذي سيكون القلب الإداري والاحتفالي للدولة ثلاثة قرون.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["جلوس بايزيد الثاني على العرش في إسطنبول", "9b686d04"], "d": ["وفقًا لمادة بايزيد الثاني في موسوعة الإسلام التركية (TDV)، جاء الأمير بايزيد، وكان أمير سنجق أماسيا، مسرعًا إلى إسطنبول عند بلوغه نبأ وفاة أبيه، وتولى العرش؛ وسبق بدعم الإنكشارية خروج أخيه جم من قونية. ووُزّعت على الإنكشارية خلال الجلوس بقشيش الجلوس المعتاد. وكان تغيير العرش هذا هو الذي أشعل فتيل الصراع بين الأخوين.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["إعلان جم سلطان نفسه سلطانًا في بورصة", "b355168a"], "d": ["وفقًا لمادة جم سلطان في موسوعة الإسلام التركية (TDV)، وصل جم إلى بورصة عن طريق قرمان، واستولى على المدينة وأعلن نفسه سلطانًا وأمر بقراءة الخطبة باسمه. وانتهت هذه السلطنة القصيرة بهزيمة جم في يني شهر أمام القوات التي أرسلها أخوه الأكبر بايزيد الثاني. وعلى إثر الهزيمة اضطر جم إلى الفرار نحو مصر.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["إعدام كدك أحمد باشا", "6d75a58c"], "d": ["وفقًا لمادة كدك أحمد باشا في موسوعة الإسلام التركية (TDV)، أُعدم الباشا المعروف بحملة أوترانتو وبصدارته العظمى في أدرنة بأمر بايزيد الثاني، بسبب موقفه في مسألة جم سلطان وما أُثير من قلق حول نفوذه. وأثار موت أحد أكثر قادة عهد الفاتح خبرة صدى واسعًا في القصر.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["تأسيس أول مطبعة في إسطنبول", "04475930"], "d": ["وفقًا لمادة المطبعة في موسوعة الإسلام التركية (TDV)، أسّس الأخوان داود وصموئيل بن نحمياس، من المهاجرين اليهود القادمين من إسبانيا، أول مطبعة في إسطنبول تطبع بالحروف العبرية. وسُجّلت بوصفها أول مبادرة طباعية عاملة في الأراضي العثمانية؛ أما الطباعة التركية بالحروف العربية فلن تكون ممكنة إلا بعد ذلك بزمن طويل، في القرن الثامن عشر.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["استيلاء الشاه إسماعيل على تبريز: تأسيس الدولة الصفوية", "014d81e6"], "d": ["وفقًا لمادتي «الصفويون» و«الآق قويونلو» في موسوعة الإسلام التركية (TDV)، ألحق إسماعيل، الشيخ الشاب لتكية أردبيل، بالجيش الذي كوّنه من مريديه القزلباش في الأناضول هزيمة ثقيلة بسلطان الآق قويونلو ألوند في ناحية نخجوان؛ ففر ألوند إلى ديار بكر، ودخل إسماعيل تبريز وجلس على العرش وأعلن مذهب الشيعة الاثني عشرية مذهبًا رسميًا. وبذلك طُويت سيادة الآق قويونلو وكذلك عهد الإمارات التي تلت الإيلخانيين في المنطقة؛ وتأسست الدولة الصفوية التي ستدوم ثلاثة قرون.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["زلزال «القيامة الصغرى» في إسطنبول", "53e3b1d6"], "d": ["وفقًا لمادة إسطنبول في موسوعة الإسلام التركية (TDV)، عُرف الزلزال العنيف الذي ضرب المدينة بين الناس باسم «القيامة الصغرى»؛ ووقع ضرر جسيم في الأسوار والجوامع وكثير من المباني، وسقط عدد كبير من الضحايا. وبأمر بايزيد الثاني بدأت في المدينة حملة واسعة للترميم والتعمير.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["اندلاع ثورة شاه قولو", "3d9a4a90"], "d": ["وفقًا لمادة شاه قولو بابا تكه لي في موسوعة الإسلام التركية (TDV)، جمع شاه قولو، متغذيًا بالدعاية الصفوية، حوله جمهورًا واسعًا من التركمان في ناحية تكه، وأطلق ثورة كبرى ذات طابع ديني اجتماعي. وهزّت الثورة، وهي من أخطر أزمات الأمن الداخلي في العصر، سلطة الدولة المركزية هزًّا عميقًا.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["وفاة بايزيد الثاني في طريقه إلى ديمتوقة", "c46e98c9"], "d": ["غادر السلطان السابق إسطنبول بعد تنازله عن العرش متوجهًا إلى ديمتوقة، المدينة التي وُلد فيها، فاعتلّ في قرية أبالار قرب جورلو وهو يسير في محفته التي لا تقطع في اليوم أكثر من 5-6 كم، وتوفي في 25 ربيع الأول 918 (10 يونيو 1512). وتعدّ موسوعة الإسلام التركية (TDV) سبب الوفاة مثار شك كبير؛ ويُشار بحسب بعض المصادر المحلية والأجنبية إلى احتمال أنه مات مسمومًا. وبذلك توفي بعد سلطنة دامت إحدى وثلاثين سنة ثامنُ سلاطين آل عثمان.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["إعدام الأمير أحمد بأمر يافوز سليم", "65abb2f2"], "d": ["وفقًا لمادة سليم الأول في موسوعة الإسلام التركية (TDV)، هُزم الأمير أحمد، المقرّب من أبيه بايزيد الثاني والمنافس الحقيقي على العرش، في سهل يني شهر خلال الصراع الذي خاضه بعد جلوس أخيه سليم على العرش، وأُمسك به وقُتل وهو يفرّ من ميدان المعركة. وبهذه الواقعة أنهى سليم إلى حد كبير التنافس على العرش بين إخوته وأبناء إخوته.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["تعيين إبراهيم باشا صدرًا أعظم", "9c94c1e3"], "d": ["وفقًا لمادة إبراهيم باشا مقبول في موسوعة الإسلام التركية (TDV)، أصبح إبراهيم باشا، الذي رُقّي من منصب رئيس الغرفة الخاصة إلى بكلربك الروملي وإلى الوزارة العظمى في اليوم نفسه، صدرًا أعظم في 13 شعبان 929 (27 يونيو 1523). وكان ذلك تعيينًا لم يسبق له مثيل بالانتقال من خدمة القصر مباشرة إلى الصدارة العظمى، ودل على قرب إبراهيم باشا الاستثنائي من القانوني.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["تعيين بربروس خير الدين باشا قبطان باشا", "a0ff6bab"], "d": ["وفقًا لمادة بربروس خير الدين باشا في موسوعة الإسلام التركية (TDV)، استُدعي خير الدين باشا، المعروف بنجاحاته في الجزائر، إلى إسطنبول في 6 أبريل 1534 وعُيّن قبطان باشا وبكلربك جزائر البحر الأبيض. ويُعدّ هذا التعيين بداية إعادة هيكلة الأسطول العثماني وإضفاء الطابع المؤسسي على القوة البحرية في البحر المتوسط.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["رستم باشا صدرًا أعظم للمرة الأولى", "ddfcc014"], "d": ["وفقًا لمادة رستم باشا في موسوعة الإسلام التركية (TDV)، بعد عزل خادم سليمان باشا إثر خلاف مع أحد الوزراء، عُيّن رستم باشا في الوزارة العظمى في 17 رمضان 951 (2 ديسمبر 1544). وبهذا المنصب صار رستم باشا، الذي ازداد قربه من القصر بزواجه من السلطانة مهرماه، أحد أكثر رجال الدولة نفوذًا في عهد القانوني.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["أبو السعود أفندي شيخ الإسلام", "11ed04f8"], "d": ["وفقًا لمادة أبو السعود أفندي في موسوعة الإسلام التركية (TDV)، عُيّن أبو السعود أفندي، الذي شغل قضاء عسكر الروملي ثماني سنوات، شيخًا للإسلام في شعبان 952 (أكتوبر 1545)، وبقي في هذا المنصب ثماني وعشرين سنة وأحد عشر شهرًا. وقد أدى أبو السعود أفندي، المعروف بفتاواه التي وفّقت بين قوانين القانوني والشريعة، دورًا حاسمًا في تشكيل المؤسسات القانونية والتعليمية في عصره.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["وفاة بربروس خير الدين باشا", "3378a0bf"], "d": ["وفقًا لمادة بربروس خير الدين باشا في موسوعة الإسلام التركية (TDV)، توفي في إسطنبول في 6 جمادى الأولى 953 (5 يوليو 1546) بعد مرض قصير. وقد دُفن في الضريح الملاصق للمدرسة التي أنشأها بنفسه في بشكتاش، وعُدّ موته إغلاقًا لحقبة من التفوق الذي أقامه الأسطول العثماني في البحر المتوسط.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["بدء بناء جامع السليمانية ومجمعه", "101ec36f"], "d": ["وفقًا لمادة جامع السليمانية ومجمعه في موسوعة الإسلام التركية (TDV)، وُضع أساس المجمع عام 1550 تحت رئاسة المعمار سنان، وصُمّم مجمعًا اجتماعيًا كبيرًا يتألف إلى جانب الجامع من مدارس ودار شفاء وعمارة ومكتبة. وكان البناء من أكبر برامج الإنشاء التي رمزت إلى قوة سلطنة القانوني وعمران إسطنبول.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["بدء موجة طاعون جديدة في إسطنبول وما حولها", "547d6bf6"], "d": ["وفقًا لمادة الطاعون في موسوعة الإسلام التركية (TDV)، وقعت إحدى أوبئة القرن 16 التي أصابت العالم الإسلامي بين عامي 1552 و1566، وكان تأثيرها شديدًا خاصة في إسطنبول والأناضول والروملي ومصر وشمال أفريقيا. وتُعدّ طرق التجارة المتسعة وازدياد حركة السكان من العوامل التي سهّلت انتشار الأوبئة في أقوى فترات الإمبراطورية.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["تعيين قره أحمد باشا صدرًا أعظم", "a7d7748e"], "d": ["وفقًا لمادة قره أحمد باشا في موسوعة الإسلام التركية (TDV)، رُقّي قره أحمد باشا، الذي كان يشغل منصب الوزير الثاني، إلى الوزارة العظمى في 27 شوال 960 (5 أكتوبر 1553) بعد عزل الصدر الأعظم القائم فجأة. ويشير هذا التغيير إلى فترة تبدّلت فيها موازين القوى داخل القصر بسرعة، وهي تتزامن مع الأيام التي أُعدم فيها الأمير مصطفى.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["إعدام قبطان باشا بيري رئيس", "3b2ad7a0"], "d": ["وفقًا لمادة بيري رئيس في موسوعة الإسلام التركية (TDV)، أُعدم البحار والخرائطي الشهير في القاهرة في أواخر عام 960 (أواخر 1553) عندما بلغت مصر الاتهامات بأنه نهب أموال المسلمين مقابل رشوة أثناء رفع حصار هرمز وترك جيشه في ميدان المعركة. ويُعدّ موت بيري رئيس، الذي صودرت أمواله، نتيجة للتنافس بين الباشوات في سياسة البصرة والمحيط الهندي البحرية في ذلك العصر.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["إعدام قره أحمد باشا وعودة رستم باشا صدرًا أعظم", "9a85076a"], "d": ["وفقًا لمادتي رستم باشا وقره أحمد باشا في موسوعة الإسلام التركية (TDV)، عُيّن رستم باشا في اليوم نفسه صدرًا أعظم للمرة الثانية بدعم من السلطانتين خرّم ومهرماه، خلفًا لقره أحمد باشا الذي أُعدم فجأة أثناء اجتماع الديوان في 13 ذي القعدة 962 (29 سبتمبر 1555). وتركت المصادر كواليس الواقعة غير واضحة، وقُدّرت بأنها نتيجة لدسائس داخل القصر.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["وفاة خرّم سلطان", "1ae998b5"], "d": ["وفقًا لمادة خرّم سلطان في موسوعة الإسلام التركية (TDV)، توفيت خرّم سلطان، التي كانت لسنوات طويلة صاحبة نفوذ كبير داخل القصر بوصفها خاصكي سلطان القانوني، في إسطنبول في 26 جمادى الآخرة 965 (15 أبريل 1558)، ودُفنت في ضريحها بمجمع جامع السليمانية. وبوفاة خرّم سلطان، التي كانت قد ثبّتت سلطتها على الحريم بعد وفاة الوالدة سلطان حفصة عام 1534، زال كذلك الأثر الموازن الذي كان يقف أمام التنافس على العرش بين ولديها بايزيد وسليم.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["ارتقاء صوقوللو محمد باشا إلى الصدارة العظمى", "896391a2"], "d": ["وفقًا لمادة صوقوللو محمد باشا في موسوعة الإسلام التركية (TDV)، ارتقى صوقوللو محمد باشا إلى الصدارة العظمى إثر وفاة سميز علي باشا في 30 ذي القعدة 972 (29 يونيو 1565)، وكان آخر صدور القانوني العظام، واستمر في هذا المنصب بعده في عهدي سليم الثاني ومراد الثالث، فصار من أطول الوزراء العظام خدمةً في التاريخ العثماني.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["وصول سليم الثاني إلى إسطنبول وجلوسه على العرش", "0289ef97"], "d": ["بعد وفاة السلطان سليمان القانوني في زيغتفار، أبقى صوقوللو محمد باشا الخبر سرًا أسابيع حفاظًا على النظام. ووفقًا لموسوعة الإسلام التركية (TDV)، يذكر سلانيكي أن تاريخ وصول سليم إلى إسطنبول هو 15 ربيع الأول 974 (30 سبتمبر 1566)، بينما يرى معظم المؤرخين المعاصرين أن الصحيح هو 9 ربيع الأول (24 سبتمبر). ولم تُعلن وفاة القانوني رسميًا في بلغراد إلا في 24-25 أكتوبر 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["نزول الأسطول الذي أعاد قلج علي باشا بناءه إلى البحر", "d0fc9f48"], "d": ["بعد الهزيمة الثقيلة في إينه بختي (7 أكتوبر 1571) بُنيت السفن في الترسانات طوال الشتاء. ووفقًا لموسوعة الإسلام التركية (TDV)، أُنزل الأسطول الجديد المؤلف من 250 قادسًا ونحو 300 سفينة جكتري من سفن الرياس المتطوعين إلى البحر في استعراض للقوة في 1 صفر 980 (13 يونيو 1572).", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["اغتيال صوقوللو محمد باشا", "6ffa8dec"], "d": ["قُتل صوقوللو محمد باشا، الذي تولى الصدارة العظمى أربع عشرة سنة في عهد ثلاثة سلاطين، طعنًا بخنجر على يد درويش اقترب منه كأنه يريد تقديم عريضة إلى ديوان العصر في قصره، في 20 شعبان 987 (12 أكتوبر 1579). ووفقًا لموسوعة الإسلام التركية (TDV)، يُناقَش أن يكون الاغتيال متصلًا بالانتقام لشيخ الحمزوية حمزة بالي الذي نُفّذ فيه حكم الإعدام.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["أول عهدنامة تجارية مع إنجلترا — منح الإنجليز الامتيازات", "59c8e3ee"], "d": ["حصل المبعوث الإنجليزي وليم هاربورن، الذي أُرسل إلى إسطنبول في أكتوبر 1578، بدعم من صوقوللو محمد باشا وخوجه سعد الدين أفندي، على عهدنامة مؤرخة في عام 1580 من مراد الثالث. وبموجب هذه العهدنامة نال التجار الإنجليز حق الانتفاع بالقدر نفسه من الامتيازات التجارية (الكابيتولاسيون) التي كانت قد مُنحت من قبل للفرنسيين والبنادقة. وتبودلت الرسائل بين الملكة إليزابيث الأولى ومراد الثالث، وأُقيمت علاقة رسمية بين الدولتين. وعقب هذه الامتيازات مباشرة تأسست في لندن عام 1581 شركة الليفانت؛ وأدار الإنجليز تجارتهم في المنطقة عبر هذه الشركة حتى عام 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["هدم مرصد إسطنبول بخط همايوني", "3bc0c78c"], "d": ["تحت تأثير فتوى بأن المراصد تجلب الشؤم على البلاد ومعارضة داخل القصر، هُدم مرصد إسطنبول بجميع آلاته بموجب خط همايوني مؤرخ في 4 ذي الحجة 987 (22 يناير 1580). ووفقًا لموسوعة الإسلام التركية (TDV)، كانت هذه نهاية قصيرة العمر للمؤسسة التي أسسها تقي الدين الراصد.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["بدء حفل ختان الأمير محمد في أت ميداني", "c2926d5d"], "d": ["خُتن الأمير محمد، ابن مراد الثالث، في احتفالات فخمة بدأت في 6 جمادى الأولى 990 (29 مايو 1582) واستمرت ستة وخمسين أو سبعة وخمسين يومًا. ووفقًا لموسوعة الإسلام التركية (TDV)، كانت الاحتفالات التي أُقيمت في أت ميداني من أروع احتفالات القصر في عصرها.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["وفاة نوربانو والدة سلطان", "77d0a577"], "d": ["توفيت نوربانو سلطان، والدة مراد الثالث، في 22 ذي القعدة 991 (7 ديسمبر 1583). ووفقًا لموسوعة الإسلام التركية (TDV)، أجرت بوصفها والدة سلطان مراسلات مع بلاطي البندقية وفرنسا، وكان مجلس الشيوخ البندقي قد قبل في العام نفسه أن يرسل إليها هدية بقيمة 2000 دوقية ذهبية بندقية مقابل خدماتها.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["اندلاع وقعة بكلربكي بسبب الأقجة المغشوشة", "db2f2e61"], "d": ["لما دفعت الدولة الرواتب بأقجة خُفضت نسبة الفضة فيها، حاصر السباهية والإنكشارية القصر وأثاروا تمردًا دمويًا دخل التاريخ باسم وقعة بكلربكي. ووفقًا لمادة عبد القادر شيخي أفندي في موسوعة الإسلام التركية (TDV)، عُزل شيخ الإسلام من منصبه بسبب هذه الواقعة.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["جلوس محمد الثالث على العرش وخنق تسعة عشر أميرًا", "2cd9a8c5"], "d": ["وصل محمد الثالث إلى إسطنبول يوم الجمعة 16 جمادى الأولى 1003 (27 يناير 1595) إثر وفاة أبيه مراد الثالث، وتولى العرش. ووفقًا لموسوعة الإسلام التركية (TDV)، خُنق في الليلة نفسها تسعة عشر أميرًا، أربعة منهم بالغون (مصطفى وبايزيد وعثمان وعبد الله)؛ وكانت هذه أكبر مجزرة للإخوة في التاريخ العثماني.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["ازدياد نفوذ صفية سلطان بوصفها والدة سلطان", "000bec21"], "d": ["ارتقت صفية سلطان، زوجة مراد الثالث ووالدة محمد الثالث، بجلوس ابنها إلى مكانة حاسمة في سياسة القصر بصفتها والدة سلطان. ووفقًا لموسوعة الإسلام التركية (TDV)، بلغ النفوذ الصادر عن الحريم في هذه الفترة حد التدخل المباشر في شؤون الدولة.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["خروج محمد الثالث بنفسه إلى الحملة بضغط من الإنكشارية", "d3c50656"], "d": ["رغم معارضة الصدر الأعظم داماد إبراهيم باشا، وبضغط من الإنكشارية، خرج محمد الثالث من إسطنبول إلى الحملة في 20 يونيو 1596، وهو أول سلطان يتولى قيادة الجيش بنفسه بعد السلطان سليمان القانوني. ووفقًا لموسوعة الإسلام التركية (TDV)، كان ذلك يعني إحياء تقليد الغزو القديم.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["استمرار وباء الطاعون الذي بدأ في عقد 1570 في التأثير في إسطنبول", "eb4ca37a"], "d": ["وفقًا لمادة الطاعون في موسوعة الإسلام التركية (TDV)، استمر الوباء الذي بدأ في عقد 1570 في أثره حتى أوائل القرن 17، وضرب إسطنبول أولًا ثم الأناضول والبلقان ومصر وشمال أفريقيا. وكانت فترات الوباء تشكّل تهديدًا مزمنًا يقطع حياة القصر والمدينة مرارًا.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["وفاة قره يازيجي عبد الحليم وضعف حركة التمرد", "876ca7a6"], "d": ["توفي قره يازيجي عبد الحليم، الذي انسحب جريحًا بعد هزيمته الثقيلة في سبتلي قرب أبلستين في 12 أغسطس 1601، في سنة 1010 (1602). ووفقًا لموسوعة الإسلام التركية (TDV)، بلغ نبأ وفاته إسطنبول في رمضان 1010 (فبراير-مارس 1602)؛ وتذكر المصادر أن كون موته ناتجًا عن جراحه أم على يد رجاله أمر مختلف فيه.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["الانتهاء الفعلي لتقليد قتل الإخوة", "9046c607"], "d": ["لم يأمر أحمد الأول عند جلوسه على العرش بقتل أخيه الأمير مصطفى، خلافًا للسلاطين السابقين، بل عفا عنه؛ ويُعدّ هذا القرار بداية الأخذ الفعلي بنظام الأكبر والأرشد في الوراثة العثمانية. وتنقل مادة «مصطفى الأول» في موسوعة الإسلام التركية (TDV) أن مصطفى ظل بعد هذا التاريخ يعيش حياة المحفل في القصر. وبذلك وضع هذا التطبيق نهاية فعلية لجرائم الجلوس التي استمرت قرونًا.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["وضع حجر أساس جامع السلطان أحمد", "1683262f"], "d": ["بأمر أحمد الأول، وُضع حجر أساس الجامع الذي سيبنيه المعمار صدفكار محمد آغا، في أت ميداني بحفل. ووفقًا لمادة «جامع السلطان أحمد ومجمعه» في موسوعة الإسلام التركية (TDV)، كان البناء، بوصفه أول جامع سلطاني كبير يُشيَّد مباشرة من الخزينة دون انتصار في فتح، موضع انتقادات في عصره أيضًا. وصُمّم المجمع بحيث يشمل مع الجامع مدرسة وعمارة وضريحًا.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["قتل عثمان الشاب على يد الإنكشارية (الفاجعة العثمانية)", "324f6582"], "d": ["ثار الإنكشارية والسباهية إثر شائعات بأنه يخطط للخروج من إسطنبول بذريعة الحج وحلّ أوجاق الإنكشارية، فخلعوا عثمان الثاني عن العرش وخنقوه في سجون يدي قولة. ووفقًا لمادة «عثمان الثاني» في موسوعة الإسلام التركية (TDV)، كانت هذه الواقعة أول حالة في التاريخ العثماني يُقتل فيها سلطان صراحةً بتمرد عسكري، وأحدثت صدعًا عميقًا في علاقة الأسرة الحاكمة بالجيش. وكانت ساعاته الأخيرة على النحو الآتي: لما لم تُجدِ محاولته اللجوء إلى قصر آغا الإنكشارية علي آغا، أُركب السلطان على فرس، وبحسب تعبير TDV «في حال فظيعة، مكشوف الرأس، مضطرب الثياب»، وسط إهانات شديدة، فسيق أولًا إلى الجامع الأوسط حيث كان مصطفى الأول، ثم بعد ظهر اليوم نفسه إلى يدي قولة؛ وبحسب بعض المؤرخين قُطعت أذنه وأنفه لإثبات موته وعُرضتا على والدة مصطفى الأول. وبعد الواقعة أُعيد مصطفى الأول إلى العرش للمرة الثانية. وقد أخلّت الواقعة المعروفة بـ«الفاجعة العثمانية» (مأساة عثمان) بالتوازن بين القصر والأوجاق إخلالًا دائمًا، وأطلقت جدلًا حول الشرعية سيستمر طوال قرن.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["إعادة مصطفى الأول إلى العرش للمرة الثانية", "34a0b29a"], "d": ["بعد قتل الإنكشارية لعثمان الشاب، أُعيد مصطفى الأول إلى العرش للمرة الثانية، إذ لم يكن في الأسرة الحاكمة عضو ذكر بالغ آخر. ووفقًا لمادة «مصطفى الأول» في موسوعة الإسلام التركية (TDV)، مرت هذه السلطنة الثانية أيضًا، كالأولى، دون أن يتمكن من تسيير شؤون الدولة فعليًا، وبقيت إدارة الدولة في أيدي الوزراء والوالدة سلطان. وانتهت هذه الفترة التي دامت أربعة عشر شهرًا بجلوس مراد الرابع على العرش عام 1623.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["حريق جبالي", "3e42fb08"], "d": ["أتى الحريق الذي اندلع في جبالي وانتشر بسرعة بتأثير الريح على جزء كبير من إسطنبول؛ ووفقًا لمادة «إسطنبول» في موسوعة الإسلام التركية (TDV)، تنقل مصادر العصر أن آلاف البيوت احترقت. وكان ربط الحريق بنسيج البيوت الخشبية وبتدخين التبغ السبب المباشر للحظر الصارم للتبغ والمقاهي الذي سيعلنه مراد الرابع بعد وقت قصير. وكانت الكارثة واحدة فحسب من الحرائق الكبرى المتكررة في إسطنبول ذلك العصر.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["حظر مراد الرابع للتبغ والمقاهي", "5dd71297"], "d": ["بعد حريق جبالي، حظر مراد الرابع تدخين التبغ والمقاهي حرصًا على الأمن ومنعًا للحرائق؛ وطُبقت على المخالفين عقوبات شديدة منها عقوبة الإعدام. ووفقًا لمادة «مراد الرابع» في موسوعة الإسلام التركية (TDV)، انتهج السلطان سياسة انضباط داخلي صارمة بلغت حد أنه كان يجول بنفسه في شوارع المدينة متنكرًا لمراقبة تطبيق الحظر. وتُعدّ هذه التدابير القاسية جزءًا من سعي مراد الرابع إلى إعادة تأسيس السلطة المركزية.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["وباء الطاعون في إسطنبول", "f33f58c5"], "d": ["هزّ إسطنبول في عهد مراد الرابع وباء طاعون شديد أصاب جزءًا مهمًا من السكان؛ وتعطلت التجارة داخل المدينة والحياة اليومية أشهرًا. وتسجل مادة «إسطنبول» في موسوعة الإسلام التركية (TDV) أن الأوبئة المتكررة في القرن 17 أثرت تأثيرًا جسيمًا في التوازن السكاني للمدينة. وفي فترة الوباء انتقل القصر والطبقة النخبوية إلى البساتين والأجنحة خارج المدينة لبعض الوقت.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["طيران هزارفن أحمد جلبي بالجناحين (رواية)", "df474c04"], "d": ["وفقًا للرواية التي ينقلها أوليا جلبي، تمكن هزارفن أحمد جلبي بجناحين صنعهما بنفسه من القفز من برج غلطة والانزلاق حتى أسكدار؛ ومع أن ثبوته التاريخي موضع جدل، فقد صار رمزًا للخيال التقني. وقد نفى السلطان هزارفن، الذي كان قد كافأه في البداية، إلى الجزائر لاحقًا بسبب الصدى الذي أحدثته الواقعة.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["اكتساب جنجي خوجه حسين أفندي النفوذ في القصر", "41d21572"], "d": ["استُدعي الراقي حسين أفندي إلى القصر لمعالجة الاضطرابات النفسية لدى السلطان إبراهيم، فكسب ثقة السلطان في وقت قصير وارتقى حتى منصب قاضي عسكر الأناضول. ووفقًا لمادة «حسين أفندي، جنجي خوجه» في موسوعة الإسلام التركية (TDV)، استخدم هذا النفوذ لجمع الثروة والتدخل في الأحداث السياسية في عصره. وبعد وفاة إبراهيم عُزل من جميع مناصبه وأُعدم عام 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["إعدام كمانكش مصطفى باشا", "0ecc8030"], "d": ["خُنق كمانكش مصطفى باشا، الذي تولى الصدارة العظمى منذ عهد مراد الرابع وحقق للخزينة فائضًا مهمًا بإصلاحاته المالية، وأُعدم إثر تأثير خصومه داخل القصر في إبراهيم واتهامه بإثارة تمرد للإنكشارية. ووفقًا لمادة «كمانكش مصطفى باشا» في موسوعة الإسلام التركية (TDV)، نُفّذ إعدامه في 21 ذي القعدة 1053 / 31 يناير 1644: خنقه الجلاد قره علي في سوق خوجه باشا، ودُفن في ضريحه الذي أنشأه لنفسه في جارشي قابي. ويُذكر موته مثالًا لافتًا على عدم الاستقرار في منصب الصدارة العظمى في ذلك العصر، وقد أنهى فترة إصلاح صارمة قصيرة.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["قرار الديوان بحملة كريت وخروج الأسطول", "9076827e"], "d": ["تقرر في ديوان همايون فتح حملة واسعة النطاق على جزيرة كريت التابعة للبندقية، وتحرك الأسطول العثماني بقيادة قبطان باشا من إسطنبول نحو كريت. ووفقًا لمادة «كريت» في موسوعة الإسلام التركية (TDV)، شكّل هذا القرار البداية السياسية لمرحلة طويلة من الحصار والحرب ستدوم نحو خمس وعشرين سنة. وكان فتح الحملة قد أثار جدلًا واسعًا بين رجال الدولة بوصفه أكبر مبادرة في السياسة الخارجية في عهد إبراهيم.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["جلوس محمد الرابع على العرش في السابعة من عمره", "a197a3bc"], "d": ["عقب خلع إبراهيم مباشرة، أُجلس ابنه محمد، وهو في السابعة من عمره، على العرش، فصار سلطانًا بلقب محمد الرابع. ووفقًا لمادة «محمد الرابع» في موسوعة الإسلام التركية (TDV)، أدى الجلوس على العرش في هذه السن المبكرة إلى احتدام الصراع على النفوذ داخل القصر بين جدته كوسم سلطان وأمه تورهان سلطان. وسينتهي هذا الصراع على السلطة بقتل كوسم سلطان عام 1651.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["إصلاح الميزانية المتوازنة على يد طرخونجو أحمد باشا", "376fc7f2"], "d": ["طبّق الصدر الأعظم طرخونجو أحمد باشا، للتغلب على الأزمة المالية التي سببتها سنوات الحرب الطويلة، برنامج تقشف صارمًا شمل نفقات القصر أيضًا، وأعد أول ميزانية متوازنة معروفة في التاريخ العثماني (لائحة طرخونجو). ووفقًا لمادة «طرخونجو أحمد باشا» في موسوعة الإسلام التركية (TDV)، حقق هذا الإصلاح فائضًا مهمًا للخزينة، لكنه أثار استياءً واسعًا في أوساط القصر والبيروقراطية العليا. وسيفضي هذا الاستياء بعد عام إلى إعدامه.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["واقعة الجنار (الوقعة الواقواقية)", "4c6ed90f"], "d": ["وفقًا لمادة «واقعة الجنار» في موسوعة الإسلام التركية (TDV)، ثار الإنكشارية والسباهية العائدون من حملة كريت دون أن يتقاضوا رواتبهم في إسطنبول، وطالبوا بإعدام رجال الدولة الذين اتهموهم بالفساد. ولم يُقبل اقتراح الصدر الأعظم زورنازن مصطفى باشا بالمصادرة والنفي؛ فأُعدم ثلاثة مسؤولين أولًا، ثم نحو ثلاثين من رجال الدولة، وعُلّقت جثثهم على أشجار الجنار في ميدان السلطان أحمد. ولذلك عُرفت الواقعة باسم واقعة الجنار.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["تعيين كوبريلي محمد باشا صدرًا أعظم بقبول مشروط", "3a6b7f8f"], "d": ["وفقًا لمادة كوبريلي محمد باشا في موسوعة الإسلام التركية (TDV)، لم يتسلم كوبريلي محمد باشا، وقد قارب الثمانين من العمر، الختم إلا بعد أن حمل الوالدة تورهان سلطان ومحمدًا الرابع على قبول الشروط الثقيلة التي قدمها — وهي عدم التدخل في تعييناته وعدم تصديق ما يُقال ضده. وباشر مهامه في 26 ذي القعدة 1066 خلفًا لبويون أغري محمد باشا، وشرع في إعادة تأسيس انضباط الدولة بشدة.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["قمع كوبريلي محمد باشا لحركة القاضي زاديين", "5ec3ce84"], "d": ["وفقًا لمادة «القاضي زاديون» في موسوعة الإسلام التركية (TDV)، تناول كوبريلي محمد باشا فور تسلمه مهامه الصراع الديني بين حلقة قاضي زاده محمد أفندي وأهل الطريقة. وبعد استشارة العلماء، صدر فرمان بإعدام زعماء الحركة أوستوفاني محمد أفندي وترك أحمد وديوانه مصطفى، غير أن هذه العقوبة حُوّلت إلى النفي، وأُرسل الثلاثة إلى قبرص؛ وبذلك انتهت المرحلة الثانية من الحركة.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["حريق كبير في إسطنبول: احتراق آغا قابي", "b9253b66"], "d": ["وفقًا لمادة آغا قابي في موسوعة الإسلام التركية (TDV)، احترق آغا قابي، المقر الرسمي لآغا الإنكشارية، احتراقًا تامًا في الحريق الكبير الذي اندلع في يوليو 1660 في عهد محمد الرابع، ثم أُعيد بناؤه. وكان هذا الحريق من حرائق المدينة الكبرى التي ضربت إسطنبول ذلك العصر مرارًا.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["تعيين كوبريلي زاده فاضل أحمد باشا صدرًا أعظم", "c1999b5c"], "d": ["وفقًا لمادة كوبريلي زاده فاضل أحمد باشا في موسوعة الإسلام التركية (TDV)، عُيّن في الصدارة العظمى في 8 ربيع الأول 1072 (1 نوفمبر 1661) إثر وفاة أبيه كوبريلي محمد باشا. وأنشأ فاضل أحمد باشا، المعروف، خلافًا لأبيه، بلين طبعه وتدينه ورعايته للعلماء والفنانين، خلال صدارته التي تجاوزت خمس عشرة سنة، مكتبات ومؤسسات خيرية في إسطنبول وفي الأراضي المفتوحة.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["تعيين وانلي محمد أفندي واعظًا في الجامع الجديد ومعلمًا للسلطان", "7ea6aaae"], "d": ["وفقًا لمادة محمد أفندي، واني في موسوعة الإسلام التركية (TDV)، استُدعي واني محمد أفندي إلى إسطنبول عند تولي كوبريلي زاده فاضل أحمد باشا الصدارة العظمى، وقُدّم إلى محمد الرابع، فكسب اهتمام السلطان القريب في وقت قصير. وفي عام 1665 عُيّن واعظًا في الجامع الجديد ومعلمًا للسلطان، فصار من أكثر رجال الدين نفوذًا في القصر.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["تعيين قره مصطفى باشا المرزيفوني صدرًا أعظم", "3d1e836c"], "d": ["وفقًا لمادة مرزيفونلو قره مصطفى باشا في موسوعة الإسلام التركية (TDV)، عُيّن في الصدارة العظمى في 28 شعبان 1087 (5 نوفمبر 1676) إثر وفاة فاضل أحمد باشا. وصار المرزيفوني، صهر أسرة كوبريلي وتلميذها وصاحب الخبرة الطويلة في إدارة الدولة، من أقوى صدور محمد الرابع العظام وأكثرهم نفوذًا.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["وفاة وانلي محمد أفندي في المنفى", "cda714aa"], "d": ["وفقًا لمادة محمد أفندي، واني في موسوعة الإسلام التركية (TDV)، أُسقط واني محمد أفندي، الذي يُعدّ من أبرز من حملوا السلطان على قبول حملة فيينا، من مكانته بضغط الرأي العام بعد انتهاء الحملة بهزيمة، ونُفي إلى بلدة كستل في بورصة. وتوفي فيها في 14 ذي القعدة 1096 (12 أكتوبر 1685)، ودُفن عند مدخل الجامع الذي أنشأه.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["تعيين كوبريلي زاده فاضل مصطفى باشا صدرًا أعظم وإصلاحاته المالية", "b048570e"], "d": ["وفقًا لمادة كوبريلي زاده فاضل مصطفى باشا في موسوعة الإسلام التركية (TDV)، أعاد فاضل مصطفى باشا، الذي عُيّن في الصدارة العظمى في 11 محرم 1101 (25 أكتوبر 1689)، تنظيم أسلوب جباية الجزية وفق الأسس الشرعية، وكافح تضخم المانغير، وقوّى الخزينة بتحويل موارد من مؤسسات القصر. كما عزز الإدارة في الولايات بموظفين موثوقين وأقام مجالس محلية شبيهة بالديوان المركزي.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["بدء العمل بنظام المالكانة", "316b8426"], "d": ["وفقًا لمادة المالكانة في موسوعة الإسلام التركية (TDV)، أدخل ازدياد نفقات الحرب في الربع الأخير من القرن 17 وتناقص الإيرادات بسبب خسائر الأراضي الخزينةَ في أزمة مالية شديدة. وفي نظام المالكانة الذي بدأ العمل به عام 1106 (1695) مُنح الملتزمون حق ضريبة ثابتة مدى الحياة، وأُدخل حافز لحماية الإنتاج بدلًا من الاستغلال قصير الأجل.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["جلوس مصطفى الثاني على العرش", "b53656c7"], "d": ["وفقًا لمادة مصطفى الثاني في موسوعة الإسلام التركية (TDV)، أعلن مصطفى الثاني، الذي تولى العرش وهو في الحادية والثلاثين من عمره، سلطنته دون انتظار موافقة الصدر الأعظم وشيخ الإسلام؛ وأُقيم حفل تقليد السيف بعد أيام قليلة في الجامع القديم. وصار السلطان، الذي تولى العرش في فترة استمرت فيها الحروب على جبهات متعددة بعد هزيمة فيينا، آخر سلطان عثماني يخرج بنفسه إلى الحملة.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["تعيين فيض الله أفندي شيخًا للإسلام للمرة الثانية", "1cf14cff"], "d": ["وفقًا لمادة فيض الله أفندي، سيد في موسوعة الإسلام التركية (TDV)، عُيّن في مشيخة الإسلام للمرة الثانية في 11 شوال 1106 (25 مايو 1695) عقب جلوس مصطفى الثاني. وازداد نفوذه على السلطان تدريجيًا خلال فترة هذا المنصب التي دامت أكثر من ثماني سنوات.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["تولية فيض الله أفندي أبناءه المناصب العليا وتراكم ردود الفعل", "a6398280"], "d": ["وفقًا لمادة فيض الله أفندي، سيد في موسوعة الإسلام التركية (TDV)، نال شيخ الإسلام من مصطفى الثاني فرمانًا لا مثيل له بأن يكون ابنه فتح الله أفندي شيخًا للإسلام بعده، ووضع أقاربه في مناصب عليا في سن مبكرة. وأثارت هذه الممارسات استياءً واسعًا بين طبقة العلمية والجيش وأهالي إسطنبول؛ وتضافرت مع شائعات عن نقل العاصمة إلى أدرنة فمهدت الأرضية لوقعة أدرنة عام 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["اندلاع وقعة أدرنة", "5a106458"], "d": ["وفقًا لمادة «وقعة أدرنة» في TDV، بدأت الحركة بتمرد جنود لم يتقاضوا رواتبهم، وسرعان ما تحولت إلى تمرد واسع شارك فيه الإنكشارية وطلبة المدارس والتجار والعامة. وكان الهدف الأساسي للتمرد شيخ الإسلام فيض الله أفندي الذي زُعم أنه يتدخل في شؤون الدولة تدخلًا مفرطًا. وسار جمع يناهز 60.000 شخص من إسطنبول إلى أدرنة.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["صدارة نوشهرلي داماد إبراهيم باشا العظمى", "8d627a6f"], "d": ["وفقًا لمادة «داماد إبراهيم باشا، نوشهرلي» في TDV، عُيّن في منصب الصدارة العظمى في 8 جمادى الآخرة 1130 (9 مايو 1718) أثناء مفاوضات السلام الجارية مع النمسا، وتوجه فور تعيينه إلى المفاوضات التي ستنهي الحرب؛ وبعد شهرين وُقعت معاهدة باساروفيتس (21 يوليو 1718). وبحسب تعبير TDV: «كان يريد الانشغال بالمسائل الاجتماعية والمالية، وكان يتوق إلى عصر سلام ينسي الحروب التي انتهت بالهزيمة منذ سنوات طويلة». وأجرى إصلاحات في المالية فخفض رواتب الجنود وكوّن فائضًا مهمًا في خزينة الدولة. وشكلت صدارته التي ستدوم اثنتي عشرة سنة الإطار السياسي للعهد الذي يحمل اسمه (عصر التوليب).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["تأسيس أوجاق الطلمبجية", "f58b0d97"], "d": ["وفقًا لمادة «الطلمبجي» في TDV، إثر نجاح داود الحقيقي، العائد من حملة المورة عام 1715، في استخدام المضخة في حرائق إسطنبول، كلّفه الصدر الأعظم نوشهرلي داماد إبراهيم باشا بتأسيس أوجاق رسمي لإطفاء الحرائق. وبلغ الأوجاق، الذي أُسس في ثكنة عجمي أوغلان بستة ضباط وخمسين فردًا، 150 فردًا عام 1724 و461 فردًا عام 1755. وبقي داود على رأس الأوجاق حتى وفاته عام 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["استقبال لويس الخامس عشر لمحمد أفندي", "0ff5b174"], "d": ["وفقًا لمادة «يكرمي سكيز جلبي محمد أفندي» في TDV، استقبل ملك فرنسا لويس الخامس عشر السفير رسميًا في قصر التويلري، وقدم هدايا أحمد الثالث ورسالته. وزار خلال إقامته قصور فرساي وتريانون ومارلي والمستشفيات والمراصد والمصانع، وسجل ما رآه برسوم.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["عودة محمد أفندي إلى إسطنبول", "a09a8bba"], "d": ["وفقًا لمادة «يكرمي سكيز جلبي محمد أفندي» في TDV، أثرت ملاحظات السفير العائد من سفارة دامت سنة في باريس في الذوق المعماري لعصر التوليب. وكان عمل ابنه لاحقًا مع إبراهيم متفرقة تمهيدًا لتأسيس أول مطبعة تركية، وهي أدوم إرث للسفارة.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["بناء قصر سعد آباد", "aec9c65e"], "d": ["وفقًا لمادة «سعد آباد» في TDV، أُنشئ على ضفة نهر كاغدخانة مجمع واسع للترفيه والنزهة، مؤلف من قصر وقنوات وسُبُل وأجنحة، مستوحى من العمارة القصرية الفرنسية. وصار سعد آباد، وقد غدا أحب أماكن الترفيه في العصر، خالدًا في أشعار الشاعر نديم. وقد دُمّر المجمع في معظمه أثناء تمرد باترونا خليل عام 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["استيلاء القوات الروسية على دربند: حملة بطرس الأول على بحر قزوين", "c2b269f9"], "d": ["في وقت كانت الدولة الصفوية تنجرف فيه إلى الاضطراب الداخلي بسبب الغزو الأفغاني، خرج القيصر الروسي بطرس الأول في حملة بقصد الاستيلاء على الأراضي الإيرانية على ساحل بحر قزوين؛ وسلّمت مدينة دربند الساحلية نفسها للقوات الروسية دون مقاومة تُذكر. ووفقًا لمادة «دربند» في موسوعة الإسلام التركية (TDV)، كان هذا الاحتلال بداية سيادة روسية مؤقتة ستدوم ثلاث عشرة سنة؛ وتوجهت الدولة العثمانية كذلك، مستفيدة من الاضطراب نفسه، نحو القسم الغربي من القوقاز. وكان الجيش قد نزل من أستراخان بحرًا إلى خليج أغراخان، ثم سار برًا على طول الساحل عبر طرقو؛ واستضاف شمخال طرقو بطرس ودخل في التبعية الروسية.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["إلغاء شمخالية طرقو: الإدارة الروسية المباشرة", "b0f029c6"], "d": ["ثار شمخال طرقو عادل كراي، الذي استضاف بطرس عام 1722 ودخل في التبعية الروسية، في عام 1725؛ فدمّر ييروبكين طرقو في خريف 1725، واعتُقل الشمخال ونُفي في منتصف مايو 1726، وأُلغيت الشمخالية. وبقيت طرقو وما حولها تحت الإدارة الروسية المباشرة حتى معاهدة كنجة عام 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["الإذن لإبراهيم متفرقة بتأسيس مطبعة", "0659dd0a"], "d": ["وفقًا لمادة «إبراهيم متفرقة» في TDV، أُذن بتأسيس أول مطبعة تركية بفرمان من أحمد الثالث وبفتوى من شيخ الإسلام يني شهرلي عبد الله أفندي. وبدأت المطبعة عملها في حي يافوز سليم في إسطنبول. وطبع متفرقة حتى وفاته عام 1747 سبعة عشر كتابًا في ثلاثة وعشرين مجلدًا.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["اكتمال أول كتاب مطبوع: قاموس وانقولي", "684700e8"], "d": ["وفقًا لمادة «إبراهيم متفرقة» في TDV، اكتملت في أوائل عام 1729 الترجمة التركية لـ«صحاح الجوهري» (قاموس وانقولي)، وهي أول أعمال المطبعة. وكان هذا أول كتاب يُطبع بالحروف العربية في الأراضي العثمانية، ويُعدّ بداية تاريخ الطباعة التركية.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["إعدام نوشهرلي داماد إبراهيم باشا", "50c64341"], "d": ["وفقًا لمادة «داماد إبراهيم باشا، نوشهرلي» في TDV، سُحبت جثة الصدر الأعظم، الذي قُتل في القصر أثناء تمرد باترونا خليل، في شوارع إسطنبول ثم تُركت قرب سبيل أحمد الثالث في ميدان السلطان أحمد. وانتهت بذلك صدارته التي دامت اثنتي عشرة سنة وعصر التوليب نهاية دموية.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["تنازل أحمد الثالث عن العرش وجلوس محمود الأول", "a43f5d40"], "d": ["وفقًا لمادة «محمود الأول» في TDV، تنازل أحمد الثالث عن العرش بعد أن أخذ ضمانًا لنفسه ولأولاده أمام ضغط الثوار، وأجلس بنفسه ابن أخيه الأمير محمود على العرش. وشرع محمود الأول، الذي جلس على العرش بنصيحة عمه «خذ شؤون الدولة بيدك ولا تثق بأحد»، أول ما شرع في كسر نفوذ جماعة الثوار التي أجلسته على العرش.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["إصلاح أحمد باشا القومباراجي لأوجاق المدفعية", "ea3a7c64"], "d": ["وفقًا لمادة «القومباراجي» في TDV، شرع الضابط أحمد باشا، الفرنسي الأصل الذي اعتنق الإسلام، في عهد الصدر الأعظم حكيم أوغلو علي باشا في إصلاح تنظيم القومباراجية ذوي العلوفة على النمط الأوروبي. وأقام بنية جديدة تتبع الصدر الأعظم مباشرة، من 601 شخص، منهم 300 برواتب و301 بتيمار. وأنتج بتقنية العصر 100 مدفع هاون و50.000 قذيفة.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["تأسيس الهندسخانة (النموذج الأول لمدرسة الهندسة)", "a77ed1f3"], "d": ["وفقًا لمادة «محمود الأول» في TDV، أسس أحمد باشا القومباراجي في أسكدار الهندسخانة، التي تُسمى أيضًا القومبارخانة، وقدم تدريبًا عسكريًا قائمًا على الرياضيات والهندسة للطلاب الذين اختارهم من بين خدم القصر والبستانجية. وتُعدّ هذه المؤسسة النموذج الأول لمدارس الهندسة التي ستتطور في العهد اللاحق.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["معاهدة كنجة: إعادة دربند وباكو إلى إيران", "ff19d531"], "d": ["أعادت روسيا، التي كانت تبحث عن تحالف مع إيران في وجه التهديد العثماني، بموجب معاهدة كنجة مدن ساحل بحر قزوين التي ظلت في يدها ثلاث عشرة سنة إلى إيران بقيادة نادر خان (الذي لم يكن قد اتخذ لقب شاه بعد). ووفقًا لمادة «دربند» في موسوعة الإسلام التركية (TDV)، كان هذا الانسحاب نتيجة لعدم رغبة روسيا في قتال على جبهتين في الجنوب (العثمانية والإيرانية) في آن واحد، وعزز مكانة نادر العسكرية التي مهدت طريق جلوسه على العرش بعد بضع سنوات. وعادت طرقي (طرقو) الخاضعة للإدارة الروسية هي الأخرى إلى الجانب الإيراني بهذا الانسحاب (يُستعمل في الخريطة يوم كنجة).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["جلوس نادر شاه على العرش في سهل موغان: النهاية الفعلية للأسرة الصفوية", "4f640979"], "d": ["وفقًا لمادة «نادر شاه» في موسوعة الإسلام التركية (TDV)، ألحّ مجلس القورولتاي المنعقد في سهل موغان، المؤلف من نحو عشرين ألف شخص، على أن يتولى نادر رئاسة إيران؛ فقبل نادر هذا العرض بشرط التخلي عن الفهم الشيعي المفرط الذي تسبب في الحروب بين الصفويين والعثمانيين واعتماد المذهب الجعفري المعتدل، وجلس على العرش بلقب نادر شاه في 24 شوال 1148 (8 مارس 1736). وكان ذلك يعني النهاية الفعلية للأسرة الصفوية التي دامت قرنين وتأسيس الأسرة الأفشارية.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["بدء وباء الطاعون في إسطنبول", "9fa82b56"], "d": ["وفقًا لمادة «الطاعون» في TDV، ضرب وباء الطاعون، الذي كان مؤثرًا في الجغرافيا الإسلامية بين عامي 1739 و1743، إسطنبول أيضًا في هذه الفترة. وتشير المادة إلى أن أوبئة القرن 18 كانت أخف نسبيًا من أوبئة القرون السابقة. وتُعدّ سنوات 1713 و1719 و1728-1729 و1759-1765 أيضًا من فترات الوباء.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["حريق خوجه باشا", "321c7d0d"], "d": ["وفقًا لمادة «جامع فاطمة سلطان» في TDV، دمّر حريق خوجه باشا، الذي اندلع ليلًا، الباب العالي وما حوله؛ ويُقدَّر أن جامع فاطمة سلطان في المنطقة تضرر من هذا الحريق أيضًا. وقد تسببت هذه الكارثة، وهي من الحرائق الكبرى التي ضربت إسطنبول في عهد عثمان الثالث، في دمار شديد في مركز المدينة التجاري والإداري.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["صدارة كوجه راغب محمد باشا العظمى", "a1846910"], "d": ["عُيّن راغب باشا، المعروف بكونه شاعرًا ودبلوماسيًا، في منصب الصدارة العظمى على يد عثمان الثالث (واصل مهامه بعد وفاة عثمان الثالث في أكتوبر 1757 ونال ختمًا جديدًا من مصطفى الثالث). واتبع سياسة خارجية متوازنة أبقت الدولة العثمانية بمنأى عن النزاعات في أوروبا أثناء حرب السنوات السبع. وأولى أهمية للأنشطة الثقافية، كتأسيس المكتبات، طوال صدارته التي ستدوم ست سنوات.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["وفاة راغب باشا", "6bc19323"], "d": ["توفي راغب باشا بعد صدارة دامت ست سنوات. وبوفاته انتهت أطول صدارة عظمى في عهد مصطفى الثالث نفَسًا وأكثرها توازنًا.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["زلزال إسطنبول الكبير وانهيار جامع الفاتح", "2475b4dc"], "d": ["وفقًا لمادة «جامع الفاتح ومجمعه» في TDV، انهارت القبة الرئيسية للجامع انهيارًا تامًا في الزلزال الكبير عام 1766، وتضررت جدرانه ضررًا لا يمكن إصلاحه. وبأمر مصطفى الثالث بدأت عام 1767 إعادة البناء تحت إشراف المعماريين صاريم إبراهيم أفندي وعزت محمد بك، واكتملت عام 1771 بتصميم جديد يختلف عن المخطط القديم.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["تجربة مدرسة مدفعية قصيرة العمر بقيادة البارون دو توت", "4192260c"], "d": ["وفقًا لمادة «مهندسخانة بحري همايون» في TDV، كشفت الإخفاقات في الحرب العثمانية الروسية عام 1768 الحاجة إلى التدريب العسكري التقني؛ وبدأت مدرسة المدفعية قصيرة العمر، التي افتُتحت بمساهمة الضابط الفرنسي البارون دو توت، عملها في أكتوبر 1772 لكنها ظلت عديمة الأثر. وتُعدّ هذه التجربة طليعة مهندسخانة بحري همايون التي ستؤسس عام 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["جلوس سليم الثالث على العرش", "00d046d9"], "d": ["إثر وفاة عبد الحميد الأول، تولى ابن أخيه سليم الثالث العرش. ووفقًا لمادة سليم الثالث في موسوعة الإسلام التركية (TDV)، بدأ السلطان الجديد، الذي كان يهتم منذ أن كان أميرًا بإصلاح الجيوش الأوروبية، يعدّ برنامج تجديد جذري بعد جلوسه بوقت قصير. وسيُعرف هذا البرنامج بعد بضع سنوات باسم النظام الجديد.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["بدء إعداد برنامج إصلاح النظام الجديد", "eff78a68"], "d": ["أعدّ سليم الثالث برنامج تجديد شامل وفق اللوائح التي طلبها من رجال الدولة والخبراء الأجانب. ووفقًا لمادة «النظام الجديد» في موسوعة الإسلام التركية (TDV)، لم يقتصر هذا البرنامج على تأسيس جيش جديد، بل تحول إلى حركة إصلاح واسعة شملت المالية وإدارة الولايات والدبلوماسية. وسيجد البرنامج في السنوات الخمس عشرة التالية مؤيدين ومعارضين.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["تأسيس سفارات دائمة في العواصم الأوروبية", "2e9dc8a1"], "d": ["أرسل سليم الثالث، لأول مرة في تاريخ الدولة العثمانية، سفراء دائمين للعمل المستمر في المراكز الأوروبية الكبرى. ووفقًا لمادة «السفير» في موسوعة الإسلام التركية (TDV)، أعطت هذه الخطوة الدبلوماسية العثمانية، التي كانت تُدار حتى ذلك الوقت بوفود مؤقتة لمرة واحدة فقط، تنظيمًا دائمًا. وكانت المهمة الرئيسية للسفارات الجديدة إبلاغ إسطنبول بانتظام بالتطورات السياسية والعسكرية في أوروبا.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["تأسيس خزينة الإيراد الجديد", "ae5c8ce2"], "d": ["أُسست خزينة منفصلة لتغطية نفقات جيش النظام الجديد وبرنامج الإصلاح. ووفقًا لمادة «الأسهم» في موسوعة الإسلام التركية (TDV)، كان من إيرادات الخزينة الجديدة تشغيل بعض المقاطعات مباشرة بيد الدولة وإخضاع بيع الأسهم للرقابة. وكان هذا الترتيب محاولة لخلق مورد جديد خارج نظام المالية التقليدي.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["اندلاع تمرد قاباقجي مصطفى", "b98eee17"], "d": ["انفجر الاستياء المتراكم ضد النظام الجديد بتمرد جنود اليماك بقيادة قاباقجي مصطفى. ووفقًا لمادة «تمرد قاباقجي» في موسوعة الإسلام التركية (TDV)، سيطر الثوار على إسطنبول في وقت قصير وطالبوا برؤوس رجال الدولة المؤيدين للنظام الجديد. وانتهى التمرد في غضون أيام بخلع سليم الثالث عن العرش.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["خلع سليم الثالث عن العرش", "ff2c30ec"], "d": ["خُلع سليم الثالث عن العرش بفتوى من شيخ الإسلام تحت ضغط تمرد قاباقجي مصطفى. ووفقًا لمادة سليم الثالث في موسوعة الإسلام التركية (TDV)، كان هذا القرار اللحظة التي انتهت فيها فعليًا مرحلة الإصلاح التي دامت ثماني عشرة سنة؛ وأُلغي جيش النظام الجديد أيضًا في وقت قصير. وبدأ احتجاز سليم في قصر طوب قابي.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["جلوس مصطفى الرابع على العرش", "8f1ac86c"], "d": ["أُعلن ابن أخي سليم الثالث، مصطفى الرابع، سلطانًا فور خلعه عن العرش. ووفقًا لمادة مصطفى الرابع في موسوعة الإسلام التركية (TDV)، بدأ السلطان الجديد سلطنته تحت تأثير الأوساط المعادية للنظام الجديد التي دعمت التمرد. وكانت هذه الفترة القصيرة مرحلة من عدم الاستقرار ضعفت فيها السلطة المركزية ضعفًا شديدًا.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["دخول علمدار مصطفى باشا إسطنبول بجيشه", "0cad3dea"], "d": ["جاء أعيان روسجق علمدار مصطفى باشا بجيشه إلى أطراف إسطنبول بقصد إعادة سليم الثالث إلى العرش. ووفقًا لمادة علمدار مصطفى باشا في موسوعة الإسلام التركية (TDV)، استقبله مصطفى الرابع بنفسه عند دخوله المدينة؛ لكن ميزان القوى داخل القصر سيتغير تمامًا في غضون أيام. وأطلق هذا الدخول سلسلة من الأحداث انتهت بوفاة سليم وبجلوس جديد على العرش.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["مقتل سليم الثالث", "e452f5f6"], "d": ["في اليوم الذي استولى فيه علمدار مصطفى باشا على الباب العالي، قُتل سليم الثالث في القصر بأمر مصطفى الرابع. ووفقًا لمادة سليم الثالث في موسوعة الإسلام التركية (TDV)، كان ذلك قرارًا اتُّخذ لمنع محاولة إعادة سلطان مخلوع إلى العرش. وأفضت وفاة سليم، في اليوم نفسه، إلى جلوس محمود.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["جلوس محمود الثاني على العرش", "661c1974"], "d": ["بعد قتل سليم الثالث، جلس محمود، وقد بقي العضو الذكر الوحيد في الأسرة الحاكمة، على العرش بدعم من علمدار مصطفى باشا. ووفقًا لمادة محمود الثاني في موسوعة الإسلام التركية (TDV)، أمضى السلطان الجديد الأشهر الأولى من سلطنته تحت وصاية علمدار الذي أجلسه على العرش، ساعيًا إلى إعادة إقامة التوازن بين الأعيان والمركز. وكانت هذه الفترة بداية مسيرة إصلاح جذري دامت عشرين سنة تالية.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["تأسيس جيش السكبان الجديد", "6f9eb5e4"], "d": ["أنشأ علمدار مصطفى باشا جيشًا جديدًا مجهزًا على الطريقة الأوروبية بدلًا من النظام الجديد الملغى. ووفقًا لمادة «السكبان الجديد» في موسوعة الإسلام التركية (TDV)، عدّ الإنكشارية هذه القوة المؤلفة من ثلاثة أفواج تهديدًا مباشرًا لهم، وقُضي عليها في تمرد للإنكشارية بعد أشهر قليلة فقط من تأسيسها.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["سقوط إبراييل — أول ثغرة كبرى في خط الدانوب", "ee519321"], "d": ["في الحرب الروسية التي بدأت عام 1806، حوصرت قلعة إبراييل على الضفة الشمالية للدانوب وقُصفت بالمدافع من القوات الروسية بقيادة الكونت كامينسكي. وكان في داخلها 4100 مشاة و1100 فارس و260 مدفعًا؛ وسلّمت القلعة للجنرال إيسن بسبب نقص الأقوات. وبذلك انفتح الطرف الشمالي من خط الدفاع على الدانوب.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["تسليم روسجق — الضفة الجنوبية للدانوب تخرج من اليد أيضًا", "084062e8"], "d": ["قاومت روسجق حصارًا طويلًا ودمويًا من الجيش الروسي بقيادة الكونت كامينسكي؛ وسلّمت بشرط أن يغادر الحامية والسكان المدنيون المدينة آمنين. وحوّل سقوط أقوى مدينة قلعة على الضفة الجنوبية للدانوب مجرى الحرب لصالح روسيا.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["تأسيس أوجاق الأشكنجية", "67c56759"], "d": ["أسس محمود الثاني وحدة جديدة تتدرب على الطريقة الأوروبية من جنود اختيروا من داخل أوجاق الإنكشارية. ووفقًا لمادة «أوجاق الأشكنجية» في موسوعة الإسلام التركية (TDV)، بدأت الوحدة التدريب في 12 يونيو 1826، لكن الإنكشارية رأوا في ذلك نهاية أوجاقهم. وأنهى التمرد الذي اندلع بعد ثلاثة أيام عمر أوجاق الأشكنجية القصير أيضًا.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["تأسيس العساكر المنصورة المحمدية", "14b84a7e"], "d": ["فور إلغاء أوجاق الإنكشارية، أسس محمود الثاني بدلًا منه جيشًا جديدًا نظاميًا مدربًا على الطريقة الأوروبية. ووفقًا لمادة «العساكر المنصورة المحمدية» في موسوعة الإسلام التركية (TDV)، صار هذا الجيش مؤسسة دائمة، خلافًا للمحاولات السابقة، بنظام الرتب وبرنامج التدريب ونظام الرواتب. وسيتحول الجيش في السنوات التالية إلى الجيش النظامي في عهد التنظيمات.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["إغلاق الطريقة البكتاشية", "f7d9a367"], "d": ["بالتزامن مع إلغاء أوجاق الإنكشارية، حُظرت كذلك الطريقة البكتاشية المعروفة بصلاتها الدينية بالأوجاق. ووفقًا لمادة «البكتاشية» في موسوعة الإسلام التركية (TDV)، أُعدم بعض شيوخ التكايا الصغيرة، ونُفي شيخ درگاه حاجي بكتاش إلى أماسيا، وسُلّمت التكايا إلى إدارة النقشبندية. وواصلت الطريقة تنظيمها سرًا رغم هذه الضربة الثقيلة.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["حادثة المروحة — ذريعة الاحتلال", "e949001e"], "d": ["في مفاوضات توترت بسبب عدم سداد دين الحبوب القديم المستحق على فرنسا للجزائر، ضرب الداي حسين القنصل الفرنسي دوفال بالمروحة التي في يده. وجُعلت هذه الحادثة، التي نشأت عن خلاف حول دين مستحق، ذريعةً رسمية للاحتلال الذي سيبدأ بعد ثلاث سنوات.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["الحصار البحري الفرنسي لسواحل الجزائر — حصار دام ثلاث سنوات", "d0ba97a5"], "d": ["بعد حادثة المروحة ضربت فرنسا حصارًا على السواحل الجزائرية. واستمر الحصار ثلاث سنوات؛ وجُففت موارد الأوجاق من التجارة البحرية ومصادر الدخل، وتآكلت قدرته على المقاومة قبل أن يبدأ الاحتلال.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["معاهدة تركمانجاي: انتقال إيروان وطالش إلى روسيا", "abffcfdb"], "d": ["لما انتهت الحرب الروسية الإيرانية في 1826-1828 بهزيمة ثقيلة لإيران، تُركت بموجب المعاهدة الموقعة في تركمانجاي خانيتا إيروان ونخجوان ومنطقة طالش على ساحل بحر قزوين (لنكران وأستارا) لروسيا؛ وفُرض فضلًا عن ذلك تعويض حرب ثقيل. ووفقًا لمادة «إيروان» في موسوعة الإسلام التركية (TDV)، هذه الخسارة هي اللحظة التي رُسمت فيها الحدود الروسية الإيرانية في القوقاز بشكل سيبقى ساريًا إلى حد كبير حتى اليوم، وقد أطلقت كذلك هجرة السكان الأرمن إلى إيروان.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["السقوط الثاني لإبراييل — القيصر نيقولا أمام القلعة", "eb6a8741"], "d": ["حوصرت إبراييل، التي أُعيدت إلى العثمانيين عام 1812 وأُعيد تحصينها في 1817-1818، في أبريل وفيها 4000 حارس و278 مدفعًا. وأقام قائدها أبو بكر باشا خط دفاع جديدًا؛ وجاء القيصر نيقولا الأول بنفسه إلى أمام القلعة في أواخر مايو. وتعرضت المدينة للاحتلال الروسي، لكنها ستُعاد بمعاهدة أدرنة وتُترك لإمارة الأفلاق.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["إعلان الطربوش غطاء الرأس الرسمي", "f55be4eb"], "d": ["أجرى محمود الثاني تغييرًا جذريًا في لباس الموظفين والجنود، فأعلن الطربوش غطاء الرأس الرسمي بدلًا من العمامة. ووفقًا لمادة «الطربوش» في موسوعة الإسلام التركية (TDV)، أُعلن هذا القرار بخط همايوني وطُبق مع الإصلاحات ذات الطابع الغربي للعساكر المنصورة المحمدية. وكان التغيير يعني أيضًا إنهاء التسلسل الهرمي التقليدي للباس.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["التخلي عن أخسخة لروسيا — مركز إيالة جلدير يخرج من اليد", "e2e00b2a"], "d": ["أخسخة، التي كانت تحت الإدارة العثمانية منذ حرب جلدير عام 1578 ومركز إيالة جلدير، تُركت لروسيا بمعاهدة أدرنة الموقعة في ختام حرب 1828-1829. وخلّف خروج المدينة من اليد حزنًا عميقًا بين الناس وصار موضوعًا لكثير من المراثي.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["إنزال سيدي فرج — الجيش الفرنسي على أرض الجزائر", "33327553"], "d": ["بعد حصار دام ثلاث سنوات، أنزل جيش الإنزال الفرنسي بقيادة الكونت دي بورمون جنوده في خليج سيدي فرج في غرب الجزائر. وكسرت القوات الزاحفة نحو المدينة خط الدفاع في ثلاثة أسابيع؛ وسقطت في 4 يوليو قلعة الإمبراطور المشرفة على المدينة، وفي اليوم التالي استسلم الداي حسين.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["نفي الداي حسين — النهاية الفعلية لأوجاق الجزائر", "e122403b"], "d": ["بموجب شروط الاستسلام، أُخرج آخر دايات الجزائر، حسين، من المدينة مع أسرته وخزينته وأُرسل إلى نابولي. وبذلك انتهت إدارة الأوجاق الذي ارتبط بسليم الثاني عام 1519 وكان طوال ثلاثمئة سنة أقوى قاعدة بحرية عثمانية في البحر المتوسط.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["انسحاب الجيش الروسي من الأفلاق والبغدان — نهاية احتلال دام ست سنوات", "efdb0275"], "d": ["في الحرب العثمانية الروسية 1828-1829 احتل الروس الأفلاق والبغدان، ولم ينسحبوا بعد معاهدة أدرنة أيضًا إلى أن يُدفع تعويض الحرب. ولما خُفض التعويض إلى خمسة ملايين في يناير 1834، أخلت القوات الروسية الإمارتين، وعُيّن في الإمارتين وُلاة جدد. وعادت التبعية العثمانية على الورق، لكن روسيا حافظت على النفوذ الذي أقامته بالنظام الأساسي (Reglement Organique).", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["تأسيس تنظيم رديف العساكر المنصورة", "15947493"], "d": ["أُسس تنظيم الرديف قوةً احتياطية تدعم العساكر المنصورة المحمدية، بنظامنامة مؤرخة في 8 يوليو 1834. ووفقًا لمادة «الرديف» في موسوعة الإسلام التركية (TDV)، شُكلت في أقضية الولايات، تحت إشراف السرعسكر قوجه خسرو باشا، طوابير من نحو ألف وأربعمئة فرد لكل منها. وصُمّم التنظيم بحيث يدعم الأمن المحلي أيضًا دون أن يُستدعى للخدمة الدائمة.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["تأسيس نظارة الخارجية", "750c6c7d"], "d": ["ألغى محمود الثاني منصب رئيس الكتّاب الذي كان يدير الشؤون الخارجية وأسس بدلًا منه نظارة الخارجية. ووفقًا لمادة «نظارة الخارجية» في موسوعة الإسلام التركية (TDV)، عُيّن محمد عاكف باشا في أول وزارة لهذه النظارة، وبدأ التنظيم عمله في قصر رفعت بك سفير فيينا. وكان هذا الترتيب بداية إدارة السياسة الخارجية العثمانية على أساس الوزارة الحديثة.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["تأسيس مجلس الأحكام العدلية الأعلى", "69db056e"], "d": ["أسس محمود الثاني مجلس الأحكام العدلية الأعلى مجلسًا رفيع المستوى تُناقش فيه القوانين والنظم التي ستُعد. ووفقًا لمادة «مجلس والا أحكام عدلية» في موسوعة الإسلام التركية (TDV)، بدأ المجلس عمله فعليًا في 31 مارس 1838، وأُعدّت تقريبًا جميع إصلاحات التنظيمات اللاحقة وروقبت عبر هذا المجلس. وصارت المؤسسة من أهم مراكز البيروقراطية العثمانية الحديثة.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["غارة سينوب", "5947e93f"], "d": ["شن الأسطول الروسي في البحر الأسود، بقيادة الأميرال ناخيموف، غارة على الأسطول العثماني الراسي في ميناء سينوب دون إعلان حرب؛ فغرقت اثنتا عشرة سفينة، واستُشهد أكثر من ألفي جندي، وأُسر قائد الأسطول عثمان باشا. ووفقًا لمادة «سينوب» في موسوعة الإسلام التركية (TDV)، احترقت في الغارة في المدينة أيضًا سبعة مساجد ومدرستان و247 بيتًا و170 دكانًا، وقُتل من المدنيين خمسة مسلمين وستة عشر مسيحيًا. وكانت الواقعة، التي دوّت في الرأي العام الأوروبي بوصفها «مأساة سينوب»، المحرّك المباشر لدخول إنجلترا وفرنسا الحرب في صف العثمانيين بعد أشهر قليلة.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["صدور صحيفة تصوير أفكار", "506c98e2"], "d": ["بدأت صحيفة تصوير أفكار التي أصدرها شناسي بالصدور رابعَ صحيفة تركية بعد تقويم وقائع وجريدة حوادث وترجمان أحوال. ووفقًا لمادة «تصوير أفكار» في TDV، صارت الصحيفة في عهد نامق كمال، الذي تولى رئاسة التحرير لاحقًا، لسان حركة العثمانيين الجدد.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["تأسيس جمعية العثمانيين الجدد", "335fb02d"], "d": ["تنظّم المثقفون العثمانيون الذين فروا إلى أوروبا بقيادة مصطفى فاضل باشا باسم تركيا الفتاة بنظام داخلي من ثلاث عشرة مادة. ووفقًا لمادة «جمعية العثمانيين الجدد» في TDV، نشرت المجموعة مطلب الحكم الدستوري بإصدار صحف مثل «المخبر» و«الحرية» في باريس ولندن وجنيف.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["تأسيس مجلس شورى الدولة", "b863b306"], "d": ["قُسّم مجلس الأحكام العدلية إلى قسمين، فأُسس شورى الدولة الذي يتولى الشؤون الإدارية وديوان الأحكام العدلية الذي ينظر في الشؤون القضائية. ووفقًا لمادة «شورى الدولة» في TDV، عُيّن مدحت باشا في أول رئاسة للمؤسسة التي اتُّخذ مجلس الدولة الفرنسي نموذجًا لها؛ وكان الهدف فصل التشريع والتنفيذ والقضاء بعضها عن بعض.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["صدور الإرادة بتأسيس دار الفنون", "513704bf"], "d": ["أُسست دار الفنون رسميًا بإرادة أعدّها الصدر الأعظم عالي باشا وناظر المعارف صفوت باشا؛ وكانت الدروس الأولى قد بدأت قبل ذلك عام 1863. ووفقًا لمادة «دار الفنون» في TDV، بدأت المؤسسة التدريس فعليًا في فبراير 1870 بإدارة خوجه تحسين أفندي، بفروع الفلسفة والأدب والعلوم والحقوق.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["بدء أعمال مجلة الأحكام العدلية", "8abdcbee"], "d": ["شرعت جمعية المجلة، التي تأسست برئاسة أحمد جودت باشا رئيس ديوان الأحكام العدلية، في إعداد قانون مدني يقوم على الفقه الحنفي. ووفقًا لمادة «مجلة الأحكام العدلية» في TDV، اكتمل الجزء الأخير من العمل المؤلف من ستة عشر كتابًا و1851 مادة في 15 سبتمبر 1876 وبدأ العمل به؛ ويُعدّ أول تقنين للفقه الإسلامي.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["تمثيل مسرحية «وطن أو سيليستره» ونفي نامق كمال", "3861284c"], "d": ["لما مُثلت مسرحية نامق كمال الوطنية في مسرح كدك باشا، نزل الجمهور إلى الشوارع هاتفًا «يحيا الوطن، يحيا كمال». ووفقًا لمادة «نامق كمال» في TDV، ذعرت الحكومة من هذا الاستعراض فأغلقت صحيفة «عبرت» ونفت نامق كمال في 6 أبريل 1873 إلى قبرص (ماغوسا) دون محاكمة.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["وفاة عبد العزيز في ظروف مشبوهة", "85816692"], "d": ["عُثر على عبد العزيز، الذي نُقل بإرادته بعد خلعه عن العرش إلى قصر فريّة (1 يونيو 1876)، في 4 يونيو في غرفته وقد قُطعت شرايين معصميه. وأعدّت هيئة أطباء من تسعة عشر شخصًا، شارك فيها أطباء السفارات، تقريرًا غامض العبارة؛ وأُعلن الموت في الصحف في 6 يونيو انتحارًا. أما التحقيق الذي أمر به عبد الحميد الثاني فانتهى إلى أن الوفاة ليست انتحارًا بل جريمة قتل، وحوكم المتهمون عام 1881 في محكمة يلدز؛ والمسألة لا تزال محل جدل في الكتابة التاريخية حتى اليوم.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["عزل مدحت باشا من الصدارة العظمى ونفيه", "b5247b06"], "d": ["عُزل الصدر الأعظم مدحت باشا، مهندس القانون الأساسي، من منصبه على يد عبد الحميد الثاني بعد ستة أسابيع من إعلانه، ونُفي إلى خارج البلاد في ليلة واحدة. ووفقًا لمادة مدحت باشا في موسوعة الإسلام التركية (TDV)، يُربط العزل بانزعاج السلطان من الأحكام التي تقيّد سلطاته في الدستور. وذهب الباشا أولًا إلى نابولي، ثم إلى مدن أوروبية مختلفة.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["استعادة عبد العزيز بن سعود الرياض من آل رشيد", "75eb8830"], "d": ["شنّ عبد العزيز، الشاب من أسرة آل سعود الذي نُفي إلى الكويت قبل عشر سنوات، بمفرزة صغيرة هجومًا على الرياض، وقتل قائم مقام والي آل رشيد (شمّر) واستولى على المدينة. ووفقًا لمادة «الرياض» في موسوعة الإسلام التركية (TDV)، سهّل ضعف آل رشيد المتزايد وعجزهم عن إرسال مدد إلى المدينة نجاح هذا الهجوم؛ ويُعدّ الحدث لحظة تأسيس الدولة السعودية الثانية التي ستشكل في السنوات الثلاثين التالية نواة المملكة العربية السعودية الحالية.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["دخول جيش الحركة إسطنبول", "41c8304c"], "d": ["دخل جيش الحركة، الذي انطلق من سالونيك وتألف في أغلبه من وحدات تابعة لجمعية الاتحاد والترقي، إسطنبول لقمع تمرد 31 مارس. ووفقًا لمادة «جيش الحركة» في موسوعة الإسلام التركية (TDV)، تولى محمود شوكت باشا قيادته، وتولى رئاسة أركانه القائمقام مصطفى كمال. وبعد اشتباكات قصيرة أُعيد الأمن في المدينة.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["حلّ آخر مجلس مبعوثان عثماني", "2b709269"], "d": ["بعد الاحتلال الرسمي لإسطنبول من قوات الوفاق واعتقال كثير من النواب، صار مجلس المبعوثان عاجزًا عن العمل وحُلّ رسميًا بإرادة محمد السادس. ووفقًا لمادة «مجلس المبعوثان» في موسوعة الإسلام التركية (TDV)، رمز هذا الحل إلى نهاية تقليد البرلمان الدستوري العثماني فعليًا. وقد عزز الإغلاق الحاجة إلى انعقاد مجلس وطني جديد في أنقرة.", "4caabf36"]}
});
